1	import Link from "next/link";
2	import { requireArea } from "@/lib/rbac";
3	import { db } from "@/lib/db";
4	import { ServerStatus } from "@prisma/client";
5	import { PageHeader, StatusDot, Badge, fmtMoney, fmtBytes } from "@/components/ui/primitives";
6	import { MeterBar } from "@/components/ui/charts";
7	import { currentRenewalPrices } from "@/lib/admin-metrics";
8	import { serverFleetPriceCents, serverFleetTags, type FleetTag } from "@/lib/admin-fleet";
9	import { dunningConfig } from "@/lib/dunning-config";
10	import { SuspendServerButton, ReconcileServerButton } from "@/components/AdminControls";
11	import { RebootServerButton } from "@/components/admin/ServerAdminActions";
12	import { ServerFleetTable, type FleetColumn, type FleetRow } from "@/components/admin/ServerFleetTable";
13	import { AutoRefresh } from "@/components/AutoRefresh";
14	import { pveForNode, listVms } from "@/lib/proxmox";
15	import { REGION_LABELS, REGION_COUNTRY } from "@/lib/node-regions";
16	import { CountryFlag } from "@/components/ui/CountryFlag";
17	import { resolveServerLifetimeSpendCents } from "@/lib/server-spend";
18	import { GAME_DISPLAY, GAME_ART_SLUG, type GameFamily } from "@/lib/games";
19	
20	export const dynamic = "force-dynamic";
21	
22	const STATUSES = Object.values(ServerStatus);
23	const TRANSITIONAL: ServerStatus[] = ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"];
24	
25	/** Servers renewing within this many days surface in the "expiring soon" alert. */
26	const EXPIRING_SOON_DAYS = 5;
27	
28	/** Archive-backed filters (ServerArchive.reason values), distinct from the live
29	 *  ServerStatus enum above — see prisma schema's ServerArchive doc comment for
30	 *  how `reason` is derived. "Deleted" folds REMOVED in with DELETED: the admin
31	 *  request behind this filter is "show me servers that are gone", and the
32	 *  REMOVED/DELETED distinction is a finer one than that ask needs at a glance. */
33	const ARCHIVE_FILTERS: Record<string, { label: string; reasons: string[] }> = {
34	  CANCELLED: { label: "cancelled", reasons: ["CANCELLED"] },
35	  EXPIRED: { label: "expired", reasons: ["EXPIRED"] },
36	  DELETED: { label: "deleted", reasons: ["REMOVED", "DELETED"] },
37	};
38	
39	/** 24x24 cover thumbnail for a game family, or the game's glyph on a plain
40	 *  background when no poster art exists yet (e.g. a freshly-scaffolded
41	 *  family) — mirrors the "no poster 404s" fallback lib/games.ts itself
42	 *  documents for GAME_ART_SLUG. */
43	function GameCover({ family }: { family: string }) {
44	  const art = GAME_ART_SLUG[family as GameFamily];
45	  const display = GAME_DISPLAY[family as GameFamily];
46	  if (art?.poster) {
47	    return (
48	      <img
49	        src={`/games/art/${art.poster}_poster.jpg`}
50	        alt=""
51	        width={28}
52	        height={28}
53	        className="h-7 w-7 shrink-0 rounded-md object-cover"
54	      />
55	    );
56	  }
57	  return (
58	    <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md bg-white/[0.06] text-sm">
59	      {display?.glyph ?? "🎮"}
60	    </span>
61	  );
62	}
63	
64	/** Plain server-rack icon for a VPS, same stroke style as the sidebar's own
65	 *  "server" glyph (components/portal/Shell.tsx) so the fleet table matches
66	 *  the rest of the admin chrome. */
67	function VpsIcon() {
68	  return (
69	    <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md bg-white/[0.06] text-slate-300">
70	      <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
71	        <rect x="3" y="4" width="18" height="7" rx="2" />
72	        <rect x="3" y="13" width="18" height="7" rx="2" />
73	        <circle cx="7.5" cy="7.5" r="0.8" fill="currentColor" />
74	        <circle cx="7.5" cy="16.5" r="0.8" fill="currentColor" />
75	      </svg>
76	    </span>
77	  );
78	}
79	
80	function ServiceType({ gameFamily }: { gameFamily: string | null }) {
81	  return (
82	    <div className="flex items-center gap-2">
83	      {gameFamily ? <GameCover family={gameFamily} /> : <VpsIcon />}
84	      <Badge tone={gameFamily ? "brand" : "slate"}>{gameFamily ? "Game Server" : "VPS"}</Badge>
85	    </div>
86	  );
87	}
88	
89	function RegionCell({ region }: { region: string | null }) {
90	  if (!region) return <span className="text-xs text-slate-500">—</span>;
91	  const code = REGION_COUNTRY[region];
92	  return (
93	    <span className="flex items-center gap-1.5 text-xs text-slate-400">
94	      {code && <CountryFlag code={code} size={14} />}
95	      {REGION_LABELS[region] ?? region}
96	    </span>
97	  );
98	}
99	
100	export default async function AdminServers({
101	  searchParams,
102	}: {
103	  searchParams: Promise<{ status?: string }>;
104	}) {
105	  await requireArea("fleet");
106	  const { status } = await searchParams;
107	  const archiveFilter = status && ARCHIVE_FILTERS[status] ? status : undefined;
108	  const statusFilter = !archiveFilter && STATUSES.includes(status as ServerStatus) ? (status as ServerStatus) : undefined;
109	
110	  // ── Archive view: a churned server has no live VM, no resources, no actions
111	  //    — a different, simpler table, not the live fleet query below at all. ──
112	  if (archiveFilter) {
113	    const filter = ARCHIVE_FILTERS[archiveFilter];
114	    const [archived, liveCounts, archiveCounts] = await Promise.all([
115	      db.serverArchive.findMany({ where: { reason: { in: filter.reasons } }, orderBy: { deletedAt: "desc" } }),
116	      db.server.count(),
117	      db.serverArchive.groupBy({ by: ["reason"], _count: true }),
118	    ]);
119	    const archiveCountFor = (reasons: string[]) =>
120	      archiveCounts.filter((c) => reasons.includes(c.reason)).reduce((n, c) => n + c._count, 0);
121	
122	    const columns: FleetColumn[] = [
123	      { header: "Hostname" },
124	      { header: "Owner" },
125	      { header: "Type" },
126	      { header: "Service" },
127	      { header: "Node" },
128	      { header: "Region" },
129	      { header: "Total spent" },
130	      { header: "Provisioned" },
131	      { header: "Reason" },
132	      { header: "Removed" },
133	    ];
134	    const rows: FleetRow[] = archived.map((a) => ({
135	      id: a.id,
136	      search: [a.hostname, a.userEmail, a.serviceName, a.nodeName].filter(Boolean).join(" ").toLowerCase(),
137	      cells: [
138	        <span key="h" className="font-medium text-slate-300">{a.hostname}</span>,
139	        a.userId ? (
140	          <Link key="o" href={`/admin/users/${a.userId}`} className="text-slate-300 hover:text-brand-300">
141	            {a.userEmail}
142	          </Link>
143	        ) : (
144	          <span key="o" className="text-slate-500">{a.userEmail || "—"}</span>
145	        ),
146	        <ServiceType key="t" gameFamily={a.gameFamily} />,
147	        <span key="p" className="text-xs">{a.serviceName}</span>,
148	        <span key="n" className="text-xs text-slate-400">{a.nodeName ?? "—"}</span>,
149	        <RegionCell key="r" region={a.region} />,
150	        <span key="sp" className="text-xs">{a.totalSpentCents > 0 ? fmtMoney(a.totalSpentCents) : <span className="text-slate-600">—</span>}</span>,
151	        <span key="prov" className="text-xs text-slate-400">{a.provisionedAt.toISOString().slice(0, 10)}</span>,
152	        <Badge key="reason" tone={a.reason === "CANCELLED" ? "slate" : a.reason === "EXPIRED" ? "amber" : "red"}>
153	          {a.reason.toLowerCase()}
154	        </Badge>,
155	        <span key="del" className="text-xs text-slate-400" title={a.deletedAt.toISOString()}>
156	          {a.deletedAt.toISOString().slice(0, 10)}
157	        </span>,
158	      ],
159	    }));
160	
161	    return (
162	      <div className="space-y-6">
163	        <PageHeader title="Server fleet" sub={`${archived.length} ${filter.label} server${archived.length === 1 ? "" : "s"}.`} />
164	        <StatusChips liveTotal={liveCounts} archiveCountFor={archiveCountFor} active={archiveFilter} liveActive={undefined} />
165	        <ServerFleetTable columns={columns} rows={rows} minWidth={1400} empty={`No ${filter.label} servers.`} />
166	      </div>
167	    );
168	  }
169	
170	  const [servers, counts, archiveCounts] = await Promise.all([
171	    db.server.findMany({
172	      where: statusFilter ? { status: statusFilter } : undefined,
173	      include: {
174	        user: { select: { id: true, email: true, name: true } },
175	        plan: { select: { name: true, priceCents: true } },
176	        gamePlan: { select: { name: true, priceCents: true, termMonths: true, gameFamily: true } },
177	        node: { select: { id: true, name: true, region: true, publicIp: true, apiUrl: true, pveNode: true, tokenId: true, tokenSecret: true } },
178	        // Needed by renewalCharge (via serverFleetPriceCents) to price the
179	        // dedicated-IP add-on, and by serverFleetTags to show the "Dedicated
180	        // IP" tag — only the id, the row's own `dedicatedIp` relation existing
181	        // is all either one reads.
182	        dedicatedIp: { select: { id: true } },
183	      },
184	      orderBy: { createdAt: "desc" },
185	    }),
186	    db.server.groupBy({ by: ["status"], _count: true }),
187	    db.serverArchive.groupBy({ by: ["reason"], _count: true }),
188	  ]);
189	
190	  const countByStatus = new Map(counts.map((c) => [c.status, c._count]));
191	  const total = counts.reduce((n, c) => n + c._count, 0);
192	  const anyTransitional = servers.some((s) => TRANSITIONAL.includes(s.status));
193	  const archiveCountFor = (reasons: string[]) =>
194	    archiveCounts.filter((c) => reasons.includes(c.reason)).reduce((n, c) => n + c._count, 0);
195	
196	  // Real, historical lifetime revenue per server (order + renewals + add-ons,
197	  // net of refunds) — see lib/server-spend.ts for exactly what "real" means
198	  // here and the one verified historical gap it corrects for. Fleet-wide at
199	  // once: 33 servers today, cheap regardless of the status filter above.
200	  const spendByServerId = await resolveServerLifetimeSpendCents(
201	    servers.map((s) => ({
202	      id: s.id,
203	      hostname: s.hostname,
204	      previousHostnames: s.previousHostnames,
205	      userId: s.userId,
206	      createdAt: s.createdAt,
207	    })),
208	  );
209	
210	  // Priced through `renewalCharge` (lib/renewal-charge.ts, via serverFleetPriceCents
211	  // in lib/admin-fleet.ts) — the SAME formula the renewal sweep, the saved-card path
212	  // and "Renew now" charge through, so the Price column can never show a different
213	  // number than what a server is actually billed, add-ons and any grandfathered
214	  // override included. The four admin-priced settings are read ONCE for the whole
215	  // fleet here; pricing each row below is then pure in-memory arithmetic — no
216	  // per-row DB round trip regardless of fleet size.
217	  const renewalPrices = await currentRenewalPrices();
218	  // The real dunning config (lib/dunning-config.ts — the exact function
219	  // worker/billing.ts's own sweep calls) is only needed for the "Deleting soon"
220	  // tag, which only ever applies to a suspended-unpaid row — skip the settings
221	  // reads entirely when the fleet has none.
222	  const hasSuspendedUnpaid = servers.some((s) => s.status === "SUSPENDED" && s.suspendReason === "UNPAID");
223	  const dunningCfg = hasSuspendedUnpaid ? await dunningConfig() : null;
224	
225	  // Live resource metrics, one Proxmox call PER NODE (not per server) — /qemu
226	  // on a node returns every VM's current cpu/mem in one shot, so this stays
227	  // cheap regardless of how many servers are in the fleet. A node's API being
228	  // slow/unreachable only blanks out ITS OWN servers' metrics column, same
229	  // "one node down doesn't take the others with it" discipline as the
230	  // Infrastructure page.
231	  const nodesById = new Map(servers.map((s) => s.node).filter((n): n is NonNullable<typeof n> => !!n).map((n) => [n.id, n]));
232	  const liveByNode = new Map(
233	    await Promise.all(
234	      Array.from(nodesById.values()).map(async (n) => {
235	        try {
236	          const vms = await listVms(pveForNode(n));
237	          const byVmid = new Map(vms.map((v: any) => [v.vmid, v]));
238	          return [n.id, byVmid] as const;
239	        } catch {
240	          return [n.id, null] as const;
241	        }
242	      }),
243	    ),
244	  );
245	
246	  // RAM specifically comes from the worker-collected guest-agent sample
247	  // (ServerMemSample), not the live `mem`/`maxmem` above — those balloon-stat
248	  // fields are MemFree-based, not MemAvailable-based, so a VM with ordinary
249	  // disk/page-cache activity reads falsely high "memory used" even with
250	  // plenty of genuinely spare RAM (confirmed against a real running server:
251	  // balloon said ~90% used, the guest's own free -h said ~25%). CPU stays
252	  // live above since that reading has no such distortion.
253	  const memSampleByServerId = new Map(
254	    await Promise.all(
255	      servers.map(async (s) => {
256	        const sample = await db.serverMemSample.findFirst({
257	          where: { serverId: s.id },
258	          orderBy: { ts: "desc" },
259	          select: { usedBytes: true, totalBytes: true },
260	        });
261	        return [s.id, sample] as const;
262	      }),
263	    ),
264	  );
265	
266	  // "Expiring soon": due for renewal within EXPIRING_SOON_DAYS, still actually
267	  // in play (not free, not already on its way out). A server already SUSPENDED
268	  // or DELETING is already being handled by the dunning flow — surfacing it
269	  // here too would just be noise on top of its own status chip.
270	  const now = Date.now();
271	  const soonCutoff = now + EXPIRING_SOON_DAYS * 24 * 60 * 60 * 1000;
272	  const expiringSoon = servers.filter(
273	    (s) =>
274	      !s.isFree &&
275	      s.status !== "SUSPENDED" &&
276	      s.status !== "DELETING" &&
277	      s.expiresAt &&
278	      s.expiresAt.getTime() >= now &&
279	      s.expiresAt.getTime() <= soonCutoff,
280	  ).sort((a, b) => a.expiresAt!.getTime() - b.expiresAt!.getTime());
281	
282	  return (
283	    <div className="space-y-6">
284	      {anyTransitional && <AutoRefresh />}
285	      <PageHeader title="Server fleet" sub={`${total} server${total === 1 ? "" : "s"} across all clients.`} />
286	
287	      {expiringSoon.length > 0 && (
288	        <div className="rounded-xl border border-amber-500/30 bg-amber-500/[0.07] px-4 py-3">
289	          <div className="flex flex-wrap items-center gap-2 text-sm text-amber-300">
290	            <span className="font-medium">
291	              {expiringSoon.length} server{expiringSoon.length === 1 ? "" : "s"} renewing within {EXPIRING_SOON_DAYS} days
292	            </span>
293	          </div>
294	          <div className="mt-2 flex flex-wrap gap-x-4 gap-y-1 text-xs text-amber-300/80">
295	            {expiringSoon.slice(0, 8).map((s) => (
296	              <Link key={s.id} href={`/admin/servers/${s.id}`} className="hover:text-amber-200 hover:underline">
297	                {s.hostname} · {s.expiresAt!.toISOString().slice(0, 10)}
298	              </Link>
299	            ))}
300	            {expiringSoon.length > 8 && <span>+{expiringSoon.length - 8} more</span>}
301	          </div>
302	        </div>
303	      )}
304	
305	      {/* Status filter chips */}
306	      <StatusChips
307	        liveTotal={total}
308	        countByStatus={countByStatus}
309	        archiveCountFor={archiveCountFor}
310	        liveActive={statusFilter}
311	        active={undefined}
312	      />
313	
314	      {(() => {
315	        const columns: FleetColumn[] = [
316	          { header: "Hostname" },
317	          { header: "Owner" },
318	          { header: "Type" },
319	          { header: "Plan" },
320	          { header: "VMID" },
321	          { header: "SSH endpoint" },
322	          { header: "Node" },
323	          { header: "Region" },
324	          { header: "Provisioned" },
325	          { header: "Total spent" },
326	          { header: "Resources", className: "min-w-40" },
327	          { header: "Status" },
328	          { header: "Expires" },
329	          { header: "Actions", className: "text-right" },
330	        ];
331	
332	        const rows: FleetRow[] = servers.map((s) => {
333	          const gameFamily = s.gamePlan?.gameFamily ?? null;
334	          const planName = s.gamePlan ? s.gamePlan.name : s.plan.name;
335	          const search = [s.hostname, s.user.email, s.user.name, planName, s.node?.name, s.node ? REGION_LABELS[s.node.region] ?? s.node.region : null]
336	            .filter(Boolean)
337	            .join(" ")
338	            .toLowerCase();
339	          const spentCents = spendByServerId.get(s.id) ?? 0;
340	          // Real total renewal price (add-ons + any grandfathered override) and
341	          // small lifecycle tags — see lib/admin-fleet.ts for what each one means
342	          // and where its definition is lifted from.
343	          const priceMonthlyCents = serverFleetPriceCents(s, renewalPrices);
344	          const tags: FleetTag[] = serverFleetTags(s, {
345	            now: new Date(now),
346	            renewingSoonWindowMs: EXPIRING_SOON_DAYS * 24 * 60 * 60 * 1000,
347	            dunning: dunningCfg,
348	          });
349	          return {
350	            id: s.id,
351	            search,
352	            cells: [
353	              <span key="h">
354	                <Link href={`/admin/servers/${s.id}`} className="font-medium hover:text-brand-300">
355	                  {s.hostname}
356	                </Link>
357	                {(s.isFree || tags.length > 0) && (
358	                  <div className="mt-1 flex flex-wrap gap-1">
359	                    {s.isFree && <Badge tone="green">free</Badge>}
360	                    {tags.map((t) => (
361	                      <span key={t.key} title={t.title}>
362	                        <Badge tone={t.tone}>{t.label}</Badge>
363	                      </span>
364	                    ))}
365	                  </div>
366	                )}
367	              </span>,
368	              <Link key="o" href={`/admin/users/${s.user.id}`} className="text-slate-300 hover:text-brand-300">
369	                {s.user.email}
370	              </Link>,
371	              <ServiceType key="type" gameFamily={gameFamily} />,
372	              <span key="p">
373	                {planName}
374	                {!s.isFree && (
375	                  <span className="text-xs text-slate-500">
376	                    {" "}
377	                    · {fmtMoney(priceMonthlyCents)}/mo
378	                  </span>
379	                )}
380	              </span>,
381	              <span key="v" className="font-mono text-xs">{s.vmid ?? "—"}</span>,
382	              <span key="ssh" className="font-mono text-xs">
383	                {/* The CONNECTABLE endpoint: NAT servers reach the VM through the node's
384	                    PUBLIC ip + the forwarded ssh port — never the internal 10.20.x.x
385	                    address (that's unreachable from outside the host). Show the public
386	                    endpoint like the customer dashboard does; keep the internal ip as a
387	                    muted secondary line for admin NAT debugging. */}
388	                {s.sshPort ? (
389	                  <>
390	                    <span>{`${s.node?.publicIp ?? process.env.PUBLIC_IP ?? "—"}:${s.sshPort}`}</span>
391	                    {s.ipAddress && <div className="text-slate-600">int {s.ipAddress}</div>}
392	                  </>
393	                ) : (
394	                  s.ipAddress ?? "—"
395	                )}
396	              </span>,
397	              <span key="n" className="text-xs">
398	                {s.node ? (
399	                  <Link href={`/admin/nodes/${s.node.id}`} className="hover:text-brand-300">
400	                    {s.node.name}
401	                  </Link>
402	                ) : (
403	                  "—"
404	                )}
405	              </span>,
406	              <RegionCell key="r" region={s.node?.region ?? null} />,
407	              <span key="prov" className="text-xs text-slate-400" title={s.createdAt.toISOString()}>
408	                {s.createdAt.toISOString().slice(0, 10)}
409	              </span>,
410	              <span key="spend" className="text-xs" title="Real lifetime total: order + renewals + add-ons, net of refunds — not an estimate">
411	                {spentCents > 0 ? fmtMoney(spentCents) : <span className="text-slate-600">—</span>}
412	              </span>,
413	              <span key="res">
414	                {(() => {
415	                  const live = s.vmid && s.node ? liveByNode.get(s.node.id)?.get(s.vmid) : null;
416	                  if (!live) {
417	                    return <span className="text-xs text-slate-600">{s.vmid ? "unavailable" : "—"}</span>;
418	                  }
419	                  const cpuPct = Math.round((live.cpu ?? 0) * 100);
420	                  const memSample = memSampleByServerId.get(s.id);
421	                  const memUsed = memSample ? Number(memSample.usedBytes) : 0;
422	                  const memTotal = memSample ? Number(memSample.totalBytes) : 0;
423	                  const memRatio = memTotal > 0 ? memUsed / memTotal : 0;
424	                  return (
425	                    <div className="space-y-1.5">
426	                      <div className="flex items-center justify-between gap-2 text-[11px] text-slate-500">
427	                        <span>CPU</span>
428	                        <span className="font-mono">{cpuPct}%</span>
429	                      </div>
430	                      <MeterBar value={cpuPct} max={100} color={cpuPct > 90 ? "#ef4444" : cpuPct > 75 ? "#f59e0b" : "#34d399"} />
431	                      <div className="flex items-center justify-between gap-2 text-[11px] text-slate-500">
432	                        <span>RAM</span>
433	                        <span className="font-mono">
434	                          {memSample && memTotal > 0 ? (
435	                            `${fmtBytes(memUsed)} / ${fmtBytes(memTotal)}`
436	                          ) : (
437	                            <span className="text-slate-600">— not measured yet</span>
438	                          )}
439	                        </span>
440	                      </div>
441	                      {memSample && memTotal > 0 && (
442	                        <MeterBar
443	                          value={memUsed}
444	                          max={memTotal || 1}
445	                          color={memRatio > 0.9 ? "#ef4444" : memRatio > 0.75 ? "#f59e0b" : "#34d399"}
446	                        />
447	                      )}
448	                    </div>
449	                  );
450	                })()}
451	              </span>,
452	              <StatusDot key="s" status={s.status} />,
453	              <span key="e" className="text-xs">
454	                {s.isFree ? "never" : s.expiresAt ? s.expiresAt.toISOString().slice(0, 10) : "—"}
455	              </span>,
456	              <div key="a" className="flex flex-wrap items-center justify-end gap-2">
457	                {(["ERROR", "PENDING", "PROVISIONING"] as ServerStatus[]).includes(s.status) && (
458	                  <ReconcileServerButton serverId={s.id} />
459	                )}
460	                {s.status !== "DELETING" && <RebootServerButton serverId={s.id} status={s.status} />}
461	                {s.status !== "DELETING" && (
462	                  <SuspendServerButton serverId={s.id} suspended={s.status === "SUSPENDED"} />
463	                )}
464	              </div>,
465	            ],
466	          };
467	        });
468	
469	        return (
470	          <ServerFleetTable
471	            columns={columns}
472	            rows={rows}
473	            minWidth={1900}
474	            empty={`No servers${statusFilter ? ` in status ${statusFilter.toLowerCase()}` : " yet"}.`}
475	          />
476	        );
