6	/**
7	 * Poll one ADMIN_OPS job until it is DONE/FAILED. `jobId` null = idle.
8	 * Backs off from 1.5s to 4s so a long op (bulk, drift) doesn't hammer the DB.
9	 */
10	export function useOpJob(jobId: string | null, initial: OpJobView | null = null) {
11	  const [job, setJob] = useState<OpJobView | null>(initial);
12	  const tries = useRef(0);
13	  useEffect(() => {
14	    if (!jobId) return;
15	    let alive = true;
16	    tries.current = 0;
17	    const tick = async () => {
18	      const j = await getOpJob(jobId).catch(() => null);
19	      if (!alive) return;
20	      if (j) setJob(j);
21	      if (!j || (j.status !== "DONE" && j.status !== "FAILED")) {
22	        tries.current++;
23	        setTimeout(tick, Math.min(4000, 1500 + tries.current * 250));
24	      }
25	    };
26	    tick();
27	    return () => {
28	      alive = false;
29	    };
30	  }, [jobId]);
31	  const busy = !!jobId && (!job || job.id !== jobId || job.status === "QUEUED" || job.status === "RUNNING");
32	  return { job, busy };
33	}
