35	export function useAction<A extends unknown[], R>(fn: (...a: A) => Promise<R>) {
36	  const [pending, setPending] = useState(false);
37	  const run = useCallback(
38	    async (...a: A): Promise<R | null> => {
39	      setPending(true);
40	      try {
41	        return await fn(...a);
42	      } catch (e) {
43	        return { ok: false, error: String((e as Error)?.message ?? e) } as unknown as R;
44	      } finally {
45	        setPending(false);
46	      }
47	    },
48	    [fn],
49	  );
50	  return { run, pending };
51	}
