import { headers } from "next/headers";
import { db } from "./db";
import { impersonating } from "./auth";
import { clientIp, UNKNOWN_IP } from "./rate-limit";

/**
 * The single shared audit-log writer. Extracted verbatim (same body, same
 * impersonation-attribution logic) from what was a private, unexported
 * `audit()` in lib/actions.ts used by only ~19 call sites in that one file —
 * every other lib/actions-*.ts module wrote `db.auditLog.create(...)` ad hoc,
 * so coverage of "what did staff actually do" was inconsistent by
 * construction. New staff-reachable modules (lib/actions-work.ts,
 * lib/actions-staff.ts's grant/IP changes) call this directly so an
 * EMPLOYEE's activity is captured with the same discipline as everything
 * else, from day one.
 *
 * 2026-10-01 (docs/AUDIT-7D-2026-10-01.md F-15): `AuditLog.ip` exists in the
 * schema but nothing ever populated it — every one of the 24
 * `admin.impersonate_start` and 10 `admin.renew_now` rows in the last 7 days
 * had `ip = NULL`, so a hijacked staff session could not be told apart from
 * the real admin after the fact. The writer now records the proxy-validated
 * client IP (the same `clientIp()` the login throttle trusts) whenever it runs
 * inside a request. `headers()` throws outside a request scope (worker,
 * scripts, tests) — that is swallowed and the row is written without an IP,
 * exactly as before, so no caller's behaviour changes.
 */
export async function recordAudit(userId: string | null, action: string, detail?: string): Promise<void> {
  // Attribute to the real admin when an admin is impersonating, so customer-scoped
  // actions taken during impersonation aren't logged as if the customer did them.
  const imp = await impersonating();
  const actor = imp ? `actingAdmin=${imp.admin.id}` : "";
  const fullDetail = detail && actor ? `${detail} ${actor}` : detail || actor || undefined;
  const ip = await requestIp();
  await db.auditLog.create({ data: { userId, action, detail: fullDetail, ...(ip ? { ip } : {}) } });
}

/** The caller's validated IP when inside a request; null anywhere else. */
async function requestIp(): Promise<string | null> {
  try {
    const ip = clientIp(await headers());
    return ip === UNKNOWN_IP ? null : ip;
  } catch {
    return null;
  }
}
import net from "node:net";

/**
 * Dependency-free, in-memory sliding-window rate limiter.
 *
 * Suitable for single-process app-level throttling (login attempts, etc).
 * State lives in a module-level Map; on a horizontally-scaled deployment each
 * instance limits independently — acceptable for auth-abuse mitigation. A
 * background sweep prunes empty buckets so the Map does not grow unbounded.
 */

type Bucket = number[]; // sorted-ish list of hit timestamps (ms)

const buckets = new Map<string, Bucket>();

// Persist the Map across HMR / route reloads in dev.
const globalForRl = globalThis as unknown as { __nxeonRateLimit?: Map<string, Bucket> };
const store: Map<string, Bucket> = globalForRl.__nxeonRateLimit ?? buckets;
if (process.env.NODE_ENV !== "production") globalForRl.__nxeonRateLimit = store;

export type RateLimitOptions = { max: number; windowMs: number };
export type RateLimitResult = { ok: boolean; retryAfterSec: number; remaining: number };

/**
 * The widest window any caller has ever asked for.
 *
 * The sweep below used a HARDCODED 15-minute horizon while callers pass windows
 * far longer than that — `RESEND_LIMIT` in lib/email-verification.ts is an hour,
 * as are the mail-send, calendar-mutation, org-invite and wallet-top-up limits.
 * A bucket whose last hit was 16 minutes ago was therefore DELETED, and deleting
 * a bucket resets its counter: "5 verification emails per hour" was really "5
 * per 15 minutes, forever", and "60 outbound mails per hour" was 60 per quarter
 * hour. The limiter silently enforced a limit nobody had chosen, and the longer
 * the window a caller asked for, the less of it was honoured.
 *
 * Tracking the real maximum keeps the sweep's only job — bounding the Map — from
 * quietly becoming a policy decision. It only ever grows, so it can never evict a
 * bucket that some caller still considers live.
 */
let widestWindowMs = 15 * 60 * 1000;

/**
 * Record and check a hit for `key`. Returns `{ ok, retryAfterSec, remaining }`.
 * When `ok` is false the caller should reject and surface `retryAfterSec`.
 */
export function checkRateLimit(key: string, { max, windowMs }: RateLimitOptions): RateLimitResult {
  const now = Date.now();
  if (windowMs > widestWindowMs) widestWindowMs = windowMs;
  sweep(now);
  const cutoff = now - windowMs;
  const hits = (store.get(key) ?? []).filter((t) => t > cutoff);

  if (hits.length >= max) {
    const oldest = hits[0];
    const retryAfterSec = Math.max(1, Math.ceil((oldest + windowMs - now) / 1000));
    store.set(key, hits); // persist the pruned window
    return { ok: false, retryAfterSec, remaining: 0 };
  }

  hits.push(now);
 * One-shot claim on `key`, valid for `ttlMs`. True the first time, false every
 * time after. Built on the same window store, so it inherits the same
 * single-process caveat documented at the top of this file.
 *
 * Used to make a TOTP code single-use (see lib/totp-verify.ts).
 */
export function claimOnce(key: string, ttlMs: number): boolean {
  return checkRateLimit(`once:${key}`, { max: 1, windowMs: ttlMs }).ok;
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { stripComments } from "./_source-tools.ts";

/**
 * Structural guard over lib/admin-ops/actions.ts — the same net
 * test/admin-actions-guards.test.ts casts over the older admin modules: every
 * export of a "use server" file is a public endpoint, so every one must reach
 * for STAFF authority (via the module's `gate()`, which is requireArea +
 * assertNotImpersonating) as its first statement.
 */
const SRC = stripComments(readFileSync(join(import.meta.dirname, "..", "lib", "admin-ops", "actions.ts"), "utf8"));

test("admin-ops actions module declares use server", () => {
  assert.ok(SRC.trimStart().startsWith('"use server"'));
});

test("gate() is requireArea + assertNotImpersonating", () => {
  const m = /async function gate\([^)]*\)\s*\{([\s\S]*?)\n\}/.exec(SRC);
  assert.ok(m, "gate() helper exists");
  assert.match(m![1], /requireArea\(/);
  assert.match(m![1], /assertNotImpersonating\(/);
});

test("every exported action calls gate() before anything else", () => {
  const exported = [...SRC.matchAll(/export\s+async\s+function\s+([A-Za-z0-9_]+)\s*\(/g)].map((m) => ({ name: m[1], index: m.index! }));
  assert.ok(exported.length >= 20, `expected the full action surface, found ${exported.length}`);
  const offenders: string[] = [];
  for (const { name, index } of exported) {
    const bodyStart = SRC.indexOf("{", SRC.indexOf(")", SRC.indexOf("(", index)) + 1);
    // skip past a return-type annotation that itself contains braces: find the
    // first "{" that is followed (after whitespace) by a statement.
