/**
 * "State truth" for one server — PURE (no db / proxmox / next imports) so it is
 * unit-tested in test/admin-server-360.test.ts and shared by the admin server
 * page's Overview tab and the fleet list's per-row health dot.
 *
 * Three sources can each claim to know whether a server is up:
 *   1. the DB row        (Server.status — what billing, the portal and the worker act on)
 *   2. Proxmox           (qemu status — whether the VM is actually running on its node)
 *   3. the game runtime  (GameRuntime.state — whether the GAME inside is actually up)
 *
 * They disagree in real life (a VM crashed but the row still says RUNNING; a
 * suspended server whose VM someone started by hand; a game that died inside a
 * healthy VM). The admin page shows all three side by side and lists every
 * disagreement as a Mismatch with a severity and, where one exists, the fix the
 * existing ops library already knows how to apply (lib/admin-ops FixKey names).
 *
 * Never invents a reading: an unreachable/absent source is shown as exactly that,
 * and only produces an "info" note, never a mismatch.
 */

export type TruthTone = "ok" | "info" | "warn" | "bad" | "muted";

export type ProxmoxReading =
  /** the server has no vmid yet — nothing to ask Proxmox about */
  | { kind: "none" }
  /** the node API did not answer (timeout / auth / network) */
  | { kind: "unreachable"; error?: string }
  /** the node answered and the vmid does not exist there */
  | { kind: "missing" }
  | { kind: "vm"; status: string; uptimeSec?: number | null; lock?: string | null };

export type RuntimeReading = {
  state: string | null;
  probedAt: Date | null;
  intent: string | null;
  probeError?: string | null;
} | null;

export type StateTruthInput = {
  dbStatus: string;
  provisionError?: string | null;
  suspendReason?: string | null;
  isGame: boolean;
  proxmox: ProxmoxReading;
  runtime: RuntimeReading;
  /** the in-flight job, if any (QUEUED/RUNNING) */
  activeJob: { type: string; status: string; updatedAt: Date } | null;
  /** last time the server row changed state (Server.updatedAt) */
  updatedAt: Date;
  now?: Date;
};

export type SourceView = { key: "db" | "proxmox" | "runtime"; label: string; value: string; tone: TruthTone; detail?: string };

export type MismatchSeverity = "critical" | "warning" | "info";

export type Mismatch = {
  code: string;
  severity: MismatchSeverity;
  message: string;
  /** an existing fix (lib/admin-ops/diagnose-rules FixKey vocabulary) when one applies */
  fix?: "reconcile" | "start" | "diagnose" | "restart_game" | "sync_forwards";
};

export type StateTruth = {
  sources: SourceView[];
  mismatches: Mismatch[];
  /** the single worst tone across everything — drives the list's health dot */
  health: "ok" | "warn" | "bad" | "unknown";
};

/** Transitional DB states that should always have a job behind them. */
export const TRANSITIONAL_STATUSES = new Set(["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"]);
/** A transitional state with no job for this long is "stuck". */
export const STUCK_TRANSITION_MS = 30 * 60_000;
/** A game probe older than this is not evidence of anything. */
export const RUNTIME_STALE_MS = 15 * 60_000;

const GAME_DOWN = new Set(["game_stopped", "crashed", "not_responding"]);
const GAME_UP = new Set(["online", "unverified", "starting"]);

function dbTone(s: string): TruthTone {
  if (s === "RUNNING") return "ok";
  if (s === "ERROR") return "bad";
  if (s === "SUSPENDED") return "warn";
  if (TRANSITIONAL_STATUSES.has(s)) return "info";
  return "muted";
}

export function evaluateStateTruth(input: StateTruthInput): StateTruth {
  const now = input.now ?? new Date();
  const sources: SourceView[] = [];
  const mismatches: Mismatch[] = [];
  const db = input.dbStatus;

  sources.push({
    key: "db",
    label: "Database",
    value: db.toLowerCase(),
    tone: dbTone(db),
    detail: db === "ERROR" ? input.provisionError ?? undefined : db === "SUSPENDED" ? input.suspendReason ?? undefined : undefined,
  });

  // ── Proxmox ───────────────────────────────────────────────────────────────
  const pve = input.proxmox;
  let vmRunning: boolean | null = null;
  if (pve.kind === "none") {
    sources.push({ key: "proxmox", label: "Proxmox", value: "no VM yet", tone: "muted" });
  } else if (pve.kind === "unreachable") {
    sources.push({ key: "proxmox", label: "Proxmox", value: "unreachable", tone: "muted", detail: pve.error });
    mismatches.push({ code: "pve_unreachable", severity: "info", message: "The node API did not answer, so the VM's real state could not be checked." });
  } else if (pve.kind === "missing") {
    sources.push({ key: "proxmox", label: "Proxmox", value: "VM not found", tone: "bad" });
    if (db !== "DELETING" && db !== "PENDING") {
      mismatches.push({
        code: "vm_missing",
        severity: "critical",
        message: "The database has a vmid for this server but the node has no such VM.",
        fix: "diagnose",
      });
    }
  } else {
    vmRunning = pve.status === "running";
    sources.push({
      key: "proxmox",
      label: "Proxmox",
      value: pve.lock ? `${pve.status} (locked: ${pve.lock})` : pve.status,
      tone: vmRunning ? "ok" : "muted",
    });
    if (db === "RUNNING" && !vmRunning) {
      mismatches.push({ code: "db_running_vm_stopped", severity: "critical", message: "The database says RUNNING but the VM is not running on its node.", fix: "reconcile" });
    } else if (db === "STOPPED" && vmRunning) {
      mismatches.push({ code: "db_stopped_vm_running", severity: "warning", message: "The database says STOPPED but the VM is running.", fix: "reconcile" });
    } else if (db === "SUSPENDED" && vmRunning) {
      mismatches.push({ code: "suspended_vm_running", severity: "critical", message: "The server is SUSPENDED but its VM is running — the suspension is not being enforced." });
    } else if (db === "ERROR" && vmRunning) {
      mismatches.push({ code: "error_vm_running", severity: "warning", message: "The row is in ERROR but the VM is running — reconcile may recover it.", fix: "reconcile" });
    }
  }

  // ── Game runtime ──────────────────────────────────────────────────────────
  if (input.isGame) {
    const rt = input.runtime;
    const stale = !rt?.probedAt || now.getTime() - rt.probedAt.getTime() > RUNTIME_STALE_MS;
    if (!rt || !rt.state) {
      sources.push({ key: "runtime", label: "Game runtime", value: "never probed", tone: "muted" });
    } else {
      const label = rt.state.replace(/_/g, " ");
      sources.push({
        key: "runtime",
        label: "Game runtime",
        value: stale ? `${label} (stale)` : label,
        tone: stale ? "muted" : GAME_UP.has(rt.state) ? "ok" : GAME_DOWN.has(rt.state) ? "bad" : "muted",
        detail: rt.probeError ?? undefined,
      });
      if (!stale) {
        const vmUp = vmRunning ?? db === "RUNNING";
        if (vmUp && GAME_DOWN.has(rt.state) && rt.intent !== "stopped") {
          mismatches.push({
            code: "game_down",
            severity: "warning",
            message: `The VM is up but the game is ${label} and nobody asked for it to stop.`,
            fix: "restart_game",
          });
        }
        if (db === "STOPPED" && GAME_UP.has(rt.state)) {
          mismatches.push({ code: "db_stopped_game_up", severity: "warning", message: "The database says STOPPED but the game answered a recent probe.", fix: "reconcile" });
        }
      } else if (db === "RUNNING") {
        mismatches.push({ code: "runtime_stale", severity: "info", message: "The last game probe is older than 15 minutes; the game state shown may be out of date." });
      }
    }
  }

  // ── Stuck transitions ─────────────────────────────────────────────────────
  if (TRANSITIONAL_STATUSES.has(db) && !input.activeJob && now.getTime() - input.updatedAt.getTime() > STUCK_TRANSITION_MS) {
    mismatches.push({ code: "stuck_transition", severity: "warning", message: `${db.toLowerCase()} for over 30 minutes with no job running.`, fix: "reconcile" });
  }
  if (db === "ERROR" && !mismatches.some((m) => m.code === "error_vm_running")) {
    mismatches.push({ code: "status_error", severity: "critical", message: input.provisionError ? `ERROR: ${input.provisionError}` : "The server is in ERROR.", fix: "diagnose" });
  }

  const health: StateTruth["health"] = mismatches.some((m) => m.severity === "critical")
    ? "bad"
    : mismatches.some((m) => m.severity === "warning")
      ? "warn"
      : pve.kind === "unreachable" && !input.isGame
        ? "unknown"
        : "ok";

  return { sources, mismatches, health };
}

/**
 * The DB-only subset of the above, for the fleet list's "mismatch" filter and
 * health dot when no live Proxmox reading is at hand. Returns the same codes.
 */
export function dbOnlyHealth(input: Omit<StateTruthInput, "proxmox">): StateTruth {
  return evaluateStateTruth({ ...input, proxmox: { kind: "none" } });
}

