    mismatches.push({ code: "pve_unreachable", severity: "info", message: "The node API did not answer, so the VM's real state could not be checked." });
  } else if (pve.kind === "missing") {
    sources.push({ key: "proxmox", label: "Proxmox", value: "VM not found", tone: "bad" });
    if (db !== "DELETING" && db !== "PENDING") {
      mismatches.push({
        code: "vm_missing",
        severity: "critical",
        message: "The database has a vmid for this server but the node has no such VM.",
        fix: "diagnose",
      });
    }
  } else {
    vmRunning = pve.status === "running";
    sources.push({
      key: "proxmox",
      label: "Proxmox",
      value: pve.lock ? `${pve.status} (locked: ${pve.lock})` : pve.status,
      tone: vmRunning ? "ok" : "muted",
    });
    if (db === "RUNNING" && !vmRunning) {
      mismatches.push({ code: "db_running_vm_stopped", severity: "critical", message: "The database says RUNNING but the VM is not running on its node.", fix: "reconcile" });
    } else if (db === "STOPPED" && vmRunning) {
      mismatches.push({ code: "db_stopped_vm_running", severity: "warning", message: "The database says STOPPED but the VM is running.", fix: "reconcile" });
    } else if (db === "SUSPENDED" && vmRunning) {
      mismatches.push({ code: "suspended_vm_running", severity: "critical", message: "The server is SUSPENDED but its VM is running — the suspension is not being enforced." });
    } else if (db === "ERROR" && vmRunning) {
      mismatches.push({ code: "error_vm_running", severity: "warning", message: "The row is in ERROR but the VM is running — reconcile may recover it.", fix: "reconcile" });
    }
  }

  // ── Game runtime ──────────────────────────────────────────────────────────
  if (input.isGame) {
    const rt = input.runtime;
    const stale = !rt?.probedAt || now.getTime() - rt.probedAt.getTime() > RUNTIME_STALE_MS;
    if (!rt || !rt.state) {
      sources.push({ key: "runtime", label: "Game runtime", value: "never probed", tone: "muted" });
    } else {
      const label = rt.state.replace(/_/g, " ");
      sources.push({
        key: "runtime",
        label: "Game runtime",
        value: stale ? `${label} (stale)` : label,
        tone: stale ? "muted" : GAME_UP.has(rt.state) ? "ok" : GAME_DOWN.has(rt.state) ? "bad" : "muted",
        detail: rt.probeError ?? undefined,
      });
      if (!stale) {
        const vmUp = vmRunning ?? db === "RUNNING";
        if (vmUp && GAME_DOWN.has(rt.state) && rt.intent !== "stopped") {
          mismatches.push({
            code: "game_down",
            severity: "warning",
            message: `The VM is up but the game is ${label} and nobody asked for it to stop.`,
            fix: "restart_game",
          });
        }
        if (db === "STOPPED" && GAME_UP.has(rt.state)) {
          mismatches.push({ code: "db_stopped_game_up", severity: "warning", message: "The database says STOPPED but the game answered a recent probe.", fix: "reconcile" });
        }
      } else if (db === "RUNNING") {
        mismatches.push({ code: "runtime_stale", severity: "info", message: "The last game probe is older than 15 minutes; the game state shown may be out of date." });
      }
    }
  }

  // ── Stuck transitions ─────────────────────────────────────────────────────
  if (TRANSITIONAL_STATUSES.has(db) && !input.activeJob && now.getTime() - input.updatedAt.getTime() > STUCK_TRANSITION_MS) {
    mismatches.push({ code: "stuck_transition", severity: "warning", message: `${db.toLowerCase()} for over 30 minutes with no job running.`, fix: "reconcile" });
  }
  if (db === "ERROR" && !mismatches.some((m) => m.code === "error_vm_running")) {
    mismatches.push({ code: "status_error", severity: "critical", message: input.provisionError ? `ERROR: ${input.provisionError}` : "The server is in ERROR.", fix: "diagnose" });
  }

  const health: StateTruth["health"] = mismatches.some((m) => m.severity === "critical")
    ? "bad"
    : mismatches.some((m) => m.severity === "warning")
      ? "warn"
      : pve.kind === "unreachable" && !input.isGame
        ? "unknown"
        : "ok";

  return { sources, mismatches, health };
}

/**
 * The DB-only subset of the above, for the fleet list's "mismatch" filter and
 * health dot when no live Proxmox reading is at hand. Returns the same codes.
 */
export function dbOnlyHealth(input: Omit<StateTruthInput, "proxmox">): StateTruth {
  return evaluateStateTruth({ ...input, proxmox: { kind: "none" } });
}

