/**
 * Transfer / Move tab — target-node evaluation. PURE (unit-tested).
 *
 * This does NOT plan or run a move; the VM move engine (lib/vm-move, branch
 * feature/vm-node-migration) owns that and its dry-run preview is the
 * authoritative answer. This only ranks the candidate TARGET nodes for one
 * server with real capacity numbers so an admin can see, before even asking
 * for a dry run, which nodes would obviously refuse and why.
 *
 * The rules mirror the engine's own preflight (lib/vm-move/plan.ts
 * capacityChecks + the addressing checks) so the two never tell the admin
 * different stories:
 *   - target must be a different node, enabled and ONLINE
 *   - committed RAM after the move must stay under the node's capacityRamMB
 *   - real free RAM after the move must leave >= TARGET_RESERVE_MB
 *   - a dedicated IP can only follow the VM within the same region (the
 *     engine's cheap pre-filter; the authoritative same-campus answer comes
 *     from the upstream IP-move destination list during the dry run)
 * plus the platform's own pinned-RAM guard (lib/vm-memory-policy
 * ramGuardVerdict) which is blocking only when NXEON_RAM_GUARD=enforce.
 */

export const TARGET_RESERVE_MB = 4096;

export type TargetNodeInput = {
  id: string;
  name: string;
  region: string;
  provider: string;
  enabled: boolean;
  status: string;
  acceptsProvisions: boolean;
  capacityRamMB: number;
  /** Σ plan RAM of the node's non-DELETING servers (DB) */
  committedRamMB: number;
  /** live Proxmox node memory; null when the node API did not answer */
  realTotalRamMB: number | null;
  realUsedRamMB: number | null;
  /** pinned-RAM guard verdict for adding this VM (null = unknown) */
  guard: { ok: boolean; reason: string | null; projectedGuaranteedPct: number; projectedRealPct: number } | null;
};

export type MoveServerInput = {
  nodeId: string | null;
  region: string | null;
  provider: string | null;
  planRamMB: number;
  hasDedicatedIp: boolean;
  /** current public endpoint for NAT servers, e.g. node publicIp */
  publicIp: string | null;
};

export type TargetEvaluation = {
  nodeId: string;
  name: string;
  region: string;
  eligible: boolean;
  blockers: string[];
  warnings: string[];
  committedPctNow: number;
  committedPctAfter: number;
  realFreeAfterMB: number | null;
  realPctAfter: number | null;
  /** what the customer-visible address does after the move */
  addressChange: string;
};

const pct = (n: number, d: number) => (d > 0 ? Math.round((n / d) * 1000) / 10 : 0);

export function evaluateMoveTargets(
  server: MoveServerInput,
  nodes: TargetNodeInput[],
  opts: { guardMode: "enforce" | "warn" | "off"; targetPublicIp?: (nodeId: string) => string | null },
): TargetEvaluation[] {
  const out: TargetEvaluation[] = [];
  for (const n of nodes) {
    if (n.id === server.nodeId) continue;
    const blockers: string[] = [];
    const warnings: string[] = [];
    if (!n.enabled) blockers.push("Node is disabled.");
    if (n.status !== "ONLINE") blockers.push(`Node is ${n.status.toLowerCase()}, not online.`);
    if (!n.acceptsProvisions) warnings.push("Node is draining (not accepting new provisions).");

    const committedAfter = n.committedRamMB + server.planRamMB;
    const committedPctAfter = pct(committedAfter, n.capacityRamMB);
    if (n.capacityRamMB <= 0) blockers.push("Node has no RAM capacity configured.");
    else if (committedPctAfter >= 100) blockers.push(`Committed RAM would reach ${committedPctAfter}% of the node's ${Math.round(n.capacityRamMB / 1024)} GB capacity.`);
    else if (committedPctAfter >= 90) warnings.push(`Committed RAM would be ${committedPctAfter}% of capacity.`);

    let realFreeAfterMB: number | null = null;
    let realPctAfter: number | null = null;
    if (n.realTotalRamMB != null && n.realUsedRamMB != null) {
      realFreeAfterMB = n.realTotalRamMB - n.realUsedRamMB - server.planRamMB;
      realPctAfter = pct(n.realUsedRamMB + server.planRamMB, n.realTotalRamMB);
      if (realFreeAfterMB < TARGET_RESERVE_MB) {
        blockers.push(`Real free RAM after the move would be ${Math.max(0, Math.round(realFreeAfterMB))} MB — below the ${TARGET_RESERVE_MB} MB reserve.`);
      }
    } else {
      blockers.push("Live RAM reading unavailable (node API did not answer) — the move engine would refuse.");
    }

    if (n.guard) {
      if (!n.guard.ok) {
        const msg = `Pinned-RAM guard: ${n.guard.reason ?? "would exceed the node's RAM policy"}`;
        if (opts.guardMode === "enforce") blockers.push(msg);
        else if (opts.guardMode === "warn") warnings.push(msg);
      }
    }

    let addressChange: string;
    if (server.hasDedicatedIp) {
      if (server.region && n.region !== server.region) {
        blockers.push(`Dedicated IP can only move within the same region (${server.region} → ${n.region}). Release it to NAT first, or pick a ${server.region} node.`);
      }
      if (server.provider && n.provider !== server.provider) {
        blockers.push(`Dedicated IP can only move between nodes on the same network (${server.provider} → ${n.provider}).`);
      }
      addressChange = "Dedicated IP moves with the VM (same address) — confirmed against the upstream move list during the dry run.";
    } else {
      const to = opts.targetPublicIp?.(n.id) ?? null;
      addressChange =
        to && server.publicIp && to !== server.publicIp
          ? `Public address changes ${server.publicIp} → ${to}; SSH/game ports are re-allocated on the target. The customer is notified.`
          : "NAT address on the target node; SSH/game ports are re-allocated there.";
    }

    out.push({
      nodeId: n.id,
      name: n.name,
      region: n.region,
      eligible: blockers.length === 0,
      blockers,
      warnings,
      committedPctNow: pct(n.committedRamMB, n.capacityRamMB),
      committedPctAfter,
      realFreeAfterMB,
      realPctAfter,
      addressChange,
    });
  }
  // eligible first, then most real headroom
  return out.sort((a, b) => Number(b.eligible) - Number(a.eligible) || (b.realFreeAfterMB ?? -1e9) - (a.realFreeAfterMB ?? -1e9));
}

/** "~3 min" style label for a seconds estimate that came from the engine's plan. */
export function fmtDuration(sec: number | null | undefined): string {
  if (sec == null || !Number.isFinite(sec) || sec < 0) return "—";
  if (sec < 90) return `~${Math.max(1, Math.round(sec))} s`;
  if (sec < 5400) return `~${Math.round(sec / 60)} min`;
  return `~${Math.round((sec / 3600) * 10) / 10} h`;
}

