/**
 * "What will be destroyed" manifest for the Danger tab — PURE (unit-tested).
 *
 * Mirrors what the worker's DELETE job (`remove` in worker/index.ts) really
 * does, so the admin reads the consequences BEFORE typing the hostname rather
 * than discovering them after:
 *   - `qm destroy --purge` → every disk the vmid owns, incl. attached volumes
 *   - cloud-init snippet
 *   - dedicated IP released back to the pool (and its virtual MAC removed)
 *   - Steam GSLT account (game servers)
 *   - game subdomain DNS record
 *   - port forwards (NAT rules re-synced without them)
 *   - Server row hard-deleted (a ServerArchive copy is written first; Job rows kept)
 * Backup archives on backup storage are NOT deleted by the job — stated, so
 * nobody assumes they are gone (or assumes they are kept forever).
 */

export type DeleteManifestInput = {
  hostname: string;
  vmid: number | null;
  nodeName: string | null;
  diskGB: number;
  dedicatedIp: string | null;
  portForwards: number;
  volumes: { name: string; sizeGB: number }[];
  subdomain: string | null;
  isGame: boolean;
  snapshots: number | null;
  firewallRules: number;
  websites: number;
  databases: number;
  status: string;
  isFree: boolean;
  expiresAt: Date | null;
};

export type ManifestItem = { label: string; detail: string; kind: "destroyed" | "released" | "kept" };

export function buildDeleteManifest(i: DeleteManifestInput): ManifestItem[] {
  const items: ManifestItem[] = [];
  if (i.vmid != null) {
    items.push({
      label: "Virtual machine",
      detail: `VMID ${i.vmid}${i.nodeName ? ` on ${i.nodeName}` : ""} — destroyed with --purge (${i.diskGB} GB system disk)`,
      kind: "destroyed",
    });
  } else {
    items.push({ label: "Virtual machine", detail: "No VM exists yet — only the database row is removed", kind: "destroyed" });
  }
  for (const v of i.volumes) {
    items.push({ label: "Attached volume", detail: `${v.name} (${v.sizeGB} GB, billed separately) — destroyed with the VM`, kind: "destroyed" });
  }
  if (i.snapshots && i.snapshots > 0) {
    items.push({ label: "Snapshots", detail: `${i.snapshots} Proxmox snapshot${i.snapshots === 1 ? "" : "s"} — destroyed with the VM`, kind: "destroyed" });
  }
  if (i.dedicatedIp) items.push({ label: "Dedicated IPv4", detail: `${i.dedicatedIp} — released back to the pool`, kind: "released" });
  if (i.portForwards > 0) items.push({ label: "Port forwards", detail: `${i.portForwards} NAT rule${i.portForwards === 1 ? "" : "s"} removed`, kind: "released" });
  if (i.subdomain) items.push({ label: "Game subdomain", detail: `${i.subdomain} DNS record deleted`, kind: "released" });
  if (i.isGame) items.push({ label: "Steam server token", detail: "Game server login token (if any) deleted", kind: "released" });
  if (i.firewallRules > 0) items.push({ label: "Firewall rules", detail: `${i.firewallRules} platform firewall rule${i.firewallRules === 1 ? "" : "s"}`, kind: "destroyed" });
  if (i.websites > 0) items.push({ label: "Websites", detail: `${i.websites} website record${i.websites === 1 ? "" : "s"} (their files live on the VM disk)`, kind: "destroyed" });
  if (i.databases > 0) items.push({ label: "Databases", detail: `${i.databases} database record${i.databases === 1 ? "" : "s"} (data lives on the VM disk)`, kind: "destroyed" });
  items.push({ label: "Server record", detail: "Hard-deleted; an archive copy (hostname, owner, spend, dates) is kept for reporting", kind: "destroyed" });
  items.push({ label: "Job history", detail: "Kept (detached from the server)", kind: "kept" });
  items.push({ label: "Backup archives", detail: "NOT deleted by this job — they remain on backup storage until retention expires", kind: "kept" });
  items.push({ label: "Invoices & wallet", detail: "Untouched. No refund is issued by deleting — use Billing → refund first if one is owed", kind: "kept" });
  return items;
}

/** Warnings that should make an admin stop and think before deleting. */
export function deleteWarnings(i: DeleteManifestInput, now = new Date()): string[] {
  const w: string[] = [];
  if (i.status === "RUNNING") w.push("The server is RUNNING right now — the customer's workload stops immediately.");
  if (!i.isFree && i.expiresAt && i.expiresAt.getTime() > now.getTime()) {
    const days = Math.ceil((i.expiresAt.getTime() - now.getTime()) / 86_400_000);
    w.push(`The customer has ${days} paid day${days === 1 ? "" : "s"} left on this server.`);
  }
  if (i.volumes.length > 0) w.push("Attached volumes are destroyed too — detach them first if the data must survive.");
  return w;
}

/** Typed-confirmation check used both client- and server-side. */
export function deleteConfirmMatches(typed: string, hostname: string): boolean {
  return typed.trim() === hostname;
}

