/**
 * Servers list (/admin/servers) — URL ⇄ filter ⇄ Prisma `where` mapping. PURE
 * (no db import; only `import type` from Prisma) so it is unit-tested and the
 * same parsing backs the page AND the CSV export route, which therefore can
 * never export a different set than the one on screen.
 */
import type { Prisma } from "@prisma/client";

export const SERVER_STATUSES = ["PENDING", "PROVISIONING", "RUNNING", "STOPPED", "SUSPENDED", "REINSTALLING", "DELETING", "ERROR"] as const;
export type ServerStatusKey = (typeof SERVER_STATUSES)[number];

export const SORT_KEYS = ["created", "expires", "hostname", "status", "vmid"] as const;
export type FleetSortKey = (typeof SORT_KEYS)[number];

export const PER_PAGE_OPTIONS = [25, 50, 100] as const;

export type FleetFilters = {
  q: string;
  status: ServerStatusKey | null;
  node: string | null;
  region: string | null;
  /** "vps" | "game" | a game family slug */
  kind: string | null;
  plan: string | null;
  owner: string | null;
  /** renewing within N days (paid, dated, not suspended/deleting) */
  expiring: number | null;
  flagged: boolean;
  mismatch: boolean;
  sort: FleetSortKey;
  dir: "asc" | "desc";
  page: number;
  per: number;
};

type Raw = Record<string, string | string[] | undefined>;
const one = (v: string | string[] | undefined) => (Array.isArray(v) ? v[0] : v) ?? "";
const ID_RE = /^[a-z0-9]{8,40}$/i;
const SLUG_RE = /^[a-z0-9][a-z0-9_-]{0,40}$/i;

export function parseFleetFilters(sp: Raw): FleetFilters {
  const q = one(sp.q).trim().slice(0, 120);
  const statusRaw = one(sp.status).toUpperCase();
  const status = (SERVER_STATUSES as readonly string[]).includes(statusRaw) ? (statusRaw as ServerStatusKey) : null;
  const node = ID_RE.test(one(sp.node)) ? one(sp.node) : null;
  const region = SLUG_RE.test(one(sp.region)) ? one(sp.region).toLowerCase() : null;
  const kind = SLUG_RE.test(one(sp.kind)) ? one(sp.kind).toLowerCase() : null;
  const plan = ID_RE.test(one(sp.plan)) ? one(sp.plan) : null;
  const owner = ID_RE.test(one(sp.owner)) ? one(sp.owner) : null;
  const exp = Number(one(sp.expiring));
  const expiring = Number.isInteger(exp) && exp > 0 && exp <= 365 ? exp : null;
  const sortRaw = one(sp.sort);
  const sort = (SORT_KEYS as readonly string[]).includes(sortRaw) ? (sortRaw as FleetSortKey) : "created";
  const dir = one(sp.dir) === "asc" ? "asc" : "desc";
  const pageN = Number(one(sp.page));
  const page = Number.isInteger(pageN) && pageN > 0 ? Math.min(pageN, 10_000) : 1;
  const perN = Number(one(sp.per));
  const per = (PER_PAGE_OPTIONS as readonly number[]).includes(perN) ? perN : 25;
  return { q, status, node, region, kind, plan, owner, expiring, flagged: one(sp.flagged) === "1", mismatch: one(sp.mismatch) === "1", sort, dir, page, per };
}

/** Back to a querystring (drops defaults) — used for chips, pagination, saved views, CSV link. */
export function fleetFiltersToParams(f: Partial<FleetFilters>): Record<string, string> {
  const p: Record<string, string> = {};
  if (f.q) p.q = f.q;
  if (f.status) p.status = f.status;
  if (f.node) p.node = f.node;
  if (f.region) p.region = f.region;
  if (f.kind) p.kind = f.kind;
  if (f.plan) p.plan = f.plan;
  if (f.owner) p.owner = f.owner;
  if (f.expiring) p.expiring = String(f.expiring);
  if (f.flagged) p.flagged = "1";
  if (f.mismatch) p.mismatch = "1";
  if (f.sort && f.sort !== "created") p.sort = f.sort;
  if (f.dir && f.dir !== "desc") p.dir = f.dir;
  if (f.page && f.page > 1) p.page = String(f.page);
  if (f.per && f.per !== 25) p.per = String(f.per);
  return p;
}

export function fleetHref(base: string, f: Partial<FleetFilters>): string {
  const qs = new URLSearchParams(fleetFiltersToParams(f)).toString();
  return qs ? `${base}?${qs}` : base;
}

export const MISMATCH_STALE_MS = 30 * 60_000;
export const GAME_DOWN_STATES = ["game_stopped", "crashed", "not_responding"];

/**
 * Build the Prisma where. `ctx.driftServerIds` are servers the latest drift
 * scan flagged (lib/admin-ops drift); `ctx.abuseServerIds` have an OPEN abuse
 * alert. Both are passed in so this stays pure.
 */
export function fleetWhere(
  f: FleetFilters,
  ctx: { now: Date; driftServerIds?: string[]; abuseServerIds?: string[] },
): Prisma.ServerWhereInput {
  const and: Prisma.ServerWhereInput[] = [];
  if (f.q) {
    const q = f.q;
    const or: Prisma.ServerWhereInput[] = [
      { hostname: { contains: q, mode: "insensitive" } },
      { name: { contains: q, mode: "insensitive" } },
      { label: { contains: q, mode: "insensitive" } },
      { ipAddress: { contains: q } },
      { subdomain: { contains: q, mode: "insensitive" } },
      { dedicatedIp: { is: { address: { contains: q } } } },
      { user: { is: { email: { contains: q, mode: "insensitive" } } } },
      { user: { is: { name: { contains: q, mode: "insensitive" } } } },
    ];
    if (/^\d{1,9}$/.test(q)) {
      const n = Number(q);
      or.push({ vmid: n }, { sshPort: n });
    }
    if (ID_RE.test(q)) or.push({ id: q });
    and.push({ OR: or });
  }
  if (f.status) and.push({ status: f.status });
  if (f.node) and.push({ nodeId: f.node });
  if (f.region) and.push({ node: { is: { region: f.region } } });
  if (f.kind === "vps") and.push({ gamePlanId: null });
  else if (f.kind === "game") and.push({ gamePlanId: { not: null } });
  else if (f.kind) and.push({ gamePlan: { is: { gameFamily: f.kind } } });
  if (f.plan) and.push({ OR: [{ planId: f.plan, gamePlanId: null }, { gamePlanId: f.plan }] });
  if (f.owner) and.push({ userId: f.owner });
  if (f.expiring) {
    and.push({
      isFree: false,
      status: { notIn: ["SUSPENDED", "DELETING"] },
      expiresAt: { gte: ctx.now, lte: new Date(ctx.now.getTime() + f.expiring * 86_400_000) },
    });
  }
  if (f.flagged) {
    const or: Prisma.ServerWhereInput[] = [{ status: "SUSPENDED" }, { dunningStage: { gt: 0 } }];
    if (ctx.abuseServerIds?.length) or.push({ id: { in: ctx.abuseServerIds } });
    and.push({ OR: or });
  }
  if (f.mismatch) {
    const or: Prisma.ServerWhereInput[] = [
      { status: "ERROR" },
      {
        status: { in: ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"] },
        updatedAt: { lt: new Date(ctx.now.getTime() - MISMATCH_STALE_MS) },
        jobs: { none: { status: { in: ["QUEUED", "RUNNING"] } } },
      },
      {
        status: "RUNNING",
        gameRuntime: { is: { state: { in: GAME_DOWN_STATES }, NOT: { intent: "stopped" } } },
      },
    ];
    if (ctx.driftServerIds?.length) or.push({ id: { in: ctx.driftServerIds } });
    and.push({ OR: or });
  }
  return and.length ? { AND: and } : {};
}

export function fleetOrderBy(f: FleetFilters): Prisma.ServerOrderByWithRelationInput[] {
  const d = f.dir;
  switch (f.sort) {
    case "expires":
      return [{ expiresAt: { sort: d, nulls: "last" } }, { createdAt: "desc" }];
    case "hostname":
      return [{ hostname: d }];
    case "status":
      return [{ status: d }, { createdAt: "desc" }];
    case "vmid":
      return [{ vmid: { sort: d, nulls: "last" } }];
    default:
      return [{ createdAt: d }];
  }
}

/** Column chooser registry. `always` columns cannot be hidden. */
export const FLEET_COLUMNS = [
  { key: "health", label: "Health", always: true },
  { key: "hostname", label: "Server", always: true },
  { key: "owner", label: "Owner" },
  { key: "type", label: "Type" },
  { key: "plan", label: "Plan / price" },
  { key: "vmid", label: "VMID" },
  { key: "endpoint", label: "Endpoint" },
  { key: "node", label: "Node / region" },
  { key: "cpu", label: "CPU (live)" },
  { key: "ram", label: "RAM (sample)" },
  { key: "disk", label: "Disk (sample)" },
  { key: "status", label: "Status" },
  { key: "expires", label: "Expires" },
  { key: "spend", label: "Total spent", defaultHidden: true },
  { key: "created", label: "Provisioned", defaultHidden: true },
  { key: "actions", label: "Actions", always: true },
] as const;
export type FleetColumnKey = (typeof FLEET_COLUMNS)[number]["key"];

/** RFC-4180 CSV cell. Also neutralises spreadsheet formula injection (=,+,-,@). */
export function csvCell(v: unknown): string {
  let s = v == null ? "" : String(v);
  if (/^[=+\-@\t\r]/.test(s)) s = `'${s}`;
  return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}

