      { ipAddress: { contains: q } },
      { subdomain: { contains: q, mode: "insensitive" } },
      { dedicatedIp: { is: { address: { contains: q } } } },
      { user: { is: { email: { contains: q, mode: "insensitive" } } } },
      { user: { is: { name: { contains: q, mode: "insensitive" } } } },
    ];
    if (/^\d{1,9}$/.test(q)) {
      const n = Number(q);
      or.push({ vmid: n }, { sshPort: n });
    }
    if (ID_RE.test(q)) or.push({ id: q });
    and.push({ OR: or });
  }
  if (f.status) and.push({ status: f.status });
  if (f.node) and.push({ nodeId: f.node });
  if (f.region) and.push({ node: { is: { region: f.region } } });
  if (f.kind === "vps") and.push({ gamePlanId: null });
  else if (f.kind === "game") and.push({ gamePlanId: { not: null } });
  else if (f.kind) and.push({ gamePlan: { is: { gameFamily: f.kind } } });
  if (f.plan) and.push({ OR: [{ planId: f.plan, gamePlanId: null }, { gamePlanId: f.plan }] });
  if (f.owner) and.push({ userId: f.owner });
  if (f.expiring) {
    and.push({
      isFree: false,
      status: { notIn: ["SUSPENDED", "DELETING"] },
      expiresAt: { gte: ctx.now, lte: new Date(ctx.now.getTime() + f.expiring * 86_400_000) },
    });
  }
  if (f.flagged) {
    const or: Prisma.ServerWhereInput[] = [{ status: "SUSPENDED" }, { dunningStage: { gt: 0 } }];
    if (ctx.abuseServerIds?.length) or.push({ id: { in: ctx.abuseServerIds } });
    and.push({ OR: or });
  }
  if (f.mismatch) {
    const or: Prisma.ServerWhereInput[] = [
      { status: "ERROR" },
      {
        status: { in: ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"] },
        updatedAt: { lt: new Date(ctx.now.getTime() - MISMATCH_STALE_MS) },
        jobs: { none: { status: { in: ["QUEUED", "RUNNING"] } } },
      },
      {
        status: "RUNNING",
        gameRuntime: { is: { state: { in: GAME_DOWN_STATES }, NOT: { intent: "stopped" } } },
      },
    ];
    if (ctx.driftServerIds?.length) or.push({ id: { in: ctx.driftServerIds } });
    and.push({ OR: or });
  }
