/**
 * Customer 360 → Profile & risk. PURE (unit-tested): turns facts the loader
 * already read from the DB into a list of plain-English risk signals.
 *
 * Nothing here is a verdict and nothing is invented — every signal names the
 * data it came from, so an admin can check it. The "score" is only a sort key
 * for the signals' combined weight, NOT a fraud probability; the UI says so.
 *
 * The signal set is built from what real incidents looked like on this
 * platform: the 2026-09 `pslgaming` teardown (fraudulent card use — several
 * cards, declines, a billing country that did not match where the person
 * actually connected from), alias accounts farming the first-month promo,
 * and shared-IP / shared-browser account clusters.
 */

export type RiskSeverity = "high" | "medium" | "low" | "info";
export type RiskSignal = { key: string; severity: RiskSeverity; title: string; detail: string };

export type RiskFacts = {
  accountAgeDays: number;
  emailVerified: boolean;
  totpEnabled: boolean;
  suspended: boolean;
  billingCountry: string | null;
  /** distinct ISO country codes seen on this account's visits / sessions */
  seenCountries: string[];
  /** other accounts that signed in from one of this account's IPs */
  sharedIpAccounts: { id: string; email: string; sharedIps: number }[];
  /** other accounts sharing a browser cookie id (Visit.visitorId) */
  sharedBrowserAccounts: { id: string; email: string }[];
  /** other accounts whose email collapses to the same mailbox (dots / +tags) */
  aliasAccounts: { id: string; email: string }[];
  cards: { createdAt: Date; unusable: boolean }[];
  paidInvoiceCents: number;
  refundedInvoices: number;
  refundedCents: number;
  chargebacks: number;
  openAbuseAlerts: number;
  priorFraudActions: number;
  /** servers this account had that were deleted within 48h of creation */
  shortLivedServers: number;
  /** minutes from signup to the first paid invoice (null = never paid) */
  minutesToFirstPurchase: number | null;
};

export type RiskReport = { score: number; level: "high" | "medium" | "low"; signals: RiskSignal[] };

const W: Record<RiskSeverity, number> = { high: 35, medium: 15, low: 5, info: 0 };

/** Gmail-style mailbox key: lowercased, +tag stripped, dots removed for gmail/googlemail. */
export function emailFamilyKey(email: string): string {
  const e = email.trim().toLowerCase();
  const at = e.lastIndexOf("@");
  if (at < 1) return e;
  let local = e.slice(0, at);
  let domain = e.slice(at + 1);
  const plus = local.indexOf("+");
  if (plus > 0) local = local.slice(0, plus);
  if (domain === "googlemail.com") domain = "gmail.com";
  if (domain === "gmail.com") local = local.replace(/\./g, "");
  return `${local}@${domain}`;
}

export function evaluateRisk(f: RiskFacts): RiskReport {
  const s: RiskSignal[] = [];

  if (f.priorFraudActions > 0) {
    s.push({ key: "prior_fraud", severity: "high", title: "Previous fraud action on record", detail: `${f.priorFraudActions} audit entr${f.priorFraudActions === 1 ? "y" : "ies"} recording a fraud teardown or fraud suspension for this account.` });
  }
  if (f.chargebacks > 0) {
    s.push({ key: "chargebacks", severity: "high", title: `${f.chargebacks} chargeback${f.chargebacks === 1 ? "" : "s"}`, detail: "Recorded against this customer's invoices (partner.chargeback audit entries)." });
  }
  const unusable = f.cards.filter((c) => c.unusable).length;
  if (f.cards.length >= 3) {
    const sorted = [...f.cards].sort((a, b) => a.createdAt.getTime() - b.createdAt.getTime());
    const spanH = (sorted[sorted.length - 1].createdAt.getTime() - sorted[0].createdAt.getTime()) / 3_600_000;
    s.push({
      key: "many_cards",
      severity: spanH <= 72 ? "high" : "medium",
      title: `${f.cards.length} cards on file`,
      detail: spanH <= 72 ? `All added within ${Math.max(1, Math.round(spanH))} h — a classic card-testing pattern.` : "Several different cards have been saved on this account.",
    });
  }
  if (unusable > 0) {
    s.push({ key: "declined_cards", severity: unusable >= 2 ? "medium" : "low", title: `${unusable} card${unusable === 1 ? "" : "s"} marked unusable`, detail: "The card processor declined or rejected these cards (PaymentCard.unusableAt)." });
  }
  if (f.billingCountry && f.seenCountries.length > 0 && !f.seenCountries.includes(f.billingCountry.toUpperCase())) {
    s.push({ key: "country_mismatch", severity: "medium", title: "Billing country never seen in sign-ins", detail: `Billing country ${f.billingCountry.toUpperCase()}; connections only seen from ${f.seenCountries.join(", ")}.` });
  }
  if (f.seenCountries.length >= 4) {
    s.push({ key: "many_countries", severity: "low", title: `Connected from ${f.seenCountries.length} countries`, detail: f.seenCountries.join(", ") + " — VPN use or a shared account." });
  }
  if (f.aliasAccounts.length > 0) {
    s.push({ key: "alias_accounts", severity: "medium", title: `${f.aliasAccounts.length} alias account${f.aliasAccounts.length === 1 ? "" : "s"}`, detail: `Same mailbox with dots/+tags: ${f.aliasAccounts.map((a) => a.email).slice(0, 5).join(", ")}.` });
  }
  if (f.sharedBrowserAccounts.length > 0) {
    s.push({ key: "shared_browser", severity: f.sharedBrowserAccounts.length >= 2 ? "medium" : "low", title: `Browser shared with ${f.sharedBrowserAccounts.length} other account${f.sharedBrowserAccounts.length === 1 ? "" : "s"}`, detail: f.sharedBrowserAccounts.map((a) => a.email).slice(0, 5).join(", ") });
  }
  if (f.sharedIpAccounts.length > 0) {
    s.push({ key: "shared_ip", severity: f.sharedIpAccounts.length >= 3 ? "medium" : "low", title: `IP addresses shared with ${f.sharedIpAccounts.length} other account${f.sharedIpAccounts.length === 1 ? "" : "s"}`, detail: "Could be a household, office or VPN exit — check together with the other signals." });
  }
  if (f.refundedInvoices > 0 && f.paidInvoiceCents > 0) {
    const ratio = f.refundedCents / f.paidInvoiceCents;
    if (ratio >= 0.5) s.push({ key: "refund_ratio", severity: "medium", title: `${Math.round(ratio * 100)}% of payments refunded`, detail: `${f.refundedInvoices} refunded invoice${f.refundedInvoices === 1 ? "" : "s"}.` });
  }
  if (f.shortLivedServers >= 2) {
    s.push({ key: "short_lived", severity: "low", title: `${f.shortLivedServers} servers deleted within 48 h`, detail: "Create-and-delete churn (promo farming or testing)." });
  }
  if (f.openAbuseAlerts > 0) {
    s.push({ key: "abuse", severity: "medium", title: `${f.openAbuseAlerts} open abuse alert${f.openAbuseAlerts === 1 ? "" : "s"}`, detail: "Bandwidth / SMTP / port-scan alerts on this customer's servers." });
  }
  if (f.minutesToFirstPurchase != null && f.minutesToFirstPurchase < 10 && f.accountAgeDays < 7 && f.cards.length >= 2) {
    s.push({ key: "fast_purchase", severity: "low", title: "Bought within minutes of signing up, on a new account", detail: `${Math.max(0, Math.round(f.minutesToFirstPurchase))} min from signup to first paid invoice.` });
  }
  if (!f.emailVerified) s.push({ key: "unverified", severity: "info", title: "Email not verified", detail: "The account has not confirmed its email address." });
  if (f.suspended) s.push({ key: "suspended", severity: "info", title: "Account is suspended", detail: "The customer cannot sign in." });
  if (f.totpEnabled) s.push({ key: "totp", severity: "info", title: "2FA enabled", detail: "Lowers account-takeover risk." });

  const score = Math.min(100, s.reduce((n, x) => n + W[x.severity], 0));
  const level = score >= 50 ? "high" : score >= 20 ? "medium" : "low";
  const order: RiskSeverity[] = ["high", "medium", "low", "info"];
  s.sort((a, b) => order.indexOf(a.severity) - order.indexOf(b.severity));
  return { score, level, signals: s };
}

/** Flags are CustomerNote rows whose body starts with `#flag:<kind>` (no schema change). */
export const FLAG_KINDS = ["fraud_watch", "vip", "chargeback", "abuse", "do_not_refund", "manual_review"] as const;
export type FlagKind = (typeof FLAG_KINDS)[number];
export const FLAG_LABELS: Record<FlagKind, string> = {
  fraud_watch: "Fraud watch",
  vip: "VIP",
  chargeback: "Chargeback history",
  abuse: "Abuse history",
  do_not_refund: "Do not refund",
  manual_review: "Manual review",
};
const FLAG_RE = /^#flag:([a-z_]+)(?:\s+([\s\S]*))?$/;

export function parseFlagNote(body: string): { kind: FlagKind; note: string } | null {
  const m = FLAG_RE.exec(body.trim());
  if (!m) return null;
  if (!(FLAG_KINDS as readonly string[]).includes(m[1])) return null;
  return { kind: m[1] as FlagKind, note: (m[2] ?? "").trim() };
}

export function flagNoteBody(kind: FlagKind, note: string): string {
  return `#flag:${kind}${note.trim() ? ` ${note.trim()}` : ""}`;
}

