/**
 * Seam between the admin server page's Transfer/Move tab and the VM move
 * engine (lib/vm-move/*, worker/vm-move.ts) that lives on the UNMERGED branch
 * feature/vm-node-migration.
 *
 * The UI in components/admin/server360/MoveTab* is built against the engine's
 * REAL signatures (lib/vm-move/actions.ts on that branch, read 2026-10-01):
 *
 *   requestVmMove({serverId,targetNodeId,dryRun?,reason?,allowDropSnapshots?})
 *       → {ok:true,vmMoveId,jobId} | {ok:false,error}
 *   previewVmMove(serverId,targetNodeId,allowDropSnapshots?) → {ok:true,plan:MovePlan} | {ok:false,error}
 *   getVmMove(id) / listVmMoves({serverId?,limit?})
 *   requestVmMoveRollback(id) / requestVmMoveCleanup(id,{force?}) → {ok:true,jobId} | {ok:false,error}
 *
 * The types below are copied VERBATIM from that branch's lib/vm-move/types.ts
 * (only the subset the UI reads). On main the engine does not exist, so every
 * call here answers "engine not enabled" and the tab renders that state.
 *
 * INTEGRATION (one edit, after feature/vm-node-migration is merged):
 *   1. set ENGINE_PRESENT = true
 *   2. replace the bodies below with calls into "@/lib/vm-move/actions"
 *      (the shapes are identical, so the UI needs no change)
 *   3. delete the copied types and re-export them from "@/lib/vm-move/types".
 * Running a real move is ALSO gated by env VM_MOVE_UI_ENABLED=1 (see
 * vmMoveUiState) so merging the engine never exposes a live "Run move" button
 * before the owner has decided to turn it on. Dry-run previews only need the
 * engine.
 */

export const ENGINE_PRESENT = false;

export type MovePhase =
  | "PREFLIGHT" | "SNAPSHOT_LIVE" | "SEND_FULL" | "STOP_SOURCE" | "SEND_INCREMENTAL"
  | "CREATE_TARGET" | "MOVE_IP" | "START_TARGET" | "COMMIT" | "DONE";

export const MOVE_PHASES: readonly MovePhase[] = [
  "PREFLIGHT", "SNAPSHOT_LIVE", "SEND_FULL", "STOP_SOURCE", "SEND_INCREMENTAL",
  "CREATE_TARGET", "MOVE_IP", "START_TARGET", "COMMIT", "DONE",
];

/** Plain-English label for each engine phase (admin UI only). */
export const PHASE_LABELS: Record<MovePhase, string> = {
  PREFLIGHT: "Preflight checks + plan",
  SNAPSHOT_LIVE: "Consistent snapshot of the running source",
  SEND_FULL: "Full disk copy to the target (source still running)",
  STOP_SOURCE: "Graceful stop of the source — downtime starts",
  SEND_INCREMENTAL: "Copy the last changes",
  CREATE_TARGET: "Create the VM on the target node",
  MOVE_IP: "Move the dedicated IP (last reversible step)",
  START_TARGET: "Start + verify the target",
  COMMIT: "Cut over DB, NAT, DNS; notify the customer",
  DONE: "Done — source kept stopped",
};

export type MoveAddressing =
  | { kind: "DEDICATED"; address: string; sourceGateway: string; targetGateway: string; sourceService: string; targetService: string; sourceVirtualMac: string | null }
  | { kind: "NAT"; sourcePrivateIp: string; targetPrivateIpPlanned: string; targetGateway: string; sshPort: number | null; forwardPorts: number[]; sourcePublicIp: string; targetPublicIp: string };

export type PreflightCheck = { id: string; ok: boolean; blocking: boolean; detail: string };

export type NodeCapacityFacts = {
  nodeId: string; name: string; region: string;
  realAvailRamMB: number; realTotalRamMB: number;
  committedRamMB: number; capacityRamMB: number;
  poolFreeBytes: number; poolTotalBytes: number;
  cpuThreads: number; committedVcpu: number; cpuLoad: number;
};

export type MovePlan = {
  version: 1;
  serverId: string; hostname: string;
  sourceNodeId: string; sourceNodeName: string; targetNodeId: string; targetNodeName: string;
  sourceVmid: number; targetVmid: number;
  planRamMB: number; planVcpu: number; diskSizeGB: number;
  sourceUsedBytes: number;
  sourceDataset: string; targetDataset: string;
  sourceStorage: string; targetStorage: string; targetSnippetStorage: string;
  targetBridge: string;
  addressing: MoveAddressing;
  carriedConfig: Record<string, string>;
  target: NodeCapacityFacts;
  checks: PreflightCheck[];
  ok: boolean;
  estimatedDowntimeSec: number;
  estimatedFullSendSec: number;
  createdAt: string;
};

export type MoveLogLine = { at: string; phase: string; msg: string };

export type VmMoveStatus = "PLANNED" | "RUNNING" | "DONE" | "ROLLED_BACK" | "FAILED" | "CLEANED";

/** The subset of a VmMove row the UI renders (dates as ISO strings). */
export type VmMoveView = {
  id: string;
  status: VmMoveStatus;
  phase: string;
  dryRun: boolean;
  reason: string | null;
  sourceNodeId: string;
  targetNodeId: string;
  sourceVmid: number;
  targetVmid: number;
  addressChanged: boolean;
  error: string | null;
  keepSourceUntil: string | null;
  sourceCleanedAt: string | null;
  committed: boolean;
  log: MoveLogLine[];
  plan: MovePlan | null;
  createdAt: string;
  finishedAt: string | null;
};

export type BridgeResult<T extends object = object> = ({ ok: true } & T) | { ok: false; error: string; engineMissing?: boolean };

const MISSING = {
  ok: false as const,
  engineMissing: true,
  error: "The VM move engine is not part of this build yet (branch feature/vm-node-migration). Nothing was changed.",
};

export async function bridgePreviewVmMove(_serverId: string, _targetNodeId: string, _allowDropSnapshots: boolean): Promise<BridgeResult<{ plan: MovePlan }>> {
  return MISSING;
}

export async function bridgeRequestVmMove(_input: {
  serverId: string; targetNodeId: string; dryRun: boolean; reason: string; allowDropSnapshots: boolean;
}): Promise<BridgeResult<{ vmMoveId: string; jobId: string }>> {
  return MISSING;
}

export async function bridgeRollbackVmMove(_vmMoveId: string): Promise<BridgeResult<{ jobId: string }>> {
  return MISSING;
}

export async function bridgeCleanupVmMove(_vmMoveId: string, _force: boolean): Promise<BridgeResult<{ jobId: string }>> {
  return MISSING;
}

export async function bridgeListVmMoves(_serverId: string): Promise<VmMoveView[]> {
  return [];
}

/** What the Move tab may offer right now. */
export function vmMoveUiState(env: Record<string, string | undefined> = process.env): {
  engine: boolean; canPreview: boolean; canRun: boolean; reason: string | null;
} {
  if (!ENGINE_PRESENT) return { engine: false, canPreview: false, canRun: false, reason: "Move engine not merged into this build." };
  if (env.NXEON_SANDBOX === "1") return { engine: true, canPreview: true, canRun: false, reason: "Sandbox: the engine refuses real moves here." };
  if (env.VM_MOVE_UI_ENABLED !== "1") return { engine: true, canPreview: true, canRun: false, reason: "Running a move is switched off (set VM_MOVE_UI_ENABLED=1 to allow it)." };
  return { engine: true, canPreview: true, canRun: true, reason: null };
}

/** Rollback is only allowed before COMMIT; cleanup only after keepSourceUntil (engine rules, mirrored for button state). */
export function moveButtons(m: Pick<VmMoveView, "status" | "committed" | "keepSourceUntil" | "sourceCleanedAt">, now = new Date()) {
  const keepUntil = m.keepSourceUntil ? new Date(m.keepSourceUntil) : null;
  return {
    canRollback: m.status === "RUNNING" && !m.committed,
    canCleanup: m.status === "DONE" && !m.sourceCleanedAt,
    cleanupNeedsForce: m.status === "DONE" && !!keepUntil && keepUntil.getTime() > now.getTime(),
  };
}

