"use server";

/**
 * Admin server page (app/admin/servers/[id]) — the mutating actions the
 * redesigned tabs need that did not already exist in an admin-safe form.
 *
 * Every export:
 *   1. opens with `gate()` — requireArea(area) + assertNotImpersonating, the
 *      same pair lib/admin-ops/actions.ts uses (test/admin-server-360.test.ts
 *      enforces this structurally);
 *   2. validates its arguments with zod;
 *   3. demands a reason (lib/admin-ops cleanReason, 4–300 chars) and, where the
 *      action destroys anything, a typed confirmation checked HERE, server-side;
 *   4. is rate-limited per admin per action;
 *   5. writes an AuditLog row (category "server", target = server id);
 *   6. reuses the existing action/job path for the real work — nothing here
 *      talks to Proxmox, a node, or a guest directly. Long work stays a Job.
 *
 * Optional `idem` keys make a double-submitted dialog a no-op instead of a
 * second job/audit row.
 */
import { z } from "zod";
import { headers } from "next/headers";
import { revalidatePath } from "next/cache";
import { db } from "@/lib/db";
import { requireArea, type Area } from "@/lib/rbac";
import { assertNotImpersonating } from "@/lib/auth";
import { checkRateLimit, claimOnce, clientIp, UNKNOWN_IP } from "@/lib/rate-limit";
import { cleanReason } from "@/lib/admin-ops/types";
import { serverRootPassword } from "@/lib/sftp";
import { serverAction, reconcileServerFromProxmox } from "@/lib/actions";
import { reinstallToOs } from "@/lib/actions-server-lifecycle";
import { createSnapshot, deleteSnapshot, rollbackSnapshot, addPortForward, deletePortForward, changeGameSubdomain } from "@/lib/actions-server";
import { adminRequestRestore, adminCreateBackup } from "@/lib/actions-backups-admin";
import { addFirewallRule, toggleFirewallRule, deleteFirewallRule } from "@/lib/actions-firewall";
import { serviceAction } from "@/lib/actions-cron";
import { startDiagnose } from "@/lib/admin-ops/actions";
import { deleteConfirmMatches } from "@/lib/admin-server/delete-manifest";
import {
  bridgePreviewVmMove,
  bridgeRequestVmMove,
  bridgeRollbackVmMove,
  bridgeCleanupVmMove,
  vmMoveUiState,
  type MovePlan,
} from "@/lib/admin-server/vm-move-bridge";

type Ok<T extends object = object> = ({ ok: true } & T) | { ok: false; error: string };

const idSchema = z.string().regex(/^[a-z0-9]{8,40}$/i);
const idemSchema = z.string().regex(/^[A-Za-z0-9_-]{8,64}$/).optional();

async function gate(area: Area = "fleet") {
  const admin = await requireArea(area);
  await assertNotImpersonating();
  return admin;
}

function limited(adminId: string, action: string, max: number, windowMs: number): string | null {
  const r = checkRateLimit(`adm360:${action}:${adminId}`, { max, windowMs });
  return r.ok ? null : `Too many requests — try again in ${r.retryAfterSec}s.`;
}

/** true = first time this idempotency key is seen (proceed); false = duplicate submit. */
function firstSubmit(adminId: string, action: string, idem: string | undefined): boolean {
  if (!idem) return true;
  return claimOnce(`adm360:${action}:${adminId}:${idem}`, 15 * 60_000);
}

async function audit(adminId: string, action: string, serverId: string | null, detail: string) {
  let ip: string | null = null;
  try {
    const v = clientIp(await headers());
    ip = v === UNKNOWN_IP ? null : v;
  } catch {
    ip = null;
  }
  await db.auditLog.create({
    data: { userId: adminId, action, detail: detail.slice(0, 2000), category: "server", target: serverId, ...(ip ? { ip } : {}) },
  });
}

async function loadServer(serverId: string) {
  return db.server.findUnique({
    where: { id: serverId },
    select: { id: true, hostname: true, status: true, vmid: true, nodeId: true, rootPassword: true, rootPasswordEnc: true, userId: true },
  });
}

function revalidate(serverId: string) {
  revalidatePath(`/admin/servers/${serverId}`);
}

// ─── Access ──────────────────────────────────────────────────────────────────

/**
 * Reveal the server's root password to the admin. Never logged; the AuditLog
 * row records WHO looked, WHEN, from WHERE and WHY — not the secret.
 */
export async function adminRevealRootPassword(serverId: string, reason: string): Promise<Ok<{ password: string }>> {
  const admin = await gate("fleet");
  if (!idSchema.safeParse(serverId).success) return { ok: false, error: "Invalid server." };
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4–300 characters) — it goes in the audit log." };
  const rl = limited(admin.id, "reveal", 10, 10 * 60_000);
  if (rl) return { ok: false, error: rl };
  const s = await loadServer(serverId);
  if (!s) return { ok: false, error: "Server not found." };
  const pw = serverRootPassword(s);
  if (!pw) return { ok: false, error: "No root password is stored for this server (key-only, or never set)." };
  await audit(admin.id, "admin.server.credential_reveal", s.id, `${s.hostname}: root password revealed — ${why}`);
  return { ok: true, password: pw };
}

// ─── Danger ──────────────────────────────────────────────────────────────────

/** Delete a server: typed hostname + reason, audited, then the existing DELETE job path. */
export async function adminDeleteServer(serverId: string, typedHostname: string, reason: string, idem?: string): Promise<Ok> {
  const admin = await gate("fleet");
  const p = z.object({ serverId: idSchema, typed: z.string().max(200), idem: idemSchema }).safeParse({ serverId, typed: typedHostname, idem });
  if (!p.success) return { ok: false, error: "Invalid request." };
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4–300 characters)." };
  const rl = limited(admin.id, "delete", 5, 10 * 60_000);
  if (rl) return { ok: false, error: rl };
  const s = await loadServer(serverId);
  if (!s) return { ok: false, error: "Server not found." };
  if (!deleteConfirmMatches(typedHostname, s.hostname)) return { ok: false, error: `Type the hostname exactly (${s.hostname}) to confirm.` };
  if (s.status === "DELETING") return { ok: false, error: "This server is already being deleted." };
  if (!firstSubmit(admin.id, "delete", idem)) return { ok: false, error: "Already submitted." };
  await audit(admin.id, "admin.server.delete", s.id, `${s.hostname} (vmid ${s.vmid ?? "—"}) delete requested — ${why}`);
  // serverAction redirects an ADMIN to /admin/servers on success (NEXT_REDIRECT
  // propagates to the client by design); only an error comes back here.
  const res = await serverAction(serverId, "delete");
  if (res && "error" in res && res.error) return { ok: false, error: res.error };
  return { ok: true };
}

/** Reinstall to an OS template: wipes the disk, so it needs the typed hostname too. */
export async function adminReinstallServer(serverId: string, osTemplateId: string, typedHostname: string, reason: string, idem?: string): Promise<Ok> {
  const admin = await gate("fleet");
  const p = z.object({ serverId: idSchema, os: idSchema, idem: idemSchema }).safeParse({ serverId, os: osTemplateId, idem });
  if (!p.success) return { ok: false, error: "Invalid request." };
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4–300 characters)." };
  const rl = limited(admin.id, "reinstall", 5, 10 * 60_000);
  if (rl) return { ok: false, error: rl };
  const s = await loadServer(serverId);
  if (!s) return { ok: false, error: "Server not found." };
  if (!deleteConfirmMatches(typedHostname, s.hostname)) return { ok: false, error: `Type the hostname exactly (${s.hostname}) to confirm.` };
  if (!firstSubmit(admin.id, "reinstall", idem)) return { ok: false, error: "Already submitted." };
  const res = await reinstallToOs(serverId, osTemplateId);
  if (res?.error) return { ok: false, error: res.error };
  await audit(admin.id, "admin.server.reinstall", s.id, `${s.hostname} reinstall to ${osTemplateId} — ${why}`);
  revalidate(serverId);
  return { ok: true };
}

// ─── Snapshots / backups ─────────────────────────────────────────────────────

const SNAP_NAME = /^[A-Za-z0-9_]{1,40}$/;

export async function adminSnapshotAction(
  serverId: string,
  op: "create" | "delete" | "rollback",
  name: string,
  reason: string,
  typedConfirm = "",
): Promise<Ok> {
  const admin = await gate("fleet");
  const p = z.object({ serverId: idSchema, op: z.enum(["create", "delete", "rollback"]), name: z.string().regex(SNAP_NAME) }).safeParse({ serverId, op, name });
  if (!p.success) return { ok: false, error: "Invalid request (snapshot names: letters, digits, underscore, max 40)." };
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4–300 characters)." };
  const rl = limited(admin.id, "snapshot", 20, 10 * 60_000);
  if (rl) return { ok: false, error: rl };
  const s = await loadServer(serverId);
  if (!s) return { ok: false, error: "Server not found." };
  if (op !== "create" && typedConfirm.trim() !== name) return { ok: false, error: `Type the snapshot name (${name}) to confirm.` };
  const res = op === "create" ? await createSnapshot(serverId, name) : op === "delete" ? await deleteSnapshot(serverId, name) : await rollbackSnapshot(serverId, name);
  if (res?.error) return { ok: false, error: res.error };
  await audit(admin.id, `admin.server.snapshot_${op}`, s.id, `${s.hostname} snapshot ${op} "${name}" — ${why}`);
  revalidate(serverId);
  return { ok: true };
}

export async function adminBackupNow(serverId: string, reason: string, idem?: string): Promise<Ok> {
  const admin = await gate("fleet");
  if (!idSchema.safeParse(serverId).success || !idemSchema.safeParse(idem).success) return { ok: false, error: "Invalid request." };
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4–300 characters)." };
  const rl = limited(admin.id, "backup", 10, 10 * 60_000);
  if (rl) return { ok: false, error: rl };
  const s = await loadServer(serverId);
  if (!s) return { ok: false, error: "Server not found." };
  if (!firstSubmit(admin.id, "backup", idem)) return { ok: false, error: "Already submitted." };
  const res = await adminCreateBackup(serverId);
  if (res?.error) return { ok: false, error: res.error };
  await audit(admin.id, "admin.server.backup_create", s.id, `${s.hostname} backup now — ${why}`);
  revalidate(serverId);
  return { ok: true };
}

/** Restore overwrites the live disk with the archive: typed hostname required. */
export async function adminRestoreBackup(serverId: string, volid: string, typedHostname: string, reason: string, idem?: string): Promise<Ok> {
  const admin = await gate("fleet");
  const p = z
    .object({ serverId: idSchema, volid: z.string().min(3).max(300).regex(/^[A-Za-z0-9_.:\/-]+$/), idem: idemSchema })
    .safeParse({ serverId, volid, idem });
  if (!p.success) return { ok: false, error: "Invalid request." };
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4–300 characters)." };
  const rl = limited(admin.id, "restore", 5, 10 * 60_000);
  if (rl) return { ok: false, error: rl };
  const s = await loadServer(serverId);
  if (!s) return { ok: false, error: "Server not found." };
  if (!deleteConfirmMatches(typedHostname, s.hostname)) return { ok: false, error: `Type the hostname exactly (${s.hostname}) to confirm.` };
  if (!firstSubmit(admin.id, "restore", idem)) return { ok: false, error: "Already submitted." };
  const res = await adminRequestRestore(serverId, volid);
  if (res?.error) return { ok: false, error: res.error };
  await audit(admin.id, "admin.server.backup_restore", s.id, `${s.hostname} restore from ${volid} — ${why}`);
  revalidate(serverId);
  return { ok: true };
}

// ─── Network ─────────────────────────────────────────────────────────────────

export async function adminAddPortForward(serverId: string, guestPort: number, protocol: "tcp" | "udp", reason: string): Promise<Ok> {
  const admin = await gate("fleet");
  const p = z.object({ serverId: idSchema, guestPort: z.number().int().min(1).max(65535), protocol: z.enum(["tcp", "udp"]) }).safeParse({ serverId, guestPort, protocol });
  if (!p.success) return { ok: false, error: "Invalid port forward (port 1–65535, tcp/udp)." };
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4–300 characters)." };
  const rl = limited(admin.id, "pf", 20, 10 * 60_000);
  if (rl) return { ok: false, error: rl };
  const s = await loadServer(serverId);
  if (!s) return { ok: false, error: "Server not found." };
  const fd = new FormData();
  fd.set("serverId", serverId);
  fd.set("guestPort", String(guestPort));
  fd.set("protocol", protocol);
  const res = await addPortForward(null, fd);
  if (res?.error) return { ok: false, error: res.error };
  await audit(admin.id, "admin.server.port_forward_add", s.id, `${s.hostname} forward ${protocol}/${guestPort} — ${why}`);
  revalidate(serverId);
  return { ok: true };
}

export async function adminRemovePortForward(serverId: string, forwardId: string, reason: string): Promise<Ok> {
  const admin = await gate("fleet");
  if (!idSchema.safeParse(serverId).success || !idSchema.safeParse(forwardId).success) return { ok: false, error: "Invalid request." };
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4–300 characters)." };
  const rl = limited(admin.id, "pf", 20, 10 * 60_000);
  if (rl) return { ok: false, error: rl };
  const pf = await db.portForward.findFirst({ where: { id: forwardId, serverId }, select: { publicPort: true, guestPort: true, protocol: true } });
  if (!pf) return { ok: false, error: "That port forward no longer exists." };
  await deletePortForward(serverId, forwardId);
  await audit(admin.id, "admin.server.port_forward_remove", serverId, `forward ${pf.protocol}/${pf.publicPort}→${pf.guestPort} removed — ${why}`);
  revalidate(serverId);
  return { ok: true };
}

export async function adminAddFirewallRule(
  serverId: string,
  rule: { action: "ALLOW" | "DENY"; protocol: "TCP" | "UDP" | "ICMP" | "ALL"; portFrom: string; portTo: string; sourceCidr: string; comment: string },
  reason: string,
): Promise<Ok> {
  const admin = await gate("fleet");
  const p = z
    .object({
      serverId: idSchema,
      action: z.enum(["ALLOW", "DENY"]),
      protocol: z.enum(["TCP", "UDP", "ICMP", "ALL"]),
      portFrom: z.string().max(5),
      portTo: z.string().max(5),
      sourceCidr: z.string().max(64),
      comment: z.string().max(200),
    })
    .safeParse({ serverId, ...rule });
  if (!p.success) return { ok: false, error: "Invalid firewall rule." };
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4–300 characters)." };
  const rl = limited(admin.id, "fw", 30, 10 * 60_000);
  if (rl) return { ok: false, error: rl };
  const fd = new FormData();
  fd.set("serverId", serverId);
  for (const [k, v] of Object.entries(rule)) fd.set(k, v);
  const res = await addFirewallRule(null, fd); // the same validateRule the worker uses
  if (res?.error) return { ok: false, error: res.error };
  await audit(admin.id, "admin.server.firewall_add", serverId, `${rule.action} ${rule.protocol} ${rule.portFrom || "*"}${rule.portTo ? "-" + rule.portTo : ""} from ${rule.sourceCidr || "any"} — ${why}`);
  revalidate(serverId);
  return { ok: true };
}

export async function adminFirewallRuleAction(serverId: string, ruleId: string, op: "toggle" | "delete", reason: string): Promise<Ok> {
  const admin = await gate("fleet");
  const p = z.object({ serverId: idSchema, ruleId: idSchema, op: z.enum(["toggle", "delete"]) }).safeParse({ serverId, ruleId, op });
  if (!p.success) return { ok: false, error: "Invalid request." };
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4–300 characters)." };
  const rl = limited(admin.id, "fw", 30, 10 * 60_000);
  if (rl) return { ok: false, error: rl };
  const rule = await db.firewallRule.findFirst({ where: { id: ruleId, serverId }, select: { id: true } });
  if (!rule) return { ok: false, error: "That rule no longer exists." };
  const res = op === "toggle" ? await toggleFirewallRule(serverId, ruleId) : await deleteFirewallRule(serverId, ruleId);
  const err = (res as { error?: string } | void)?.error;
  if (err) return { ok: false, error: err };
  await audit(admin.id, `admin.server.firewall_${op}`, serverId, `rule ${ruleId} ${op} — ${why}`);
  revalidate(serverId);
  return { ok: true };
}

export async function adminChangeSubdomain(serverId: string, subdomain: string, reason: string): Promise<Ok> {
  const admin = await gate("fleet");
  const p = z.object({ serverId: idSchema, sub: z.string().min(1).max(63).regex(/^[a-z0-9-]+$/i) }).safeParse({ serverId, sub: subdomain });
  if (!p.success) return { ok: false, error: "Subdomains are letters, digits and dashes." };
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4–300 characters)." };
  const rl = limited(admin.id, "subdomain", 10, 10 * 60_000);
  if (rl) return { ok: false, error: rl };
  const fd = new FormData();
  fd.set("serverId", serverId);
  fd.set("subdomain", subdomain);
  const res = await changeGameSubdomain(null, fd); // availability across both tables + format rules
  if (res?.error) return { ok: false, error: res.error };
  await audit(admin.id, "admin.server.subdomain_change", serverId, `subdomain → ${subdomain.toLowerCase()} — ${why}`);
  revalidate(serverId);
  return { ok: true };
}

// ─── Software ────────────────────────────────────────────────────────────────

export async function adminServiceAction(serverId: string, unit: string, action: "start" | "stop" | "restart", reason: string): Promise<Ok> {
  const admin = await gate("fleet");
  const p = z.object({ serverId: idSchema, unit: z.string().regex(/^[a-z0-9@._-]{1,64}$/i), action: z.enum(["start", "stop", "restart"]) }).safeParse({ serverId, unit, action });
  if (!p.success) return { ok: false, error: "Invalid request." };
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4–300 characters)." };
  const rl = limited(admin.id, "svc", 20, 10 * 60_000);
  if (rl) return { ok: false, error: rl };
  const res = await serviceAction(serverId, unit, action); // allowlisted units only
  if (!res.ok) return { ok: false, error: res.error };
  await audit(admin.id, "admin.server.service_action", serverId, `${action} ${unit} — ${why}`);
  return { ok: true };
}

// ─── Transfer / Move (VM move engine, via the bridge) ────────────────────────

export async function adminPreviewMove(serverId: string, targetNodeId: string, allowDropSnapshots: boolean): Promise<Ok<{ plan: MovePlan }> & { engineMissing?: boolean }> {
  const admin = await gate("fleet");
  if (!idSchema.safeParse(serverId).success || !idSchema.safeParse(targetNodeId).success) return { ok: false, error: "Invalid request." };
  const rl = limited(admin.id, "move_preview", 20, 10 * 60_000);
  if (rl) return { ok: false, error: rl };
  const state = vmMoveUiState();
  if (!state.canPreview) return { ok: false, error: state.reason ?? "Move engine unavailable.", engineMissing: !state.engine };
  return bridgePreviewVmMove(serverId, targetNodeId, !!allowDropSnapshots);
}

export async function adminRunMove(
  serverId: string,
  targetNodeId: string,
  opts: { reason: string; typedHostname: string; allowDropSnapshots: boolean; dryRun: boolean; idem?: string },
): Promise<Ok<{ vmMoveId: string; jobId: string }>> {
  const admin = await gate("fleet");
  const p = z
    .object({ serverId: idSchema, targetNodeId: idSchema, dryRun: z.boolean(), allow: z.boolean(), idem: idemSchema })
    .safeParse({ serverId, targetNodeId, dryRun: opts.dryRun, allow: opts.allowDropSnapshots, idem: opts.idem });
  if (!p.success) return { ok: false, error: "Invalid request." };
  const why = cleanReason(opts.reason);
  if (!why) return { ok: false, error: "Give a reason (4–300 characters)." };
  const state = vmMoveUiState();
  if (opts.dryRun ? !state.canPreview : !state.canRun) return { ok: false, error: state.reason ?? "Moves are not enabled." };
  const rl = limited(admin.id, "move_run", 5, 10 * 60_000);
  if (rl) return { ok: false, error: rl };
  const s = await loadServer(serverId);
  if (!s) return { ok: false, error: "Server not found." };
  if (!opts.dryRun && !deleteConfirmMatches(opts.typedHostname, s.hostname)) return { ok: false, error: `Type the hostname exactly (${s.hostname}) to confirm.` };
  if (!firstSubmit(admin.id, "move_run", opts.idem)) return { ok: false, error: "Already submitted." };
  const res = await bridgeRequestVmMove({ serverId, targetNodeId, dryRun: opts.dryRun, reason: why, allowDropSnapshots: opts.allowDropSnapshots });
  if (!res.ok) return { ok: false, error: res.error };
  await audit(admin.id, opts.dryRun ? "admin.server.move_plan" : "admin.server.move_request", serverId, `${s.hostname} → node ${targetNodeId} (move ${res.vmMoveId}) — ${why}`);
  revalidate(serverId);
  return res;
}

export async function adminRollbackMove(serverId: string, vmMoveId: string, reason: string, typedHostname: string): Promise<Ok<{ jobId: string }>> {
  const admin = await gate("fleet");
  if (!idSchema.safeParse(serverId).success || !idSchema.safeParse(vmMoveId).success) return { ok: false, error: "Invalid request." };
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4–300 characters)." };
  const rl = limited(admin.id, "move_ctl", 10, 10 * 60_000);
  if (rl) return { ok: false, error: rl };
  const s = await loadServer(serverId);
  if (!s) return { ok: false, error: "Server not found." };
  if (!deleteConfirmMatches(typedHostname, s.hostname)) return { ok: false, error: `Type the hostname exactly (${s.hostname}) to confirm.` };
  const res = await bridgeRollbackVmMove(vmMoveId);
  if (!res.ok) return { ok: false, error: res.error };
  await audit(admin.id, "admin.server.move_rollback", serverId, `move ${vmMoveId} rollback requested — ${why}`);
  revalidate(serverId);
  return res;
}

export async function adminCleanupMove(serverId: string, vmMoveId: string, reason: string, typedHostname: string, force: boolean): Promise<Ok<{ jobId: string }>> {
  const admin = await gate("fleet");
  if (!idSchema.safeParse(serverId).success || !idSchema.safeParse(vmMoveId).success) return { ok: false, error: "Invalid request." };
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4–300 characters)." };
  const rl = limited(admin.id, "move_ctl", 10, 10 * 60_000);
  if (rl) return { ok: false, error: rl };
  const s = await loadServer(serverId);
  if (!s) return { ok: false, error: "Server not found." };
  if (!deleteConfirmMatches(typedHostname, s.hostname)) return { ok: false, error: `Type the hostname exactly (${s.hostname}) to confirm.` };
  const res = await bridgeCleanupVmMove(vmMoveId, !!force);
  if (!res.ok) return { ok: false, error: res.error };
  await audit(admin.id, "admin.server.move_cleanup", serverId, `move ${vmMoveId} source cleanup${force ? " (forced before keep-until)" : ""} — ${why}`);
  revalidate(serverId);
  return res;
}

// ─── Fleet list bulk (safe actions only) ─────────────────────────────────────

/**
 * Bulk actions offered on /admin/servers are deliberately NON-destructive:
 * reconcile (read Proxmox → fix the DB status) and diagnose (read-only job).
 * Power/delete in bulk stay on /admin/ops/fleet where they need a typed
 * confirmation and a concurrency cap.
 */
export async function adminFleetBulk(action: "reconcile" | "diagnose", serverIds: string[]): Promise<{ ok: number; failed: number; errors: string[] }> {
  const admin = await gate("fleet");
  const p = z.object({ action: z.enum(["reconcile", "diagnose"]), ids: z.array(idSchema).min(1).max(50) }).safeParse({ action, ids: serverIds });
  if (!p.success) return { ok: 0, failed: serverIds.length, errors: ["Pick between 1 and 50 servers."] };
  const rl = limited(admin.id, "bulk", 6, 10 * 60_000);
  if (rl) return { ok: 0, failed: serverIds.length, errors: [rl] };
  let ok = 0;
  const errors: string[] = [];
  for (const id of p.data.ids) {
    try {
      if (action === "reconcile") {
        const r = await reconcileServerFromProxmox(id);
        if (r?.error) errors.push(r.error);
        else ok++;
      } else {
        const r = await startDiagnose(id);
        if (!r.ok) errors.push(r.error);
        else ok++;
      }
    } catch (e) {
      errors.push(String((e as Error)?.message ?? e).slice(0, 200));
    }
  }
  await audit(admin.id, `admin.fleet.bulk_${action}`, null, `${action} on ${p.data.ids.length} servers: ${ok} ok, ${errors.length} failed`);
  revalidatePath("/admin/servers");
  return { ok, failed: errors.length, errors: [...new Set(errors)].slice(0, 5) };
}

