"use server";

/**
 * Customer 360 (app/admin/users/[id]) — account actions that had no admin UI
 * (or no admin path at all) before the 2026-10-01 redesign.
 *
 * Same discipline as lib/actions-admin-server.ts: every export opens with
 * `gate()` (requireArea("clients") + assertNotImpersonating + ADMIN role —
 * `clients` admits SUPPORT for READING the page, but nothing here is a
 * support-level action), validates with zod, requires a reason, typed
 * confirmation on anything destructive, a per-admin rate limit, and an
 * AuditLog row (category "client", target = the customer id).
 */
import { z } from "zod";
import { headers } from "next/headers";
import { revalidatePath } from "next/cache";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { assertNotImpersonating } from "@/lib/auth";
import { checkRateLimit, claimOnce, clientIp, UNKNOWN_IP } from "@/lib/rate-limit";
import { cleanReason } from "@/lib/admin-ops/types";
import { sendVerificationEmail, isEmailVerified } from "@/lib/email-verification";
import { adminSendPasswordReset } from "@/lib/actions-account";
import { FLAG_KINDS, flagNoteBody, parseFlagNote, emailFamilyKey } from "@/lib/admin-client/risk";

type Ok<T extends object = object> = ({ ok: true } & T) | { ok: false; error: string };

const idSchema = z.string().regex(/^[a-z0-9]{8,40}$/i);

async function gate() {
  const admin = await requireArea("clients");
  await assertNotImpersonating();
  if (admin.role !== "ADMIN") throw new Error("FORBIDDEN");
  return admin;
}

function limited(adminId: string, action: string, max: number, windowMs: number): string | null {
  const r = checkRateLimit(`adm360c:${action}:${adminId}`, { max, windowMs });
  return r.ok ? null : `Too many requests — try again in ${r.retryAfterSec}s.`;
}

async function audit(adminId: string, action: string, userId: string, detail: string) {
  let ip: string | null = null;
  try {
    const v = clientIp(await headers());
    ip = v === UNKNOWN_IP ? null : v;
  } catch {
    ip = null;
  }
  await db.auditLog.create({ data: { userId: adminId, action, detail: detail.slice(0, 2000), category: "client", target: userId, ...(ip ? { ip } : {}) } });
}

async function customer(userId: string) {
  if (!idSchema.safeParse(userId).success) return null;
  return db.user.findUnique({
    where: { id: userId },
    select: { id: true, email: true, name: true, role: true, emailVerifiedAt: true, createdAt: true, totpEnabled: true, balanceCents: true },
  });
}

const refresh = (userId: string) => revalidatePath(`/admin/users/${userId}`);

/** Turn off a customer's 2FA (lost device). Typed email confirmation; signs them out everywhere. */
export async function adminResetTwoFactor(userId: string, typedEmail: string, reason: string): Promise<Ok> {
  const admin = await gate();
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4–300 characters) — e.g. the ticket where identity was verified." };
  const rl = limited(admin.id, "2fa", 5, 60 * 60_000);
  if (rl) return { ok: false, error: rl };
  const u = await customer(userId);
  if (!u) return { ok: false, error: "Customer not found." };
  if (u.role !== "CUSTOMER") return { ok: false, error: "Staff accounts reset their own 2FA." };
  if (typedEmail.trim().toLowerCase() !== u.email.toLowerCase()) return { ok: false, error: "Type the customer's email exactly to confirm." };
  if (!u.totpEnabled) return { ok: false, error: "2FA is already off for this account." };
  await db.$transaction([
    db.user.update({ where: { id: u.id }, data: { totpEnabled: false, totpSecret: null, totpSecretEnc: null, backupCodes: [], sessionVersion: { increment: 1 } } }),
    db.userSession.updateMany({ where: { userId: u.id, revokedAt: null }, data: { revokedAt: new Date() } }),
  ]);
  await audit(admin.id, "admin.client.2fa_reset", u.id, `${u.email}: 2FA disabled, all sessions ended — ${why}`);
  refresh(u.id);
  return { ok: true };
}

/** Resend the email-verification link (same throttle as the customer's own resend). */
export async function adminResendVerification(userId: string, reason: string): Promise<Ok<{ message: string }>> {
  const admin = await gate();
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4–300 characters)." };
  const rl = limited(admin.id, "verify", 10, 60 * 60_000);
  if (rl) return { ok: false, error: rl };
  const u = await customer(userId);
  if (!u) return { ok: false, error: "Customer not found." };
  if (isEmailVerified(u)) return { ok: false, error: "This address is already verified." };
  const outcome = await sendVerificationEmail(u, { throttleKey: `${u.id}:admin` });
  await audit(admin.id, "admin.client.verification_resend", u.id, `${u.email}: verification resend → ${outcome} — ${why}`);
  if (outcome === "sent") return { ok: true, message: `Verification link sent to ${u.email}.` };
  if (outcome === "already_verified") return { ok: true, message: "Already verified." };
  if (outcome === "rate_limited") return { ok: false, error: "Several links were sent in the last hour already — wait before sending another." };
  return { ok: false, error: "The email could not be sent (mail delivery failed)." };
}

/** Email a password-reset link (wraps the existing adminSendPasswordReset, adds reason + rate limit). */
export async function adminPasswordResetLink(userId: string, reason: string): Promise<Ok> {
  const admin = await gate();
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4–300 characters)." };
  const rl = limited(admin.id, "pwreset", 5, 60 * 60_000);
  if (rl) return { ok: false, error: rl };
  const u = await customer(userId);
  if (!u) return { ok: false, error: "Customer not found." };
  await adminSendPasswordReset(u.id); // writes its own admin.password_reset_sent row
  await audit(admin.id, "admin.client.password_reset_link", u.id, `${u.email}: reset link emailed — ${why}`);
  return { ok: true };
}

/** Sign the customer out of every device (revokes UserSession rows + bumps sessionVersion). */
export async function adminRevokeSessions(userId: string, reason: string): Promise<Ok<{ revoked: number }>> {
  const admin = await gate();
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4–300 characters)." };
  const rl = limited(admin.id, "sessions", 10, 60 * 60_000);
  if (rl) return { ok: false, error: rl };
  const u = await customer(userId);
  if (!u) return { ok: false, error: "Customer not found." };
  if (u.role === "ADMIN") return { ok: false, error: "Refusing to sign out an admin account from here." };
  const [r] = await db.$transaction([
    db.userSession.updateMany({ where: { userId: u.id, revokedAt: null }, data: { revokedAt: new Date() } }),
    db.user.update({ where: { id: u.id }, data: { sessionVersion: { increment: 1 } } }),
  ]);
  await audit(admin.id, "admin.client.sessions_revoked", u.id, `${u.email}: ${r.count} session(s) ended — ${why}`);
  refresh(u.id);
  return { ok: true, revoked: r.count };
}

/** Add a structured flag (stored as a CustomerNote "#flag:<kind> note", no schema change). */
export async function adminAddCustomerFlag(userId: string, kind: string, note: string): Promise<Ok> {
  const admin = await gate();
  const p = z.object({ userId: idSchema, kind: z.enum(FLAG_KINDS), note: z.string().max(500) }).safeParse({ userId, kind, note });
  if (!p.success) return { ok: false, error: "Invalid flag." };
  const rl = limited(admin.id, "flag", 30, 10 * 60_000);
  if (rl) return { ok: false, error: rl };
  const u = await customer(userId);
  if (!u) return { ok: false, error: "Customer not found." };
  const existing = await db.customerNote.findMany({ where: { userId }, select: { body: true } });
  if (existing.some((n) => parseFlagNote(n.body)?.kind === p.data.kind)) return { ok: false, error: "That flag is already set." };
  await db.customerNote.create({ data: { userId, authorId: admin.id, body: flagNoteBody(p.data.kind, p.data.note) } });
  await audit(admin.id, "admin.client.flag_add", userId, `${u.email}: flag ${p.data.kind}${p.data.note ? ` — ${p.data.note}` : ""}`);
  refresh(userId);
  return { ok: true };
}

export async function adminClearCustomerFlag(userId: string, noteId: string, reason: string): Promise<Ok> {
  const admin = await gate();
  if (!idSchema.safeParse(userId).success || !idSchema.safeParse(noteId).success) return { ok: false, error: "Invalid request." };
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4–300 characters)." };
  const n = await db.customerNote.findFirst({ where: { id: noteId, userId }, select: { id: true, body: true } });
  const flag = n ? parseFlagNote(n.body) : null;
  if (!n || !flag) return { ok: false, error: "That flag no longer exists." };
  await db.customerNote.delete({ where: { id: n.id } });
  await audit(admin.id, "admin.client.flag_clear", userId, `flag ${flag.kind} cleared — ${why}`);
  refresh(userId);
  return { ok: true };
}

export type MergePreview = {
  source: { id: string; email: string };
  target: { id: string; email: string };
  servers: number;
  hosting: number;
  emailSubs: number;
  domains: number;
  balanceCents: number;
  openTickets: number;
  sameMailbox: boolean;
  blockers: string[];
  enabled: boolean;
};

/**
 * Account merge — PREVIEW ONLY. Execution is deliberately not built: a merge
 * moves money (wallet), saved cards and Stripe customers, partner attribution
 * and every product row, and there is no proven path for that yet. The
 * preview tells the admin exactly what would have to move so it can be done
 * with the existing tools (Transfer server per server, balance adjustment)
 * until a real merge job exists.
 */
export async function adminPreviewMerge(sourceUserId: string, targetEmail: string): Promise<Ok<{ preview: MergePreview }>> {
  const admin = await gate();
  const p = z.object({ id: idSchema, email: z.string().email().max(200) }).safeParse({ id: sourceUserId, email: targetEmail.trim() });
  if (!p.success) return { ok: false, error: "Enter the email of the account to merge into." };
  const rl = limited(admin.id, "merge_preview", 30, 10 * 60_000);
  if (rl) return { ok: false, error: rl };
  const src = await customer(sourceUserId);
  const tgt = await db.user.findFirst({ where: { email: { equals: p.data.email, mode: "insensitive" } }, select: { id: true, email: true, role: true } });
  if (!src) return { ok: false, error: "Customer not found." };
  if (!tgt) return { ok: false, error: "No account with that email." };
  const [servers, hosting, emailSubs, domains, openTickets] = await Promise.all([
    db.server.count({ where: { userId: src.id, status: { not: "DELETING" } } }),
    db.hostingAccount.count({ where: { userId: src.id } }),
    db.emailSubscription.count({ where: { userId: src.id } }),
    db.domain.count({ where: { userId: src.id } }),
    db.ticket.count({ where: { userId: src.id, status: { not: "CLOSED" } } }),
  ]);
  const blockers: string[] = [];
  if (tgt.id === src.id) blockers.push("That is the same account.");
  if (tgt.role !== "CUSTOMER" || src.role !== "CUSTOMER") blockers.push("Only customer accounts can be merged.");
  blockers.push("Automatic merge is not built yet — move servers with Transfer (server page → Billing) and the wallet with a balance adjustment.");
  return {
    ok: true,
    preview: {
      source: { id: src.id, email: src.email },
      target: { id: tgt.id, email: tgt.email },
      servers,
      hosting,
      emailSubs,
      domains,
      balanceCents: src.balanceCents,
      openTickets,
      sameMailbox: emailFamilyKey(src.email) === emailFamilyKey(tgt.email),
      blockers,
      enabled: false,
    },
  };
}

/**
 * Permanently delete a customer account — the same transaction the customer's
 * own GDPR deletion runs (lib/actions-gdpr.ts deleteMyAccount), with STRICTER
 * preconditions because nobody is asking for it from the account itself:
 * no servers at all (not even DELETING), no hosting/email/domains, a zero
 * wallet, no open invoices, and typed email + the word DELETE + a reason.
 */
export async function adminDeleteAccount(userId: string, typedEmail: string, typedWord: string, reason: string, idem?: string): Promise<Ok> {
  const admin = await gate();
  const why = cleanReason(reason);
  if (!why || why.length < 10) return { ok: false, error: "Give a reason of at least 10 characters." };
  const rl = limited(admin.id, "delete_account", 3, 60 * 60_000);
  if (rl) return { ok: false, error: rl };
  const u = await customer(userId);
  if (!u) return { ok: false, error: "Customer not found." };
  if (u.role !== "CUSTOMER") return { ok: false, error: "Staff and admin accounts cannot be deleted from here." };
  if (u.id === admin.id) return { ok: false, error: "You cannot delete your own account." };
  if (typedEmail.trim().toLowerCase() !== u.email.toLowerCase() || typedWord.trim() !== "DELETE") {
    return { ok: false, error: `Type ${u.email} and the word DELETE to confirm.` };
  }
  const [servers, hosting, emailSubs, domains, openInvoices] = await Promise.all([
    db.server.count({ where: { userId: u.id } }),
    db.hostingAccount.count({ where: { userId: u.id } }),
    db.emailSubscription.count({ where: { userId: u.id } }),
    db.domain.count({ where: { userId: u.id } }),
    db.invoice.count({ where: { userId: u.id, status: "OPEN" } }),
  ]);
  const blockers: string[] = [];
  if (servers) blockers.push(`${servers} server(s) — delete them first`);
  if (hosting) blockers.push(`${hosting} hosting account(s)`);
  if (emailSubs) blockers.push(`${emailSubs} email subscription(s)`);
  if (domains) blockers.push(`${domains} domain(s)`);
  if (openInvoices) blockers.push(`${openInvoices} open invoice(s)`);
  if (u.balanceCents !== 0) blockers.push(`wallet balance is not zero — refund or adjust it first`);
  if (blockers.length) return { ok: false, error: `Cannot delete yet: ${blockers.join("; ")}.` };
  if (idem && !claimOnce(`adm360c:delete_account:${admin.id}:${idem}`, 15 * 60_000)) return { ok: false, error: "Already submitted." };

  await db.$transaction([
    db.auditLog.create({ data: { userId: admin.id, action: "admin.client.account_deleted", detail: `${u.email} (${u.id}) deleted by admin — ${why}`, category: "client", target: u.id } }),
    db.auditLog.updateMany({ where: { userId: u.id }, data: { userId: null } }),
    db.user.updateMany({ where: { referredById: u.id }, data: { referredById: null } }),
    db.walletTransaction.deleteMany({ where: { userId: u.id } }),
    db.passwordResetToken.deleteMany({ where: { userId: u.id } }),
    db.user.delete({ where: { id: u.id } }),
  ]);
  revalidatePath("/admin/users");
  return { ok: true };
}

