import "server-only";
import { db } from "@/lib/db";
import { pveForNode, vmStatus, listSnapshotsOn, ProxmoxError, type NodeConn } from "@/lib/proxmox";
import type { ProxmoxReading } from "./state-truth";

/**
 * READ-ONLY live reads for the admin server page. Every call:
 *   - goes through the server's OWN node (vmids collide across nodes),
 *   - is capped at LIVE_TIMEOUT_MS — the proxmox client's own timeout is 60s,
 *     far too long to hold an admin page open for one unreachable node,
 *   - never throws: a failure becomes an explicit "unreachable" reading.
 * Nothing here mutates anything (GET endpoints only).
 */
export const LIVE_TIMEOUT_MS = Number(process.env.ADMIN_LIVE_TIMEOUT_MS ?? 6000);

export function withTimeout<T>(p: Promise<T>, ms = LIVE_TIMEOUT_MS): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const t = setTimeout(() => reject(new Error(`timed out after ${Math.round(ms / 1000)}s`)), ms);
    p.then(
      (v) => {
        clearTimeout(t);
        resolve(v);
      },
      (e) => {
        clearTimeout(t);
        reject(e);
      },
    );
  });
}

type ServerLike = { vmid: number | null; node: (NodeConn & { id?: string }) | null };

function isMissing(e: unknown): boolean {
  const msg = String((e as Error)?.message ?? e);
  const body = e instanceof ProxmoxError ? String(e.body ?? "") : "";
  return /does not exist|no such vm|not found/i.test(msg + " " + body);
}

export async function liveVm(s: ServerLike): Promise<{ reading: ProxmoxReading; raw: any | null }> {
  if (!s.vmid) return { reading: { kind: "none" }, raw: null };
  try {
    const raw = await withTimeout(s.node ? pveForNode(s.node).vmStatus(s.vmid) : vmStatus(s.vmid));
    return {
      reading: { kind: "vm", status: String(raw?.status ?? "unknown"), uptimeSec: raw?.uptime ?? null, lock: raw?.lock ?? null },
      raw,
    };
  } catch (e) {
    if (isMissing(e)) return { reading: { kind: "missing" }, raw: null };
    return { reading: { kind: "unreachable", error: String((e as Error)?.message ?? e).slice(0, 160) }, raw: null };
  }
}

/** The VM's Proxmox config (current) and pending changes, or an error string. */
export async function liveVmConfig(s: ServerLike): Promise<{ config: Record<string, unknown> | null; pending: Record<string, unknown>; error: string | null }> {
  if (!s.vmid) return { config: null, pending: {}, error: "No VM yet." };
  if (!s.node) return { config: null, pending: {}, error: "Server has no node row (legacy) — config not read." };
  const c = pveForNode(s.node);
  try {
    const [config, pendingRows] = await Promise.all([
      withTimeout(c.get(`/nodes/${c.node}/qemu/${s.vmid}/config`)),
      withTimeout(c.get(`/nodes/${c.node}/qemu/${s.vmid}/pending`)).catch(() => [] as any[]),
    ]);
    const pending: Record<string, unknown> = {};
    for (const r of Array.isArray(pendingRows) ? pendingRows : []) {
      if (r && typeof r.key === "string" && r.pending !== undefined) pending[r.key] = r.pending;
    }
    return { config: (config ?? null) as Record<string, unknown> | null, pending, error: null };
  } catch (e) {
    return { config: null, pending: {}, error: String((e as Error)?.message ?? e).slice(0, 160) };
  }
}

export async function liveSnapshots(s: ServerLike): Promise<{ snaps: { name: string; description?: string; snaptime?: number; vmstate?: number }[] | null; error: string | null }> {
  if (!s.vmid) return { snaps: [], error: null };
  if (!s.node) return { snaps: null, error: "Server has no node row (legacy)." };
  try {
    const snaps = await withTimeout(listSnapshotsOn(pveForNode(s.node), s.vmid));
    return { snaps, error: null };
  } catch (e) {
    return { snaps: null, error: String((e as Error)?.message ?? e).slice(0, 160) };
  }
}

/** Node row for a server, falling back to the primary node for legacy (nodeId null) rows. */
export async function nodeForServer(nodeId: string | null) {
  if (nodeId) return db.node.findUnique({ where: { id: nodeId } });
  return db.node.findFirst({ where: { isPrimary: true } });
}

