"use client";

import { useEffect, useId, useRef, useState, useTransition } from "react";
import { useRouter } from "next/navigation";

/**
 * The one confirmation pattern every mutating control on the redesigned admin
 * server / client pages uses. Inline (not a modal — no backdrop-filter
 * containing-block trap, see CLAUDE.md), keyboard-first:
 *   - the trigger is a real <button>; opening moves focus to the first field
 *   - Esc cancels, Enter in the last field submits
 *   - the confirm button stays disabled until the reason is long enough and the
 *     typed confirmation matches EXACTLY (the server re-checks both)
 *   - every open gets a fresh idempotency key, so a double click or a retried
 *     request is a no-op server-side
 * Errors render inline with role="alert"; success refreshes the page data.
 */
export type RunResult = { ok: boolean; error?: string; message?: string } | null | undefined | void;

function newIdem(): string {
  try {
    return crypto.randomUUID().replace(/-/g, "");
  } catch {
    return Math.random().toString(36).slice(2) + Date.now().toString(36);
  }
}

export function ActionPanel({
  label,
  title,
  description,
  tone = "secondary",
  needsReason = true,
  confirmText,
  confirmHint,
  run,
  successText = "Done.",
  disabled,
  disabledReason,
  small,
  children,
  canSubmit = true,
}: {
  label: string;
  title?: string;
  description?: React.ReactNode;
  tone?: "primary" | "secondary" | "danger" | "ghost";
  needsReason?: boolean;
  /** exact text the admin must type (e.g. the hostname) */
  confirmText?: string;
  confirmHint?: string;
  run: (reason: string, typed: string, idem: string) => Promise<RunResult>;
  successText?: string;
  disabled?: boolean;
  disabledReason?: string;
  small?: boolean;
  /** extra fields rendered above the reason (controlled by the caller) */
  children?: React.ReactNode;
  /** caller-side validity of the extra fields */
  canSubmit?: boolean;
}) {
  const [open, setOpen] = useState(false);
  const [reason, setReason] = useState("");
  const [typed, setTyped] = useState("");
  const [idem, setIdem] = useState("");
  const [msg, setMsg] = useState<{ tone: "ok" | "err"; text: string } | null>(null);
  const [pending, start] = useTransition();
  const router = useRouter();
  const firstRef = useRef<HTMLDivElement>(null);
  const uid = useId();

  useEffect(() => {
    if (!open) return;
    const el = firstRef.current?.querySelector<HTMLElement>("input, select, textarea, button");
    el?.focus();
  }, [open]);

  const reasonOk = !needsReason || reason.trim().length >= 4;
  const typedOk = !confirmText || typed.trim() === confirmText;
  const ready = reasonOk && typedOk && canSubmit && !pending;

  const btn = tone === "danger" ? "btn-danger" : tone === "primary" ? "btn-primary" : tone === "ghost" ? "btn-ghost" : "btn-secondary";
  const size = small ? "py-1 px-2.5 text-xs" : "py-1.5 text-sm";

  function submit() {
    if (!ready) return;
    setMsg(null);
    start(async () => {
      try {
        const r = await run(reason.trim(), typed.trim(), idem);
        if (r && r.ok === false) {
          setMsg({ tone: "err", text: r.error ?? "That did not work." });
          return;
        }
        setMsg({ tone: "ok", text: (r && r.message) || successText });
        setOpen(false);
        setReason("");
        setTyped("");
        router.refresh();
      } catch (e) {
        // NEXT_REDIRECT is thrown on purpose by some actions (delete → list); let it go.
        const m = String((e as Error)?.message ?? e);
        if (m.includes("NEXT_REDIRECT")) throw e;
        setMsg({ tone: "err", text: m.slice(0, 300) });
      }
    });
  }

  if (!open) {
    return (
      <span className="inline-flex flex-col items-start gap-1">
        <button
          type="button"
          className={`${btn} ${size}`}
          disabled={disabled}
          title={disabled ? disabledReason : undefined}
          onClick={() => {
            setIdem(newIdem());
            setMsg(null);
            setOpen(true);
          }}
        >
          {label}
        </button>
        {msg && (
          <span role={msg.tone === "err" ? "alert" : "status"} className={`text-xs ${msg.tone === "err" ? "text-red-400" : "text-emerald-400"}`}>
            {msg.text}
          </span>
        )}
      </span>
    );
  }

  return (
    <div
      className={`w-full max-w-xl rounded-xl border p-3 text-sm ${tone === "danger" ? "border-red-500/30 bg-red-500/[0.05]" : "border-white/10 bg-white/[0.03]"}`}
      role="group"
      aria-labelledby={`${uid}-t`}
      onKeyDown={(e) => {
        if (e.key === "Escape") {
          e.stopPropagation();
          setOpen(false);
        }
      }}
    >
      <p id={`${uid}-t`} className={`font-semibold ${tone === "danger" ? "text-red-300" : ""}`}>{title ?? label}</p>
      {description && <div className="mt-1 text-xs text-slate-400">{description}</div>}
      <div ref={firstRef} className="mt-3 space-y-2">
        {children}
        {needsReason && (
          <label className="block">
            <span className="mb-1 block text-xs text-slate-400">Reason (audit log)</span>
            <input
              className="input w-full py-1.5 text-sm"
              value={reason}
              maxLength={300}
              onChange={(e) => setReason(e.target.value)}
              placeholder="e.g. ticket #1234 — customer asked"
              onKeyDown={(e) => {
                if (e.key === "Enter" && !confirmText) submit();
              }}
            />
          </label>
        )}
        {confirmText && (
          <label className="block">
            <span className="mb-1 block text-xs text-slate-400">
              {confirmHint ?? "Type"} <code className="rounded bg-black/30 px-1 font-mono text-[11px] text-slate-200">{confirmText}</code> to confirm
            </span>
            <input
              className="input w-full py-1.5 font-mono text-xs"
              value={typed}
              onChange={(e) => setTyped(e.target.value)}
              autoComplete="off"
              spellCheck={false}
              onKeyDown={(e) => {
                if (e.key === "Enter") submit();
              }}
            />
          </label>
        )}
      </div>
      <div className="mt-3 flex flex-wrap items-center gap-2">
        <button type="button" className={`${btn} py-1.5 text-sm`} disabled={!ready} onClick={submit} aria-busy={pending}>
          {pending ? "Working…" : title ? label : `Confirm ${label.replace(/…$/, "").toLowerCase()}`}
        </button>
        <button type="button" className="btn-ghost py-1.5 text-sm" onClick={() => setOpen(false)} disabled={pending}>
          Cancel
        </button>
        {!reasonOk && needsReason && <span className="text-[11px] text-slate-500">Reason needs 4+ characters.</span>}
      </div>
      {msg && (
        <p role={msg.tone === "err" ? "alert" : "status"} className={`mt-2 text-xs ${msg.tone === "err" ? "text-red-400" : "text-emerald-400"}`}>
          {msg.text}
        </p>
      )}
    </div>
  );
}

