"use client";

import { useState } from "react";
import { ActionPanel } from "./ActionPanel";
import {
  adminRevealRootPassword,
  adminDeleteServer,
  adminReinstallServer,
  adminSnapshotAction,
  adminBackupNow,
  adminRestoreBackup,
  adminAddPortForward,
  adminRemovePortForward,
  adminAddFirewallRule,
  adminFirewallRuleAction,
  adminChangeSubdomain,
  adminServiceAction,
} from "@/lib/actions-admin-server";

/* Small, single-purpose client controls for the admin server page tabs. Each
   one is a thin binding of ActionPanel to exactly one audited server action in
   lib/actions-admin-server.ts — no business logic lives here. */

export function RevealRootPassword({ serverId }: { serverId: string }) {
  const [pw, setPw] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);
  if (pw) {
    return (
      <div className="flex flex-wrap items-center gap-2" aria-live="polite">
        <code className="rounded-lg bg-black/40 px-2 py-1 font-mono text-xs text-slate-100">{pw}</code>
        <button
          type="button"
          className="btn-ghost py-1 text-xs"
          onClick={() => {
            navigator.clipboard?.writeText(pw).then(() => setCopied(true), () => setCopied(false));
          }}
        >
          {copied ? "Copied" : "Copy"}
        </button>
        <button type="button" className="btn-ghost py-1 text-xs" onClick={() => setPw(null)}>
          Hide
        </button>
      </div>
    );
  }
  return (
    <ActionPanel
      label="Reveal root password…"
      title="Reveal root password"
      description="Your name, IP, time and reason are written to the audit log. The password itself is never logged."
      small
      successText="Revealed."
      run={async (reason) => {
        const r = await adminRevealRootPassword(serverId, reason);
        if (r.ok) setPw(r.password);
        return r.ok ? { ok: true } : r;
      }}
    />
  );
}

export function DeleteServerControl({ serverId, hostname }: { serverId: string; hostname: string }) {
  return (
    <ActionPanel
      label="Delete server…"
      title={`Delete ${hostname}`}
      tone="danger"
      confirmText={hostname}
      confirmHint="Type the hostname"
      description="Queues the DELETE job. Read the manifest above first — this cannot be undone."
      run={(reason, typed, idem) => adminDeleteServer(serverId, typed, reason, idem)}
    />
  );
}

export function ReinstallControl({ serverId, hostname, templates, currentId, disabled, disabledReason }: {
  serverId: string;
  hostname: string;
  templates: { id: string; name: string }[];
  currentId: string;
  disabled?: boolean;
  disabledReason?: string;
}) {
  const [os, setOs] = useState(currentId);
  return (
    <ActionPanel
      label="Reinstall OS…"
      title="Reinstall operating system"
      tone="danger"
      confirmText={hostname}
      confirmHint="Type the hostname"
      disabled={disabled}
      disabledReason={disabledReason}
      description="Wipes the system disk and installs a fresh image. Refused while data volumes are assigned to this server."
      canSubmit={!!os}
      run={(reason, typed, idem) => adminReinstallServer(serverId, os, typed, reason, idem)}
    >
      <label className="block">
        <span className="mb-1 block text-xs text-slate-400">Image</span>
        <select className="input w-full py-1.5 text-sm" value={os} onChange={(e) => setOs(e.target.value)}>
          {templates.map((t) => (
            <option key={t.id} value={t.id}>
              {t.name}
            </option>
          ))}
        </select>
      </label>
    </ActionPanel>
  );
}

export function SnapshotCreate({ serverId, disabled, disabledReason }: { serverId: string; disabled?: boolean; disabledReason?: string }) {
  const [name, setName] = useState("");
  const valid = /^[A-Za-z0-9_]{1,40}$/.test(name);
  return (
    <ActionPanel
      label="Take snapshot…"
      title="Take a Proxmox snapshot"
      description="Queues SNAPSHOT_CREATE. Snapshots live on the VM's own storage (not a backup) and are NOT carried by a node move."
      canSubmit={valid}
      disabled={disabled}
      disabledReason={disabledReason}
      run={(reason) => adminSnapshotAction(serverId, "create", name, reason)}
    >
      <label className="block">
        <span className="mb-1 block text-xs text-slate-400">Name (letters, digits, _ — max 40)</span>
        <input className="input w-full py-1.5 font-mono text-xs" value={name} onChange={(e) => setName(e.target.value)} placeholder="before_upgrade" />
      </label>
    </ActionPanel>
  );
}

export function SnapshotRowActions({ serverId, name, disabled }: { serverId: string; name: string; disabled?: boolean }) {
  return (
    <div className="flex flex-wrap justify-end gap-2">
      <ActionPanel
        label="Roll back…"
        title={`Roll back to ${name}`}
        tone="danger"
        small
        disabled={disabled}
        confirmText={name}
        confirmHint="Type the snapshot name"
        description="Everything written since this snapshot is lost."
        run={(reason, typed) => adminSnapshotAction(serverId, "rollback", name, reason, typed)}
      />
      <ActionPanel
        label="Delete…"
        title={`Delete snapshot ${name}`}
        tone="ghost"
        small
        disabled={disabled}
        confirmText={name}
        confirmHint="Type the snapshot name"
        run={(reason, typed) => adminSnapshotAction(serverId, "delete", name, reason, typed)}
      />
    </div>
  );
}

export function BackupNowControl({ serverId, disabled, disabledReason }: { serverId: string; disabled?: boolean; disabledReason?: string }) {
  return (
    <ActionPanel
      label="Back up now…"
      title="Create a backup now"
      tone="primary"
      disabled={disabled}
      disabledReason={disabledReason}
      description="Queues BACKUP_CREATE (vzdump to the backup storage). Progress appears in Activity."
      run={(reason, _t, idem) => adminBackupNow(serverId, reason, idem)}
    />
  );
}

export function RestoreBackupControl({ serverId, hostname, volid, disabled }: { serverId: string; hostname: string; volid: string; disabled?: boolean }) {
  return (
    <ActionPanel
      label="Restore…"
      title="Restore this backup"
      tone="danger"
      small
      disabled={disabled}
      confirmText={hostname}
      confirmHint="Type the hostname"
      description={<>The live disk is replaced with <code className="font-mono">{volid}</code>. Anything written after it was taken is lost.</>}
      run={(reason, typed, idem) => adminRestoreBackup(serverId, volid, typed, reason, idem)}
    />
  );
}

export function AddPortForwardControl({ serverId }: { serverId: string }) {
  const [port, setPort] = useState("");
  const [proto, setProto] = useState<"tcp" | "udp">("tcp");
  const n = Number(port);
  const valid = Number.isInteger(n) && n >= 1 && n <= 65535;
  return (
    <ActionPanel
      label="Add forward…"
      title="Add a port forward"
      description="A free public port is allocated automatically (unique across the fleet). NAT rules are re-synced by the worker."
      canSubmit={valid}
      run={(reason) => adminAddPortForward(serverId, n, proto, reason)}
    >
      <div className="flex gap-2">
        <label className="flex-1">
          <span className="mb-1 block text-xs text-slate-400">Guest port</span>
          <input className="input w-full py-1.5 font-mono text-xs" inputMode="numeric" value={port} onChange={(e) => setPort(e.target.value.replace(/\D/g, "").slice(0, 5))} placeholder="25565" />
        </label>
        <label>
          <span className="mb-1 block text-xs text-slate-400">Protocol</span>
          <select className="input py-1.5 text-sm" value={proto} onChange={(e) => setProto(e.target.value as "tcp" | "udp")}>
            <option value="tcp">TCP</option>
            <option value="udp">UDP</option>
          </select>
        </label>
      </div>
    </ActionPanel>
  );
}

export function RemovePortForwardControl({ serverId, forwardId, label }: { serverId: string; forwardId: string; label: string }) {
  return (
    <ActionPanel
      label="Remove…"
      title={`Remove forward ${label}`}
      tone="ghost"
      small
      run={(reason) => adminRemovePortForward(serverId, forwardId, reason)}
    />
  );
}

export function AddFirewallRuleControl({ serverId }: { serverId: string }) {
  const [r, setR] = useState({ action: "ALLOW" as "ALLOW" | "DENY", protocol: "TCP" as "TCP" | "UDP" | "ICMP" | "ALL", portFrom: "", portTo: "", sourceCidr: "", comment: "" });
  const set = (k: keyof typeof r) => (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => setR({ ...r, [k]: e.target.value });
  return (
    <ActionPanel
      label="Add rule…"
      title="Add platform firewall rule"
      description="Validated by the same rule checker the worker uses. Port 22 always stays reachable."
      run={(reason) => adminAddFirewallRule(serverId, r, reason)}
    >
      <div className="grid grid-cols-2 gap-2 sm:grid-cols-3">
        <label>
          <span className="mb-1 block text-xs text-slate-400">Action</span>
          <select className="input w-full py-1.5 text-sm" value={r.action} onChange={set("action")}>
            <option>ALLOW</option>
            <option>DENY</option>
          </select>
        </label>
        <label>
          <span className="mb-1 block text-xs text-slate-400">Protocol</span>
          <select className="input w-full py-1.5 text-sm" value={r.protocol} onChange={set("protocol")}>
            <option>TCP</option>
            <option>UDP</option>
            <option>ICMP</option>
            <option>ALL</option>
          </select>
        </label>
        <label>
          <span className="mb-1 block text-xs text-slate-400">Port from</span>
          <input className="input w-full py-1.5 font-mono text-xs" value={r.portFrom} onChange={set("portFrom")} placeholder="80" />
        </label>
        <label>
          <span className="mb-1 block text-xs text-slate-400">Port to</span>
