/** Tab information architecture for /admin/servers/[id] and /admin/users/[id]. PURE. */

export const SERVER_TABS = [
  { key: "overview", label: "Overview" },
  { key: "network", label: "Network" },
  { key: "access", label: "Access" },
  { key: "compute", label: "Compute" },
  { key: "software", label: "Software" },
  { key: "files", label: "Files" },
  { key: "backups", label: "Backups" },
  { key: "game", label: "Game", gameOnly: true },
  { key: "move", label: "Transfer / Move" },
  { key: "billing", label: "Billing" },
  { key: "activity", label: "Activity" },
  { key: "danger", label: "Danger", danger: true },
] as const;
export type ServerTabKey = (typeof SERVER_TABS)[number]["key"];

/** Older deep links (?tab=…) that must keep working. */
const SERVER_TAB_ALIASES: Record<string, ServerTabKey> = {
  ip: "network",
  ips: "network",
  firewall: "network",
  ports: "network",
  ssh: "access",
  console: "access",
  power: "compute",
  snapshots: "compute",
  apps: "software",
  services: "software",
  docker: "software",
  transfer: "move",
  migrate: "move",
  jobs: "activity",
  audit: "activity",
  delete: "danger",
};

export function serverTabsFor(isGame: boolean) {
  return SERVER_TABS.filter((t) => !("gameOnly" in t && t.gameOnly) || isGame);
}

export function resolveServerTab(raw: string | string[] | undefined, isGame: boolean): ServerTabKey {
  const v = (Array.isArray(raw) ? raw[0] : raw ?? "").toLowerCase();
  const key = (SERVER_TAB_ALIASES[v] ?? v) as ServerTabKey;
  const allowed = serverTabsFor(isGame).map((t) => t.key as string);
  return allowed.includes(key) ? key : "overview";
}

export const CLIENT_TABS = [
  { key: "profile", label: "Profile & risk" },
  { key: "servers", label: "Servers" },
  { key: "billing", label: "Billing" },
  { key: "support", label: "Support" },
  { key: "security", label: "Activity & security" },
  { key: "partner", label: "Partner & referrals" },
  { key: "actions", label: "Actions", danger: true },
] as const;
export type ClientTabKey = (typeof CLIENT_TABS)[number]["key"];

const CLIENT_TAB_ALIASES: Record<string, ClientTabKey> = {
  risk: "profile",
  notes: "profile",
  wallet: "billing",
  invoices: "billing",
  tickets: "support",
  emails: "support",
  activity: "security",
  sessions: "security",
  referrals: "partner",
};

export function resolveClientTab(raw: string | string[] | undefined): ClientTabKey {
  const v = (Array.isArray(raw) ? raw[0] : raw ?? "").toLowerCase();
  const key = (CLIENT_TAB_ALIASES[v] ?? v) as ClientTabKey;
  return (CLIENT_TABS.map((t) => t.key as string).includes(key) ? key : "profile") as ClientTabKey;
}

