"use client";

import Link from "next/link";
import { useRef } from "react";

/**
 * URL-driven tab bar (?tab=…) for the admin server and client 360 pages.
 * Real links (deep-linkable, work without JS, middle-click opens a tab) styled
 * with the admin shell's `.adm-subtabs` / `.adm-subtab` classes. Left/Right/
 * Home/End move focus between tabs, matching the WAI-ARIA tabs keyboard model
 * without pretending links are buttons.
 */
export function TabBar({
  base,
  tabs,
  active,
  badges,
  label,
}: {
  base: string;
  tabs: { key: string; label: string; danger?: boolean }[];
  active: string;
  badges?: Record<string, number | string | undefined>;
  label: string;
}) {
  const ref = useRef<HTMLElement>(null);
  function onKey(e: React.KeyboardEvent) {
    const links = Array.from(ref.current?.querySelectorAll<HTMLAnchorElement>("a") ?? []);
    const i = links.indexOf(document.activeElement as HTMLAnchorElement);
    if (i < 0) return;
    let n = -1;
    if (e.key === "ArrowRight") n = (i + 1) % links.length;
    else if (e.key === "ArrowLeft") n = (i - 1 + links.length) % links.length;
    else if (e.key === "Home") n = 0;
    else if (e.key === "End") n = links.length - 1;
    if (n >= 0) {
      e.preventDefault();
      links[n].focus();
    }
  }
  return (
    <nav ref={ref} aria-label={label} className="adm-subtabs" onKeyDown={onKey} data-testid="tabbar">
      {tabs.map((t) => {
        const b = badges?.[t.key];
        return (
          <Link
            key={t.key}
            href={t.key === tabs[0].key ? base : `${base}?tab=${t.key}`}
            className="adm-subtab"
            aria-current={t.key === active ? "page" : undefined}
            scroll={false}
            prefetch={false}
            style={t.danger ? { color: t.key === active ? "var(--adm-red)" : undefined } : undefined}
          >
            {t.label}
            {b !== undefined && b !== 0 && b !== "" && (
              <span className="adm-count" data-tone={typeof b === "string" ? "red" : undefined}>
                {b}
              </span>
            )}
          </Link>
        );
      })}
    </nav>
  );
}

