import "server-only";
import { cache } from "react";
import { db } from "@/lib/db";

/**
 * The one server row every tab of /admin/servers/[id] starts from. React
 * `cache` dedupes it across the page header and whichever tab renders, so a
 * page view is ONE query for the core plus each tab's own extras — the old
 * page loaded everything (25 jobs, all forwards, live stats, renewal quote)
 * whether or not it was shown.
 */
export const loadServerCore = cache(async (id: string) => {
  return db.server.findUnique({
    where: { id },
    include: {
      user: { select: { id: true, email: true, name: true, role: true, suspended: true, balanceCents: true } },
      plan: true,
      gamePlan: { select: { id: true, name: true, priceCents: true, termMonths: true, cpuCores: true, ramMB: true, diskGB: true, gameFamily: true } },
      osTemplate: true,
      node: true,
      dedicatedIp: { select: { id: true, address: true, reverse: true, nodeId: true, status: true } },
      gameRuntime: true,
      jobs: { where: { status: { in: ["QUEUED", "RUNNING"] } }, orderBy: { createdAt: "desc" }, take: 1 },
      _count: { select: { portForwards: true, firewallRules: true, volumes: true, websites: true, vpsDatabases: true, appInstalls: true, playerSessions: true } },
    },
  });
});

export type ServerCore = NonNullable<Awaited<ReturnType<typeof loadServerCore>>>;

export function gameFamilyOf(s: ServerCore): string | null {
  return s.gamePlan?.gameFamily ?? null;
}

export function planRamMB(s: ServerCore): number {
  return s.gamePlan?.ramMB ?? s.plan.ramMB;
}
export function planCpu(s: ServerCore): number {
  return s.gamePlan?.cpuCores ?? s.plan.cpuCores;
}

export function publicEndpoint(s: ServerCore): string | null {
  if (s.dedicatedIp) return s.dedicatedIp.address;
  const ip = s.node?.publicIp ?? process.env.PUBLIC_IP ?? null;
  return ip;
}

