/* Server-safe layout atoms shared by the server + client 360 tabs. */
import Link from "next/link";
import type { TruthTone } from "@/lib/admin-server/state-truth";

export function Fields({ children, cols = 3 }: { children: React.ReactNode; cols?: 2 | 3 | 4 }) {
  const c = cols === 2 ? "sm:grid-cols-2" : cols === 4 ? "sm:grid-cols-2 lg:grid-cols-4" : "sm:grid-cols-2 lg:grid-cols-3";
  return <dl className={`grid grid-cols-1 gap-x-6 gap-y-3 text-sm ${c}`}>{children}</dl>;
}

export function Field({ label, children, mono, hint }: { label: string; children: React.ReactNode; mono?: boolean; hint?: React.ReactNode }) {
  return (
    <div className="min-w-0">
