"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { applyFix } from "@/lib/admin-ops/actions";

/** One-click, non-destructive fix through the Admin Ops library (audited there as adminops.fix). */
export function FixButton({ serverId, fix, label }: { serverId: string; fix: "reconcile_status" | "start_vm" | "restart_game_service" | "sync_forwards" | "sync_game_dns"; label: string }) {
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null);
  const router = useRouter();
  return (
    <span className="inline-flex flex-wrap items-center gap-2">
      <button
        type="button"
        className="btn-secondary px-2.5 py-1 text-xs"
        disabled={pending}
        onClick={() =>
          start(async () => {
            const r = await applyFix(serverId, fix).catch((e) => ({ ok: false as const, error: String(e?.message ?? e) }));
            setMsg(r.ok ? { ok: true, text: r.message } : { ok: false, text: r.error });
            router.refresh();
          })
        }
      >
        {pending ? "Working…" : label}
      </button>
      {msg && (
        <span role={msg.ok ? "status" : "alert"} className={`text-xs ${msg.ok ? "text-emerald-400" : "text-red-400"}`}>
          {msg.text}
        </span>
      )}
    </span>
  );
}

