import Link from "next/link";
import { db } from "@/lib/db";
import { fmtBytes, fmtMoney, timeAgo } from "@/components/ui/primitives";
import { MeterBar } from "@/components/ui/charts";
import { effectiveDiskGB, baseDiskGBFor } from "@/lib/extra-disk";
import { monthlyCents } from "@/lib/admin-metrics";
import { REGION_LABELS } from "@/lib/node-regions";
import { SuspendServerButton, ReconcileServerButton } from "@/components/AdminControls";
import { PowerActions } from "@/components/admin/ServerAdminActions";
import { ImpersonateButton } from "@/components/admin/ImpersonateButton";
import { evaluateStateTruth } from "@/lib/admin-server/state-truth";
import { liveVm } from "@/lib/admin-server/live";
import { Card, Field, Fields, ToneBox, fmtDate } from "../ui";
import { FixButton } from "../FixButton";
import { type ServerCore, planCpu, planRamMB, publicEndpoint } from "../core";

const FIX_MAP = { reconcile: "reconcile_status", start: "start_vm", restart_game: "restart_game_service", sync_forwards: "sync_forwards" } as const;

export async function OverviewTab({ server, isGame }: { server: ServerCore; isGame: boolean }) {
  const [{ reading, raw }, memSample, diskSample] = await Promise.all([
    liveVm(server),
    db.serverMemSample.findFirst({ where: { serverId: server.id }, orderBy: { ts: "desc" }, select: { usedBytes: true, totalBytes: true, ts: true } }),
    db.serverDiskSample.findFirst({ where: { serverId: server.id }, orderBy: { ts: "desc" }, select: { usedBytes: true, totalBytes: true, ts: true } }).catch(() => null),
  ]);
  const activeJob = server.jobs[0] ?? null;
  const truth = evaluateStateTruth({
    dbStatus: server.status,
    provisionError: server.provisionError,
    suspendReason: server.suspendReason,
    isGame,
    proxmox: reading,
    runtime: server.gameRuntime
      ? { state: server.gameRuntime.state, probedAt: server.gameRuntime.probedAt, intent: server.gameRuntime.intent, probeError: server.gameRuntime.probeError }
      : null,
    activeJob: activeJob ? { type: activeJob.type, status: activeJob.status, updatedAt: activeJob.updatedAt } : null,
    updatedAt: server.updatedAt,
  });

  const livePlanMonthly = server.gamePlan ? monthlyCents(server.gamePlan.priceCents, server.gamePlan.termMonths) : server.plan.priceCents;
  const effectiveMonthly =
    server.grandfatheredRenewalCents != null
      ? server.gamePlan
        ? monthlyCents(server.grandfatheredRenewalCents, server.gamePlan.termMonths)
        : server.grandfatheredRenewalCents
      : livePlanMonthly;
  const endpoint = publicEndpoint(server);
  const daysLeft = server.expiresAt ? Math.ceil((server.expiresAt.getTime() - Date.now()) / 86_400_000) : null;
  const uptime = raw?.uptime ? `${Math.floor(raw.uptime / 86400)}d ${Math.floor((raw.uptime % 86400) / 3600)}h` : "—";

  return (
    <div className="space-y-4">
      {/* State truth */}
      <Card
        title="State truth"
        sub="What each source of truth says right now. Disagreements are listed below with the existing fix for each."
        action={<Link href={`/admin/ops/servers/${server.id}`} className="btn-ghost py-1 text-xs">Full diagnosis →</Link>}
      >
        <div className="grid gap-3 sm:grid-cols-3">
          {truth.sources.map((s) => (
            <ToneBox key={s.key} tone={s.tone}>
              <p className="text-[11px] uppercase tracking-wide opacity-75">{s.label}</p>
              <p className="mt-0.5 font-semibold">{s.value}</p>
              {s.detail && <p className="mt-0.5 text-xs opacity-80">{s.detail}</p>}
            </ToneBox>
          ))}
        </div>
        {truth.mismatches.length === 0 ? (
          <p className="mt-3 text-xs text-emerald-400">All sources agree.</p>
        ) : (
          <ul className="mt-3 space-y-2" aria-label="Mismatches">
            {truth.mismatches.map((m) => (
              <li key={m.code} className="flex flex-wrap items-center justify-between gap-2 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2 text-sm">
                <span className={m.severity === "critical" ? "text-red-300" : m.severity === "warning" ? "text-amber-300" : "text-slate-400"}>
                  <span className="mr-2 text-[10px] font-semibold uppercase tracking-wide">{m.severity}</span>
                  {m.message}
                </span>
                {m.fix && m.fix !== "diagnose" && <FixButton serverId={server.id} fix={FIX_MAP[m.fix]} label={m.fix === "reconcile" ? "Reconcile" : m.fix === "restart_game" ? "Restart game" : m.fix === "start" ? "Start VM" : "Resync"} />}
                {m.fix === "diagnose" && (
                  <Link href={`/admin/ops/servers/${server.id}`} className="btn-secondary px-2.5 py-1 text-xs">
                    Diagnose
                  </Link>
                )}
              </li>
            ))}
          </ul>
        )}
      </Card>

      <div className="grid gap-4 xl:grid-cols-3">
        <Card title="Placement & plan" className="xl:col-span-2">
          <Fields>
            <Field label="Node">
              {server.node ? (
                <Link href={`/admin/nodes/${server.node.id}`} className="hover:text-brand-300">
                  {server.node.name}
                </Link>
              ) : (
                "— (legacy, primary)"
              )}
            </Field>
            <Field label="Region">{server.node ? REGION_LABELS[server.node.region] ?? server.node.region : "—"}</Field>
            <Field label="VMID" mono>{server.vmid ?? "—"}</Field>
            <Field label="Public endpoint" mono hint={server.dedicatedIp ? "dedicated IPv4" : "NAT via node IP"}>
              {endpoint ? `${endpoint}${!server.dedicatedIp && server.sshPort ? `:${server.sshPort}` : ""}` : "—"}
            </Field>
            <Field label="Private IP" mono>{server.ipAddress ?? "—"}</Field>
            <Field label="OS / variant">{server.osTemplate.name}{server.gameVariant ? ` · ${server.gameVariant}` : ""}</Field>
            <Field label="Plan">{server.gamePlan ? server.gamePlan.name : server.plan.name}</Field>
            <Field label="Resources" hint={server.extraDiskGB > 0 ? `${baseDiskGBFor(server)} GB plan + ${server.extraDiskGB} GB added` : undefined}>
              {planCpu(server)} vCPU · {(planRamMB(server) / 1024).toFixed(1)} GB RAM · {effectiveDiskGB(baseDiskGBFor(server), server.extraDiskGB)} GB
            </Field>
            <Field label="Created">{fmtDate(server.createdAt)}</Field>
          </Fields>
        </Card>

        <Card title="Live">
          {reading.kind === "vm" ? (
            <div className="space-y-3 text-sm">
              <div>
                <div className="mb-1 flex justify-between text-xs text-slate-400">
                  <span>CPU</span>
                  <span>{((raw?.cpu ?? 0) * 100).toFixed(1)}% of {raw?.cpus ?? planCpu(server)} vCPU</span>
                </div>
                <MeterBar value={(raw?.cpu ?? 0) * 100} max={100} color="#8a70fb" />
              </div>
              <div>
                <div className="mb-1 flex justify-between text-xs text-slate-400">
                  <span>Memory (guest)</span>
                  <span>{memSample && memSample.totalBytes > 0n ? `${fmtBytes(Number(memSample.usedBytes))} / ${fmtBytes(Number(memSample.totalBytes))}` : "not measured yet"}</span>
                </div>
                {memSample && memSample.totalBytes > 0n && <MeterBar value={Number(memSample.usedBytes)} max={Number(memSample.totalBytes)} color="#3b82f6" />}
              </div>
              {diskSample && diskSample.totalBytes > 0n && (
                <div>
                  <div className="mb-1 flex justify-between text-xs text-slate-400">
                    <span>Disk (guest)</span>
                    <span>{fmtBytes(Number(diskSample.usedBytes))} / {fmtBytes(Number(diskSample.totalBytes))}</span>
                  </div>
                  <MeterBar value={Number(diskSample.usedBytes)} max={Number(diskSample.totalBytes)} color="#3edcf2" />
                </div>
              )}
              <dl className="space-y-1.5 pt-1 text-xs">
                <div className="flex justify-between"><dt className="text-slate-500">Uptime</dt><dd>{uptime}</dd></div>
                <div className="flex justify-between"><dt className="text-slate-500">Net in / out</dt><dd className="font-mono">{fmtBytes(raw?.netin ?? 0)} / {fmtBytes(raw?.netout ?? 0)}</dd></div>
                <div className="flex justify-between"><dt className="text-slate-500">Bandwidth this window</dt><dd className="font-mono">{fmtBytes(Number(server.bwInBytes))} / {fmtBytes(Number(server.bwOutBytes))}</dd></div>
                {memSample && <div className="flex justify-between"><dt className="text-slate-500">Memory sampled</dt><dd>{timeAgo(memSample.ts)}</dd></div>}
              </dl>
            </div>
          ) : (
            <p className="py-4 text-sm text-slate-500">
              {reading.kind === "none" ? "No VM has been provisioned yet." : reading.kind === "missing" ? "The node has no VM with this id." : `Proxmox did not answer (${reading.error ?? "unreachable"}).`}
            </p>
          )}
        </Card>
      </div>

      <div className="grid gap-4 xl:grid-cols-2">
        <Card title="Owner" action={<Link href={`/admin/users/${server.user.id}`} className="btn-ghost py-1 text-xs">Customer 360 →</Link>}>
          <Fields cols={2}>
            <Field label="Email">{server.user.email}</Field>
            <Field label="Name">{server.user.name}</Field>
            <Field label="Wallet">{fmtMoney(server.user.balanceCents)}</Field>
            <Field label="Account">{server.user.suspended ? <span className="text-red-400">suspended</span> : "active"}</Field>
          </Fields>
          {server.user.role !== "ADMIN" && (
            <div className="mt-3">
              <ImpersonateButton userId={server.user.id} email={server.user.email} small />
            </div>
          )}
        </Card>
        <Card title="Billing summary" action={<Link href={`/admin/servers/${server.id}?tab=billing`} className="btn-ghost py-1 text-xs">Billing →</Link>}>
          <Fields cols={2}>
            <Field label="Renews at">
              {server.isFree ? "free — never renews" : `${fmtMoney(effectiveMonthly)}/mo before add-ons`}
              {server.grandfatheredRenewalCents != null && !server.isFree && <span className="ml-1 text-xs text-brand-300">(locked)</span>}
            </Field>
            <Field label="Expires" hint={daysLeft != null && !server.isFree ? (daysLeft >= 0 ? `${daysLeft} day${daysLeft === 1 ? "" : "s"} left` : `${-daysLeft} days overdue`) : undefined}>
              {server.isFree ? "never" : fmtDate(server.expiresAt)}
            </Field>
            <Field label="Auto-renew">{server.isFree ? "n/a" : server.autoRenew ? "on" : "off"}</Field>
            <Field label="Dunning">{server.dunningStage > 0 ? `stage ${server.dunningStage}` : "none"}</Field>
          </Fields>
        </Card>
      </div>

      <Card title="Quick actions" sub="Power actions queue a job for the worker — one in-flight job per server. Destructive actions live on the Danger tab.">
        <div className="flex flex-wrap items-center gap-x-6 gap-y-3">
          <PowerActions serverId={server.id} status={server.status} activeJob={activeJob ? { type: activeJob.type, status: activeJob.status } : null} />
          {["ERROR", "PENDING", "PROVISIONING"].includes(server.status) && <ReconcileServerButton serverId={server.id} />}
          <SuspendServerButton serverId={server.id} suspended={server.status === "SUSPENDED"} />
        </div>
      </Card>
    </div>
  );
}

