  const activeJob = server.jobs[0] ?? null;
  const truth = evaluateStateTruth({
    dbStatus: server.status,
    provisionError: server.provisionError,
    suspendReason: server.suspendReason,
    isGame,
    proxmox: reading,
    runtime: server.gameRuntime
      ? { state: server.gameRuntime.state, probedAt: server.gameRuntime.probedAt, intent: server.gameRuntime.intent, probeError: server.gameRuntime.probeError }
      : null,
    activeJob: activeJob ? { type: activeJob.type, status: activeJob.status, updatedAt: activeJob.updatedAt } : null,
    updatedAt: server.updatedAt,
  });

  const livePlanMonthly = server.gamePlan ? monthlyCents(server.gamePlan.priceCents, server.gamePlan.termMonths) : server.plan.priceCents;
  const effectiveMonthly =
    server.grandfatheredRenewalCents != null
      ? server.gamePlan
        ? monthlyCents(server.grandfatheredRenewalCents, server.gamePlan.termMonths)
        : server.grandfatheredRenewalCents
      : livePlanMonthly;
  const endpoint = publicEndpoint(server);
  const daysLeft = server.expiresAt ? Math.ceil((server.expiresAt.getTime() - Date.now()) / 86_400_000) : null;
  const uptime = raw?.uptime ? `${Math.floor(raw.uptime / 86400)}d ${Math.floor((raw.uptime % 86400) / 3600)}h` : "—";

  return (
    <div className="space-y-4">
      {/* State truth */}
      <Card
        title="State truth"
        sub="What each source of truth says right now. Disagreements are listed below with the existing fix for each."
        action={<Link href={`/admin/ops/servers/${server.id}`} className="btn-ghost py-1 text-xs">Full diagnosis →</Link>}
      >
        <div className="grid gap-3 sm:grid-cols-3">
          {truth.sources.map((s) => (
            <ToneBox key={s.key} tone={s.tone}>
              <p className="text-[11px] uppercase tracking-wide opacity-75">{s.label}</p>
              <p className="mt-0.5 font-semibold">{s.value}</p>
              {s.detail && <p className="mt-0.5 text-xs opacity-80">{s.detail}</p>}
            </ToneBox>
          ))}
        </div>
        {truth.mismatches.length === 0 ? (
          <p className="mt-3 text-xs text-emerald-400">All sources agree.</p>
        ) : (
          <ul className="mt-3 space-y-2" aria-label="Mismatches">
            {truth.mismatches.map((m) => (
              <li key={m.code} className="flex flex-wrap items-center justify-between gap-2 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2 text-sm">
                <span className={m.severity === "critical" ? "text-red-300" : m.severity === "warning" ? "text-amber-300" : "text-slate-400"}>
                  <span className="mr-2 text-[10px] font-semibold uppercase tracking-wide">{m.severity}</span>
                  {m.message}
                </span>
                {m.fix && m.fix !== "diagnose" && <FixButton serverId={server.id} fix={FIX_MAP[m.fix]} label={m.fix === "reconcile" ? "Reconcile" : m.fix === "restart_game" ? "Restart game" : m.fix === "start" ? "Start VM" : "Resync"} />}
                {m.fix === "diagnose" && (
                  <Link href={`/admin/ops/servers/${server.id}`} className="btn-secondary px-2.5 py-1 text-xs">
                    Diagnose
                  </Link>
                )}
              </li>
            ))}
          </ul>
        )}
      </Card>

      <div className="grid gap-4 xl:grid-cols-3">
        <Card title="Placement & plan" className="xl:col-span-2">
          <Fields>
            <Field label="Node">
              {server.node ? (
                <Link href={`/admin/nodes/${server.node.id}`} className="hover:text-brand-300">
                  {server.node.name}
                </Link>
              ) : (
                "— (legacy, primary)"
              )}
            </Field>
            <Field label="Region">{server.node ? REGION_LABELS[server.node.region] ?? server.node.region : "—"}</Field>
            <Field label="VMID" mono>{server.vmid ?? "—"}</Field>
            <Field label="Public endpoint" mono hint={server.dedicatedIp ? "dedicated IPv4" : "NAT via node IP"}>
              {endpoint ? `${endpoint}${!server.dedicatedIp && server.sshPort ? `:${server.sshPort}` : ""}` : "—"}
            </Field>
            <Field label="Private IP" mono>{server.ipAddress ?? "—"}</Field>
            <Field label="OS / variant">{server.osTemplate.name}{server.gameVariant ? ` · ${server.gameVariant}` : ""}</Field>
            <Field label="Plan">{server.gamePlan ? server.gamePlan.name : server.plan.name}</Field>
            <Field label="Resources" hint={server.extraDiskGB > 0 ? `${baseDiskGBFor(server)} GB plan + ${server.extraDiskGB} GB added` : undefined}>
              {planCpu(server)} vCPU · {(planRamMB(server) / 1024).toFixed(1)} GB RAM · {effectiveDiskGB(baseDiskGBFor(server), server.extraDiskGB)} GB
