/** Set reverse DNS for this server's dedicated IP (same upstream call /admin/ips makes). */
export async function adminSetReverseDns(serverId: string, reverse: string, reason: string): Promise<Ok> {
  const admin = await gate("fleet");
  const p = z
    .object({ serverId: idSchema, reverse: z.string().min(3).max(253).regex(/^(?=.{3,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}\.?$/i) })
    .safeParse({ serverId, reverse: reverse.trim() });
  if (!p.success) return { ok: false, error: "Enter a valid hostname (e.g. mail.example.com)." };
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4–300 characters)." };
  if (process.env.NXEON_SANDBOX === "1") return { ok: false, error: "Sandbox: reverse DNS changes are not sent upstream here." };
  const rl = limited(admin.id, "rdns", 10, 10 * 60_000);
  if (rl) return { ok: false, error: rl };
  const ip = await db.dedicatedIp.findFirst({ where: { serverId }, select: { address: true, reverse: true } });
  if (!ip) return { ok: false, error: "This server has no dedicated IP — NAT addresses have no per-server reverse DNS." };
  const fd = new FormData();
  fd.set("address", ip.address);
  fd.set("reverse", p.data.reverse);
  const { setIpReverse } = await import("@/lib/actions-ovh");
  const res = await setIpReverse(null, fd);
  if (res?.error) return { ok: false, error: res.error };
  await audit(admin.id, "admin.server.rdns_set", serverId, `${ip.address} PTR ${ip.reverse ?? "—"} → ${p.data.reverse} — ${why}`);
  revalidate(serverId);
  return { ok: true };
}

// ─── Software ────────────────────────────────────────────────────────────────

