"use client";

import { useState } from "react";
import { runGuestCommand } from "@/lib/admin-ops/actions";
import { useOpJob } from "@/components/admin/ops/shared";

/**
 * Run ONE read-only, allowlisted guest command (lib/admin-ops/guest-commands
 * GUEST_COMMANDS) and show its output inline. The command runs as an
 * ADMIN_OPS job on the worker over guest SSH — the web app never shells in.
 */
export function GuestCommandButton({ serverId, command, label, params, disabled, disabledReason }: {
  serverId: string;
  command: string;
  label: string;
  params?: Record<string, string | number>;
  disabled?: boolean;
  disabledReason?: string;
}) {
  const [jobId, setJobId] = useState<string | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [starting, setStarting] = useState(false);
  const { job, busy } = useOpJob(jobId);
  const out = job?.result as { output?: string; exitCode?: number | null; truncated?: boolean } | null;
  return (
    <div className="space-y-2">
      <button
        type="button"
        className="btn-secondary px-2.5 py-1 text-xs"
        disabled={disabled || busy || starting}
        title={disabled ? disabledReason : undefined}
        onClick={async () => {
          setErr(null);
          setStarting(true);
          const r = await runGuestCommand(serverId, command, params ?? {}).catch((e) => ({ ok: false as const, error: String(e?.message ?? e) }));
          setStarting(false);
          if (r.ok) setJobId(r.jobId);
          else setErr(r.error);
        }}
      >
        {busy || starting ? "Running…" : label}
      </button>
      {err && <p role="alert" className="text-xs text-red-400">{err}</p>}
      {job && job.status === "FAILED" && <p role="alert" className="text-xs text-red-400">{job.error ?? "The command failed."}</p>}
      {out?.output != null && (
        <pre className="max-h-80 overflow-auto whitespace-pre-wrap break-all rounded-lg bg-black/40 p-3 font-mono text-[11px] text-slate-300" aria-live="polite">
          {out.output || "(no output)"}
          {out.truncated ? "\n… output truncated" : ""}
        </pre>
      )}
    </div>
  );
}

