  ctx: { sshPort: number | null; guestSshPort: number | null; portRange: [number, number] | null; hasDedicatedIp: boolean },
): Map<string, string[]> {
  const out = new Map<string, string[]>();
  const add = (id: string, msg: string) => out.set(id, [...(out.get(id) ?? []), msg]);
  const seen = new Map<string, string>();
  for (const r of rows) {
    const key = `${r.protocol.toLowerCase()}/${r.guestPort}`;
    const prev = seen.get(key);
    if (prev) {
      add(r.id, `Duplicate: guest ${key} is already forwarded`);
      add(prev, `Duplicate: guest ${key} is forwarded twice`);
    } else seen.set(key, r.id);
    if (ctx.sshPort != null && r.publicPort === ctx.sshPort) add(r.id, "Public port collides with this server's SSH port");
    const sshGuest = ctx.guestSshPort ?? 22;
    if (r.guestPort === sshGuest && r.protocol.toLowerCase() === "tcp") add(r.id, "Forwards the guest's SSH port a second time");
    if (ctx.portRange && (r.publicPort < ctx.portRange[0] || r.publicPort > ctx.portRange[1])) add(r.id, `Public port outside the node's range ${ctx.portRange[0]}–${ctx.portRange[1]}`);
    if (ctx.hasDedicatedIp) add(r.id, "Server has a dedicated IP — NAT forwards are not used for its traffic");
  }
  return out;
}
