import { db } from "@/lib/db";
import { timeAgo } from "@/components/ui/primitives";
import { ResetPasswordButton, CopyText } from "@/components/customer/ServerAccess";
import { ServerConsole } from "@/components/admin/ServerConsole";
import { ImpersonateButton } from "@/components/admin/ImpersonateButton";
import { Card, Empty, Field, Fields, DeepLink, fmtDateTime } from "../ui";
import { RevealRootPassword } from "../controls";
import { type ServerCore, publicEndpoint } from "../core";

function keySummary(pub: string): string {
  const parts = pub.trim().split(/\s+/);
  const body = parts[1] ?? parts[0] ?? "";
  return `${parts[0] ?? "key"} …${body.slice(-16)}${parts[2] ? ` ${parts[2]}` : ""}`;
}

export async function AccessTab({ server }: { server: ServerCore }) {
  const [keys, logins, reveals] = await Promise.all([
    db.sshKey.findMany({ where: { userId: server.userId }, orderBy: { createdAt: "desc" }, select: { id: true, name: true, publicKey: true, createdAt: true } }),
    db.telemetryEvent.findMany({
      where: { serverId: server.id, type: { in: ["SSH_LOGIN", "SSH_FAILED", "SSH_LOGOUT"] } },
      orderBy: { ts: "desc" },
      take: 20,
      select: { id: true, type: true, ts: true, ip: true, user: true },
    }),
    db.auditLog.findMany({
      where: { target: server.id, action: "admin.server.credential_reveal" },
      orderBy: { createdAt: "desc" },
      take: 10,
      select: { id: true, createdAt: true, detail: true, ip: true, user: { select: { email: true } } },
    }),
  ]);
  const host = server.dedicatedIp?.address ?? publicEndpoint(server);
  const port = server.dedicatedIp ? server.guestSshPort ?? 22 : server.sshPort;
  const sshCmd = host && port ? `ssh root@${host} -p ${port}` : null;
  const busy = !!server.jobs[0];

  return (
    <div className="space-y-4">
      <div className="grid gap-4 xl:grid-cols-2">
        <Card title="SSH">
          <Fields cols={2}>
            <Field label="Host" mono>{host ?? "—"}</Field>
            <Field label="Port" mono>{port ?? "—"}</Field>
            <Field label="User" mono>root</Field>
            <Field label="Management key" hint="platform key the worker uses for guest SSH">
              {server.sshManagementPublicKey ? "installed" : <span className="text-amber-300">none — worker falls back to password</span>}
            </Field>
          </Fields>
          {sshCmd && (
            <div className="mt-3">
              <CopyText text={sshCmd} label={sshCmd} />
            </div>
          )}
        </Card>

        <Card title="Credentials" sub="Revealing is audited (who, when, IP, reason). Reset queues PASSWORD_RESET — the customer's current password stops working.">
          <div className="space-y-3">
            <RevealRootPassword serverId={server.id} />
            <ResetPasswordButton serverId={server.id} disabled={busy || !["RUNNING", "STOPPED"].includes(server.status)} />
          </div>
          {reveals.length > 0 && (
            <div className="mt-4 border-t border-white/[0.06] pt-3">
              <p className="mb-1 text-xs text-slate-500">Recent reveals</p>
              <ul className="space-y-1 text-xs">
                {reveals.map((r) => (
                  <li key={r.id} className="text-slate-400">
                    <span className="text-slate-200">{r.user?.email ?? "?"}</span> · {timeAgo(r.createdAt)}
                    {r.ip ? ` · ${r.ip}` : ""} — <span className="text-slate-500">{(r.detail ?? "").replace(/^.*?—\s*/, "")}</span>
                  </li>
                ))}
              </ul>
            </div>
          )}
        </Card>
      </div>

      <div className="grid gap-4 xl:grid-cols-2">
        <Card title={`Owner's SSH keys (${keys.length})`} sub="Keys on the customer account, offered at provision/reinstall time. Read-only here.">
          {keys.length === 0 ? (
            <Empty>The customer has no SSH keys saved.</Empty>
          ) : (
            <ul className="space-y-2 text-sm">
              {keys.map((k) => (
                <li key={k.id} className="flex flex-wrap items-baseline justify-between gap-2">
                  <span className="font-medium">{k.name}</span>
                  <span className="font-mono text-[11px] text-slate-500">{keySummary(k.publicKey)}</span>
                </li>
              ))}
            </ul>
          )}
        </Card>

        <Card title="Recent SSH activity" sub="From the guest telemetry agent (where installed).">
          {logins.length === 0 ? (
            <Empty>No SSH events reported for this server.</Empty>
          ) : (
            <ul className="space-y-1 text-xs">
              {logins.map((e) => (
                <li key={e.id} className="flex flex-wrap justify-between gap-2">
                  <span className={e.type === "SSH_FAILED" ? "text-red-300" : e.type === "SSH_LOGIN" ? "text-emerald-300" : "text-slate-400"}>
                    {e.type.replace("SSH_", "").toLowerCase()} {e.user ? `· ${e.user}` : ""}
                  </span>
                  <span className="font-mono text-slate-500">{e.ip ?? "—"} · {fmtDateTime(e.ts)}</span>
                </li>
              ))}
            </ul>
          )}
        </Card>
      </div>

      <Card
        title="Console"
        sub="VNC console through Proxmox (only while running). The web terminal lives in the customer view."
        action={
          <div className="flex flex-wrap items-center gap-3">
            <DeepLink href={`/dashboard/servers/${server.id}?tab=console`}>Web terminal</DeepLink>
            {server.user.role !== "ADMIN" && <ImpersonateButton userId={server.user.id} email={server.user.email} small />}
          </div>
        }
      >
        {server.vmid && server.status === "RUNNING" ? <ServerConsole serverId={server.id} /> : <Empty>The console is available while the server is running.</Empty>}
      </Card>
    </div>
  );
}

