import { db } from "@/lib/db";
import { Badge, timeAgo } from "@/components/ui/primitives";
import { PowerActions } from "@/components/admin/ServerAdminActions";
import { effectiveDiskGB, baseDiskGBFor } from "@/lib/extra-disk";
import { balloonPolicy, pinVerdict, guaranteedMB, ramGuardMode } from "@/lib/vm-memory-policy";
import { liveVmConfig, liveSnapshots } from "@/lib/admin-server/live";
import { Card, Empty, Field, Fields, DeepLink, Unavailable } from "../ui";
import { SnapshotCreate, SnapshotRowActions, ReinstallControl } from "../controls";
import { type ServerCore, planCpu, planRamMB } from "../core";

/** Config keys shown in the summary, in this order (anything else is under "all keys"). */
const SUMMARY_KEYS = ["cores", "sockets", "cpu", "memory", "balloon", "machine", "ostype", "bios", "scsihw", "boot", "agent", "onboot", "net0", "scsi0", "virtio0", "ide2", "tags"];

function n(v: unknown): number | null {
  const x = Number(v);
  return Number.isFinite(x) ? x : null;
}

export async function ComputeTab({ server }: { server: ServerCore }) {
  const [{ config, pending, error: cfgErr }, { snaps, error: snapErr }, volumes, templates] = await Promise.all([
    liveVmConfig(server),
    liveSnapshots(server),
    db.volume.findMany({ where: { serverId: server.id }, orderBy: { createdAt: "asc" }, select: { id: true, name: true, sizeGB: true, status: true, mountPath: true, inUse: true } }),
    db.osTemplate.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { name: "asc" }], select: { id: true, name: true, version: true, category: true } }),
  ]);
  const activeJob = server.jobs[0] ?? null;
  const busy = !!activeJob;
  const isGame = !!server.gamePlanId;

  const memoryMB = config ? n(config.memory) : null;
  const balloonMB = config ? n(config.balloon) : null;
  const pendingBalloon = pending.balloon !== undefined ? n(pending.balloon) : null;
  const verdict = memoryMB != null ? pinVerdict({ memoryMB, balloonMB, pendingBalloonMB: pendingBalloon, planRamMB: planRamMB(server) }) : null;
  const floor = memoryMB != null ? guaranteedMB(memoryMB, balloonMB) : null;
  const pendingKeys = Object.keys(pending);

  return (
    <div className="space-y-4">
      <Card title="Power" sub="Queues a job for the worker; one in-flight job per server.">
        <PowerActions serverId={server.id} status={server.status} activeJob={activeJob ? { type: activeJob.type, status: activeJob.status } : null} />
      </Card>

      <div className="grid gap-4 xl:grid-cols-2">
        <Card title="Resources (entitlement)">
          <Fields cols={2}>
            <Field label="vCPU">{planCpu(server)}</Field>
            <Field label="RAM">{(planRamMB(server) / 1024).toFixed(1)} GB</Field>
            <Field label="Disk" hint={server.extraDiskGB > 0 ? `${baseDiskGBFor(server)} GB plan + ${server.extraDiskGB} GB added (permanent)` : undefined}>
              {effectiveDiskGB(baseDiskGBFor(server), server.extraDiskGB)} GB
            </Field>
            <Field label="Bandwidth">{server.plan.bandwidthTB} TB/mo</Field>
          </Fields>
          <div className="mt-3 space-y-1 text-xs text-slate-500">
            <p>
              Resize and disk expansion are customer purchases (they charge the customer&apos;s wallet/card) — an admin comp-resize path is not built yet.{" "}
              <DeepLink href={`/dashboard/servers/${server.id}?tab=settings`}>Customer settings</DeepLink>
            </p>
            <p>Rescue mode does not exist on this platform yet; use the VNC console (Access tab) or a snapshot rollback.</p>
          </div>
        </Card>

        <Card title="Memory policy" sub={`Balloon policy: ${balloonPolicy()} · node RAM guard: ${ramGuardMode()}`}>
          {cfgErr ? (
            <Unavailable>VM config not readable: {cfgErr}</Unavailable>
          ) : verdict ? (
            <div className="space-y-2 text-sm">
              <p>
                <Badge tone={verdict.action === "ok" ? "green" : verdict.action === "pending-restart" ? "amber" : "red"}>{verdict.action.replace("-", " ")}</Badge>{" "}
                <span className="text-xs text-slate-400">{verdict.note}</span>
              </p>
              <Fields cols={2}>
                <Field label="memory (config)" mono>{memoryMB} MB</Field>
                <Field label="balloon (config)" mono>{balloonMB == null ? "unset" : `${balloonMB} MB`}</Field>
                <Field label="guaranteed floor" mono>{floor} MB</Field>
                <Field label="plan RAM" mono>{planRamMB(server)} MB</Field>
              </Fields>
              {verdict.action === "pending-restart" && <p className="text-xs text-amber-300">The pin is pending — it applies on the next cold stop + start (not a reboot).</p>}
              {verdict.action === "pin" && <p className="text-xs text-red-300">Proxmox may balloon this VM below what the customer paid for. The fleet pin script (scripts/pin-vm-memory.ts) fixes it on the next rollout.</p>}
            </div>
          ) : (
            <Empty>No VM yet.</Empty>
          )}
        </Card>
      </div>

      <Card title="VM config (Proxmox)" sub={server.node ? `Read live from ${server.node.name}` : undefined}>
        {cfgErr ? (
          <Unavailable>{cfgErr}</Unavailable>
        ) : config ? (
          <>
            <Fields cols={3}>
              {SUMMARY_KEYS.filter((k) => config[k] !== undefined).map((k) => (
                <Field key={k} label={k} mono>
                  <span className="break-all text-xs">{String(config[k])}</span>
                  {pending[k] !== undefined && <span className="ml-1 text-[11px] text-amber-300">→ {String(pending[k])} (pending)</span>}
                </Field>
              ))}
            </Fields>
            {pendingKeys.length > 0 && <p className="mt-3 text-xs text-amber-300">{pendingKeys.length} pending change(s) apply on the next cold start: {pendingKeys.join(", ")}</p>}
            <details className="mt-3">
              <summary className="cursor-pointer text-xs text-slate-400">All config keys</summary>
              <pre className="mt-2 max-h-72 overflow-auto rounded-lg bg-black/30 p-3 font-mono text-[11px] text-slate-400">
                {Object.entries(config)
                  .filter(([k]) => !/^(cipassword|sshkeys)$/i.test(k)) // never echo credentials
                  .sort(([a], [b]) => a.localeCompare(b))
                  .map(([k, v]) => `${k}: ${String(v)}`)
                  .join("\n")}
              </pre>
            </details>
          </>
        ) : (
          <Empty>No VM yet.</Empty>
        )}
      </Card>

      <Card
        title="Snapshots"
        sub="Proxmox snapshots on the VM's own storage. Not a backup, and not carried over by a node move."
        action={<SnapshotCreate serverId={server.id} disabled={busy || !server.vmid} disabledReason="Needs a VM and no job in flight" />}
      >
        {snapErr ? (
          <Unavailable>Snapshots not readable: {snapErr}</Unavailable>
        ) : !snaps || snaps.length === 0 ? (
          <Empty>No snapshots.</Empty>
        ) : (
          <div className="overflow-x-auto">
            <table className="table-shell">
              <thead>
                <tr>
                  <th>Name</th>
                  <th>Taken</th>
                  <th>RAM state</th>
                  <th>Description</th>
                  <th className="text-right">Actions</th>
                </tr>
              </thead>
              <tbody>
                {snaps.map((s) => (
                  <tr key={s.name}>
                    <td className="font-mono text-xs">{s.name}</td>
                    <td className="text-xs text-slate-400">{s.snaptime ? timeAgo(new Date(s.snaptime * 1000)) : "—"}</td>
                    <td className="text-xs">{s.vmstate ? "yes" : "no"}</td>
                    <td className="max-w-56 truncate text-xs text-slate-400">{s.description ?? ""}</td>
                    <td className="text-right">
                      <SnapshotRowActions serverId={server.id} name={s.name} disabled={busy} />
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </Card>

      <div className="grid gap-4 xl:grid-cols-2">
        <Card title={`Volumes (${volumes.length})`} sub="Block-storage volumes assigned to this server (billed separately). Attach/detach is in the customer view.">
          {volumes.length === 0 ? (
            <Empty>No volumes.</Empty>
          ) : (
            <ul className="space-y-1.5 text-sm">
              {volumes.map((v) => (
                <li key={v.id} className="flex flex-wrap justify-between gap-2">
                  <span>
                    {v.name} <span className="text-xs text-slate-500">· {v.sizeGB} GB{v.mountPath ? ` · ${v.mountPath}` : ""}</span>
                  </span>
                  <Badge tone={v.status === "ATTACHED" ? "green" : "slate"}>{v.status.toLowerCase()}</Badge>
                </li>
              ))}
            </ul>
          )}
        </Card>

        <Card title="Reinstall" sub={isGame ? "Game servers reinstall their game, not the OS — use the customer view's game settings." : "Wipes the system disk. Typed hostname + reason required."}>
          {isGame ? (
            <DeepLink href={`/dashboard/servers/${server.id}?tab=settings`}>Game reinstall (customer view)</DeepLink>
          ) : (
            <ReinstallControl
              serverId={server.id}
              hostname={server.hostname}
              currentId={server.osTemplateId}
              templates={templates.map((t) => ({ id: t.id, name: `${t.name}${t.version ? ` ${t.version}` : ""}${t.id === server.osTemplateId ? " (current)" : ""}` }))}
              disabled={busy || !["RUNNING", "STOPPED"].includes(server.status) || volumes.length > 0}
              disabledReason={volumes.length > 0 ? "Volumes are assigned — reinstall would destroy them" : "Server must be running or stopped with no job in flight"}
            />
          )}
        </Card>
      </div>
    </div>
  );
}

