import { Suspense } from "react";
import { db } from "@/lib/db";
import { Badge, StatusDot } from "@/components/ui/primitives";
import { PanelSkeleton } from "@/components/admin/shell/primitives";
import { getServiceStatuses } from "@/lib/actions-cron";
import { ServerOpsPanel } from "@/components/admin/ops/ServerOpsPanel";
import { withTimeout } from "@/lib/admin-server/live";
import { Card, Empty, DeepLink, Unavailable, fmtDate } from "../ui";
import { GuestCommandButton } from "../GuestCommandButton";
import { ServiceControl } from "../controls";
import type { ServerCore } from "../core";

async function ServicesCard({ server }: { server: ServerCore }) {
  let services: { unit: string; label: string; state: string }[] | null = null;
  let error: string | null = null;
  if (server.status !== "RUNNING") error = "Service status is read over guest SSH, so only while the server is running.";
  else {
    try {
      const r = await withTimeout(getServiceStatuses(server.id), 12_000);
      if (r.ok) services = r.services;
      else error = r.error;
    } catch (e) {
      error = String((e as Error)?.message ?? e);
    }
  }
  return (
    <Card title="Common services" sub="systemd state of the platform-managed services (read over guest SSH). Start/stop/restart are audited and queued.">
      {error ? (
        <Unavailable>{error}</Unavailable>
      ) : !services || services.length === 0 ? (
        <Empty>No services reported.</Empty>
      ) : (
        <div className="overflow-x-auto">
          <table className="table-shell">
            <thead>
              <tr>
                <th>Service</th>
                <th>Unit</th>
                <th>State</th>
                <th className="text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {services.map((s) => (
                <tr key={s.unit}>
                  <td>{s.label}</td>
                  <td className="font-mono text-xs text-slate-400">{s.unit}</td>
                  <td>
                    <Badge tone={s.state === "running" ? "green" : s.state === "stopped" ? "amber" : "slate"}>{s.state}</Badge>
                  </td>
                  <td className="text-right">{s.state !== "not-installed" && <ServiceControl serverId={server.id} unit={s.unit} active={s.state === "running"} />}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </Card>
  );
}

export async function SoftwareTab({ server, isGame }: { server: ServerCore; isGame: boolean }) {
  const [websites, databases, apps, crons, certs] = await Promise.all([
    db.website.findMany({ where: { serverId: server.id }, orderBy: { createdAt: "asc" }, select: { id: true, domain: true, ssl: true, enabled: true, status: true, phpVersion: true, appSlug: true, error: true } }),
    db.vpsDatabase.findMany({ where: { serverId: server.id }, orderBy: { createdAt: "asc" }, select: { id: true, engine: true, name: true, dbUser: true, status: true, error: true } }),
    db.appInstall.findMany({ where: { serverId: server.id }, orderBy: { createdAt: "asc" }, select: { id: true, appSlug: true, domain: true, url: true, status: true, error: true } }),
    db.cronJob.findMany({ where: { serverId: server.id }, orderBy: { createdAt: "asc" }, select: { id: true, schedule: true, command: true, enabled: true, status: true, comment: true } }),
    db.sslCertificate.findMany({ where: { serverId: server.id }, orderBy: { createdAt: "desc" }, select: { id: true, domain: true, status: true, issuer: true, expiresAt: true, autoRenew: true, lastError: true } }),
  ]);
  const running = server.status === "RUNNING";
  const busy = !!server.jobs[0];
  const off = !running || busy;
  const offWhy = "Server must be running with no job in flight";

  return (
    <div className="space-y-4">
      <Card title="Containers & processes (read-only discovery)" sub="Runs an allowlisted, read-only command over guest SSH on the worker and shows the output. Nothing is changed.">
        <div className="grid gap-4 lg:grid-cols-2">
          <GuestCommandButton serverId={server.id} command="docker_ps" label="Docker containers (incl. compose projects)" disabled={off} disabledReason={offWhy} />
          <GuestCommandButton serverId={server.id} command="failed_units" label="Failed systemd units" disabled={off} disabledReason={offWhy} />
          <GuestCommandButton serverId={server.id} command="top_cpu" label="Top processes by CPU" disabled={off} disabledReason={offWhy} />
          <GuestCommandButton serverId={server.id} command="listening" label="Listening sockets" disabled={off} disabledReason={offWhy} />
        </div>
        <p className="mt-3 text-[11px] text-slate-500">Compose projects appear as the com.docker.compose.project label in the container list. Container logs, journals, OOM and disk tools are in the full guest tools below.</p>
      </Card>

      {!isGame && (
        <Suspense fallback={<PanelSkeleton rows={4} title="Common services" />}>
          <ServicesCard server={server} />
        </Suspense>
      )}

      <div className="grid gap-4 xl:grid-cols-2">
        <Card title={`Websites (${websites.length})`} action={<DeepLink href={`/dashboard/servers/${server.id}?tab=services`}>Manage in customer view</DeepLink>}>
          {websites.length === 0 ? (
            <Empty>No websites managed by the platform on this server.</Empty>
          ) : (
            <ul className="space-y-1.5 text-sm">
              {websites.map((w) => (
                <li key={w.id} className="flex flex-wrap items-center justify-between gap-2">
                  <span className="font-mono text-xs">{w.domain}{w.appSlug ? <span className="ml-1 text-slate-500">({w.appSlug})</span> : null}</span>
                  <span className="flex items-center gap-1.5">
                    {w.ssl && <Badge tone="green">ssl</Badge>}
                    {!w.enabled && <Badge tone="slate">disabled</Badge>}
                    <StatusDot status={w.status} />
                  </span>
                  {w.error && <span className="w-full text-xs text-red-400">{w.error.slice(0, 200)}</span>}
                </li>
              ))}
            </ul>
          )}
        </Card>

        <Card title={`SSL certificates (${certs.length})`}>
          {certs.length === 0 ? (
            <Empty>No certificates recorded for this server.</Empty>
          ) : (
            <ul className="space-y-1.5 text-sm">
              {certs.map((c) => (
                <li key={c.id} className="flex flex-wrap items-center justify-between gap-2">
                  <span className="font-mono text-xs">{c.domain}</span>
                  <span className="text-xs text-slate-400">
                    {c.issuer} · expires {fmtDate(c.expiresAt)} {c.autoRenew ? "· auto-renew" : ""}
                  </span>
                  <Badge tone={c.status === "ACTIVE" ? "green" : c.status === "FAILED" || c.status === "EXPIRED" ? "red" : "amber"}>{c.status.toLowerCase()}</Badge>
                  {c.lastError && <span className="w-full text-xs text-red-400">{c.lastError.slice(0, 200)}</span>}
                </li>
              ))}
            </ul>
          )}
        </Card>

        <Card title={`Databases (${databases.length})`}>
          {databases.length === 0 ? (
            <Empty>No platform-managed databases.</Empty>
          ) : (
            <ul className="space-y-1.5 text-sm">
              {databases.map((d) => (
                <li key={d.id} className="flex flex-wrap items-center justify-between gap-2">
                  <span className="font-mono text-xs">
                    {d.engine}:{d.name} <span className="text-slate-500">user {d.dbUser}</span>
                  </span>
                  <StatusDot status={d.status} />
                  {d.error && <span className="w-full text-xs text-red-400">{d.error.slice(0, 200)}</span>}
                </li>
              ))}
            </ul>
          )}
        </Card>

        <Card title={`One-click apps (${apps.length})`}>
          {apps.length === 0 ? (
            <Empty>No one-click apps installed.</Empty>
          ) : (
            <ul className="space-y-1.5 text-sm">
              {apps.map((a) => (
                <li key={a.id} className="flex flex-wrap items-center justify-between gap-2">
                  <span>
                    {a.appSlug} <span className="font-mono text-xs text-slate-500">{a.url ?? a.domain}</span>
                  </span>
                  <StatusDot status={a.status} />
                  {a.error && <span className="w-full text-xs text-red-400">{a.error.slice(0, 200)}</span>}
                </li>
              ))}
            </ul>
          )}
        </Card>
      </div>

      <Card title={`Cron jobs (${crons.length})`}>
        {crons.length === 0 ? (
          <Empty>No platform-managed cron jobs.</Empty>
        ) : (
          <div className="overflow-x-auto">
            <table className="table-shell">
              <thead>
                <tr>
                  <th>Schedule</th>
                  <th>Command</th>
                  <th>Comment</th>
                  <th>State</th>
                </tr>
              </thead>
              <tbody>
                {crons.map((c) => (
                  <tr key={c.id} className={c.enabled ? "" : "opacity-60"}>
                    <td className="font-mono text-xs">{c.schedule}</td>
                    <td className="max-w-md truncate font-mono text-xs" title={c.command}>{c.command}</td>
                    <td className="text-xs text-slate-400">{c.comment ?? ""}</td>
                    <td><StatusDot status={c.status} /></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </Card>

      <div>
        <h2 className="mb-2 text-sm font-semibold text-slate-300">Full guest tools</h2>
        <ServerOpsPanel serverId={server.id} sections={["guest"]} />
      </div>
    </div>
  );
}

