/**
 * Record that an admin opened the customer's files (the file manager itself
 * goes through the existing owner-or-ADMIN file API, which does not audit
 * individual operations). One row per session-with-reason, so access to a
 * customer's data is always attributable.
 */
export async function adminOpenFileManager(serverId: string, reason: string): Promise<Ok> {
  const admin = await gate("fleet");
  if (!idSchema.safeParse(serverId).success) return { ok: false, error: "Invalid server." };
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4–300 characters) — it goes in the audit log." };
  const rl = limited(admin.id, "files", 20, 10 * 60_000);
  if (rl) return { ok: false, error: rl };
  const s = await loadServer(serverId);
  if (!s) return { ok: false, error: "Server not found." };
  if (s.status !== "RUNNING") return { ok: false, error: "Files are reached over SFTP, so the server must be running." };
  await audit(admin.id, "admin.server.files_open", s.id, `${s.hostname}: file manager opened — ${why}`);
  return { ok: true };
}

