"use client";

import { useState } from "react";
import { ServerFileBrowser } from "@/components/customer/files/FileBrowser";
import { adminOpenFileManager } from "@/lib/actions-admin-server";
import { ActionPanel } from "./ActionPanel";

/** The customer's file manager, opened only after an audited reason. */
export function FilesPanel({ serverId, running }: { serverId: string; running: boolean }) {
  const [open, setOpen] = useState(false);
  if (open) {
    return (
      <div className="adm-files rounded-xl border border-white/10 p-2">
        <ServerFileBrowser serverId={serverId} initialPath="/" />
      </div>
    );
  }
  return (
    <ActionPanel
      label="Open file manager…"
      title="Open the customer's files"
      tone="primary"
      disabled={!running}
      disabledReason="The server must be running (files are reached over SFTP)"
      description="Opening is recorded in the audit log with your reason. Edits, uploads and deletes act on the live server immediately."
      run={async (reason) => {
        const r = await adminOpenFileManager(serverId, reason);
        if (r.ok) setOpen(true);
        return r;
      }}
      successText="Opened."
    />
  );
}

