import { db } from "@/lib/db";
import { timeAgo } from "@/components/ui/primitives";
import { Card, DeepLink } from "../ui";
import { FilesPanel } from "../FilesPanel";
import type { ServerCore } from "../core";

export async function FilesTab({ server }: { server: ServerCore }) {
  const recent = await db.auditLog.findMany({
    where: { target: server.id, action: "admin.server.files_open" },
    orderBy: { createdAt: "desc" },
    take: 5,
    select: { id: true, createdAt: true, detail: true, user: { select: { email: true } } },
  });
  return (
    <div className="space-y-4">
      <Card
        title="File manager"
        sub="SFTP into the guest as root, through the same file API the customer uses."
        action={<DeepLink href={`/dashboard/servers/${server.id}?tab=files`}>Open in customer view</DeepLink>}
      >
        <FilesPanel serverId={server.id} running={server.status === "RUNNING"} />
        {recent.length > 0 && (
          <div className="mt-4 border-t border-white/[0.06] pt-3">
            <p className="mb-1 text-xs text-slate-500">Recent admin access</p>
            <ul className="space-y-1 text-xs text-slate-400">
              {recent.map((r) => (
                <li key={r.id}>
                  <span className="text-slate-200">{r.user?.email ?? "?"}</span> · {timeAgo(r.createdAt)} — {(r.detail ?? "").replace(/^.*?—\s*/, "")}
                </li>
              ))}
            </ul>
          </div>
        )}
      </Card>
      <p className="text-xs text-slate-500">
        Game world files are in the same tree (see the Game tab for the world/backup tools). For large transfers give the customer SFTP details from the Access tab instead.
      </p>
    </div>
  );
}

