import { db } from "@/lib/db";
import { Badge, StatusDot, fmtBytes, timeAgo } from "@/components/ui/primitives";
import { listServerBackups } from "@/lib/actions-server-ops";
import { readPlatformBackups } from "@/lib/platform-backups";
import { BACKUP_INTERVAL_CHOICES } from "@/lib/backup-intervals";
import { withTimeout } from "@/lib/admin-server/live";
import { Card, Empty, Field, Fields, Unavailable, fmtDateTime } from "../ui";
import { BackupNowControl, RestoreBackupControl, BackupScheduleControl } from "../controls";
import type { ServerCore } from "../core";

export async function BackupsTab({ server }: { server: ServerCore }) {
  const [list, platform, jobs] = await Promise.all([
    withTimeout(listServerBackups(server.id), 10_000).catch((e) => ({ error: String((e as Error)?.message ?? e), backups: undefined })),
    readPlatformBackups().catch(() => null),
    db.job.findMany({
      where: { serverId: server.id, type: { in: ["BACKUP_CREATE", "BACKUP_RESTORE"] } },
      orderBy: { createdAt: "desc" },
      take: 8,
      select: { id: true, type: true, status: true, progress: true, step: true, error: true, createdAt: true },
    }),
  ]);
  const busy = !!server.jobs[0];
  const offsite = platform?.subsystems.find((s) => s.key === "offsite") ?? null;
  const vmSub = platform?.subsystems.find((s) => s.key === "vm") ?? null;
  const verify = platform?.subsystems.find((s) => s.key === "verify-restore") ?? null;
  const coverageAge = server.vmid != null ? platform?.coverageByVmid?.[server.vmid] ?? null : null;

  return (
    <div className="space-y-4">
      <div className="grid gap-4 xl:grid-cols-3">
        <Card title="Schedule" action={<BackupScheduleControl serverId={server.id} enabled={server.autoBackup} hours={server.backupIntervalHours} choices={[...BACKUP_INTERVAL_CHOICES]} />}>
          <Fields cols={2}>
            <Field label="Automatic">{server.autoBackup ? `every ${server.backupIntervalHours ?? "?"} h` : "off"}</Field>
            <Field label="Last automatic">{server.lastAutoBackup ? timeAgo(server.lastAutoBackup) : "never"}</Field>
            <Field label="Tier">{server.backupTier === "PLUS" ? "Backup Plus" : "Free"}</Field>
            <Field label="Keep">{server.backupKeep ?? "default"}</Field>
          </Fields>
        </Card>
        <Card title="Platform / off-site" sub="Node-level snapshot of every guest, shipped off-site. Read from the backup status files.">
          {!platform || !platform.available ? (
            <Unavailable>Platform backup status is not readable from this host.</Unavailable>
          ) : (
            <Fields cols={2}>
              <Field label="This VM's newest platform archive">{coverageAge != null ? `${Math.round(coverageAge / 3_600_000)} h old` : <span className="text-amber-300">none found</span>}</Field>
              <Field label="Platform VM backup">{vmSub ? `${vmSub.ok === false ? "FAILED" : vmSub.ok ? "ok" : "unknown"}${vmSub.ageMs != null ? ` · ${Math.round(vmSub.ageMs / 3_600_000)} h ago` : ""}` : "—"}</Field>
              <Field label="Off-site copy">{offsite ? `${offsite.ok === false ? "FAILED" : offsite.ok ? "ok" : "unknown"}${offsite.ageMs != null ? ` · ${Math.round(offsite.ageMs / 3_600_000)} h ago` : ""}` : "—"}</Field>
              <Field label="Restore test">{verify ? `${verify.ok === false ? "FAILED" : verify.ok ? "ok" : "unknown"}` : "—"}</Field>
            </Fields>
          )}
        </Card>
        <Card title="Back up now">
          <BackupNowControl serverId={server.id} disabled={busy || !server.vmid} disabledReason="Needs a VM and no job in flight" />
          <p className="mt-2 text-xs text-slate-500">Customer-visible archive on the node&apos;s backup storage.</p>
        </Card>
      </div>

      <Card title="Archives" sub="Restore REPLACES the live disk. Typed hostname + reason required; runs as BACKUP_RESTORE.">
        {list.error ? (
          <Unavailable>{list.error}</Unavailable>
        ) : !list.backups || list.backups.length === 0 ? (
          <Empty>No archives for this VM.</Empty>
        ) : (
          <div className="overflow-x-auto">
            <table className="table-shell">
              <thead>
                <tr>
                  <th>Archive</th>
                  <th>Taken</th>
                  <th>Size</th>
                  <th className="text-right">Actions</th>
                </tr>
              </thead>
              <tbody>
                {list.backups.map((b) => (
                  <tr key={b.volid}>
                    <td className="max-w-md truncate font-mono text-xs" title={b.volid}>{b.volid.split("/").pop()}</td>
                    <td className="text-xs text-slate-400">{b.ctime ? fmtDateTime(new Date(b.ctime * 1000)) : "—"}</td>
                    <td className="text-xs">{b.size ? fmtBytes(b.size) : "—"}</td>
                    <td className="text-right">
                      <RestoreBackupControl serverId={server.id} hostname={server.hostname} volid={b.volid} disabled={busy} />
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </Card>

      <Card title="Backup jobs">
        {jobs.length === 0 ? (
          <Empty>No backup or restore jobs yet.</Empty>
        ) : (
          <ul className="space-y-1.5 text-sm">
            {jobs.map((j) => (
              <li key={j.id} className="flex flex-wrap items-center justify-between gap-2">
                <span className="flex items-center gap-2">
                  <Badge tone={j.type === "BACKUP_RESTORE" ? "amber" : "brand"}>{j.type === "BACKUP_RESTORE" ? "restore" : "backup"}</Badge>
                  <StatusDot status={j.status} />
                  {j.status === "RUNNING" && <span className="text-xs text-slate-400">{j.progress}% {j.step ?? ""}</span>}
                </span>
                <span className="text-xs text-slate-500">{timeAgo(j.createdAt)}</span>
                {j.error && <span className="w-full text-xs text-red-400">{j.error.slice(0, 300)}</span>}
              </li>
            ))}
          </ul>
        )}
      </Card>
    </div>
  );
}

