model ServerMod {
  id          String   @id @default(cuid())
  serverId    String
  server      Server   @relation(fields: [serverId], references: [id], onDelete: Cascade)
  modId       String
  mod         GameMod  @relation(fields: [modId], references: [id])
  status      String   @default("INSTALLING") // INSTALLING | INSTALLED | FAILED | REMOVING | REMOVED
  version     String?
  error       String? // last failure detail, surfaced in the portal
  installedAt DateTime @default(now())
  updatedAt   DateTime @updatedAt

  @@unique([serverId, modId])
  @@index([serverId])
}
model GameSchedule {
  id              String    @id @default(cuid())
  serverId        String
  server          Server    @relation(fields: [serverId], references: [id], onDelete: Cascade)
  // "restart" = power-cycle the server; "command" = send an RCON command.
  kind            String    @default("restart")
  // RCON command to run (only for kind="command", e.g. "save-all").
  command         String?
  hour            Int // 0..23 (UTC) — used for daily (non-interval) schedules
  minute          Int // 0..59
  // If set, run every N minutes instead of daily at hour:minute.
  intervalMinutes Int?
  return v === true ? "yes" : v === false ? "no" : "—";
}

/**
 * Admin view of the GAME inside a game server (lib/game-runtime.ts): the
 * cached probe, the recorded run intent, the fleet-sweep down/alert state, the
 * post-provision readiness checklist, and the auto-update/auto-restart
 * overrides. Rendered on /admin/servers/[id] for game servers only.
 */
export function GameRuntimeCard({
  serverId,
  vmStatus,
  family,
  variant,
  gameConfig,
  autoUpdate,
  busy,
  row,
}: {
  serverId: string;
  vmStatus: string;
  family: string;
  variant: string | null;
  gameConfig: Record<string, unknown> | null;
  autoUpdate: boolean;
  busy: boolean;
  row: Row | null;
}) {
  const view = runtimeView({ vmStatus, row, now: new Date(), legacyServiceState: gameConfig?._serviceState });
  const plan = autoUpdatePlan({ family, variant, config: gameConfig, curated: curatedVersionsFor(family) });
  const checks = Array.isArray(row?.readiness) ? (row!.readiness as { id: string; label: string; status: keyof typeof CHECK_TONE; detail: string }[]) : [];

