input.content:
import { db } from "@/lib/db";
import { Badge, StatusDot, timeAgo } from "@/components/ui/primitives";
import { GameRuntimeCard } from "@/components/admin/GameRuntimeCard";
import { GAME_DISPLAY, type GameFamily } from "@/lib/games";
import { Card, Empty, Field, Fields, DeepLink, fmtDateTime } from "../ui";
import { type ServerCore, gameFamilyOf } from "../core";

/** Customer-panel tabs an admin may open for this server (it allows ADMIN without impersonating). */
const PANEL_LINKS: [string, string][] = [
  ["settings", "Game settings"],
  ["mods", "Mods / plugins"],
  ["players", "Players, ops, whitelist & bans"],
  ["console", "Live console"],
  ["backups", "Worlds & game backups"],
  ["schedules", "Schedules"],
];

export async function GameTab({ server }: { server: ServerCore }) {
  const family = gameFamilyOf(server);
  const [online, recent, mods, schedules, playerCount] = await Promise.all([
    db.playerSession.findMany({ where: { serverId: server.id, leftAt: null }, orderBy: { joinedAt: "desc" }, take: 50, select: { id: true, playerName: true, joinedAt: true } }),
    db.playerSession.findMany({ where: { serverId: server.id }, orderBy: { joinedAt: "desc" }, take: 20, select: { id: true, playerName: true, joinedAt: true, leftAt: true, leftAtInferred: true } }),
    db.serverMod.findMany({ where: { serverId: server.id, status: { not: "REMOVED" } }, orderBy: { installedAt: "desc" }, take: 50, select: { id: true, status: true, version: true, error: true, mod: { select: { name: true } } } }),
    db.gameSchedule.findMany({ where: { serverId: server.id }, select: { id: true, kind: true, command: true, hour: true, minute: true, intervalMinutes: true } }),
    db.playerSession.groupBy({ by: ["playerName"], where: { serverId: server.id } }).then((g) => g.length),
  ]);
  const cfg = (server.gameConfig as Record<string, unknown> | null) ?? null;
  const cfgEntries = cfg ? Object.entries(cfg).filter(([k]) => !k.startsWith("_") && !/pass|secret|token|rcon/i.test(k)) : [];

  return (
    <div className="space-y-4">
      <GameRuntimeCard
        serverId={server.id}
        vmStatus={server.status}
        family={family}
        variant={server.gameVariant}
        gameConfig={cfg}
        autoUpdate={server.autoUpdate}
        busy={!!server.jobs[0]}
        row={server.gameRuntime}
      />

      <Card title="Manage" sub="The full game panel, opened as yourself (admin view — not impersonation, nothing is billed to you).">
        <div className="flex flex-wrap gap-x-6 gap-y-2">
          {PANEL_LINKS.map(([tab, label]) => (
            <DeepLink key={tab} href={`/dashboard/servers/${server.id}?tab=${tab}`}>
              {label}
            </DeepLink>
          ))}
        </div>
      </Card>

      <div className="grid gap-4 xl:grid-cols-2">
        <Card title={`Players online (${online.length})`} sub={`${playerCount} distinct player${playerCount === 1 ? "" : "s"} seen on this server (from the game log).`}>
          {online.length === 0 ? (
            <Empty>Nobody is online according to the log tracker.</Empty>
          ) : (
            <ul className="flex flex-wrap gap-2">
              {online.map((p) => (
                <li key={p.id}>
                  <Badge tone="green">{p.playerName}</Badge> <span className="text-[11px] text-slate-500">{timeAgo(p.joinedAt)}</span>
                </li>
              ))}
            </ul>
          )}
          {recent.length > 0 && (
            <details className="mt-3">
              <summary className="cursor-pointer text-xs text-slate-400">Recent sessions</summary>
              <ul className="mt-2 space-y-1 text-xs">
                {recent.map((p) => (
                  <li key={p.id} className="flex justify-between gap-2">
                    <span>{p.playerName}</span>
                    <span className="text-slate-500">
                      {fmtDateTime(p.joinedAt)} → {p.leftAt ? `${fmtDateTime(p.leftAt)}${p.leftAtInferred ? " (inferred)" : ""}` : "now"}
                    </span>
                  </li>
                ))}
              </ul>
            </details>
          )}
        </Card>

        <Card title={`Mods (${mods.length})`}>
          {mods.length === 0 ? (
            <Empty>No mods installed through the panel.</Empty>
          ) : (
            <ul className="space-y-1 text-sm">
              {mods.map((m) => (
                <li key={m.id} className="flex flex-wrap items-center justify-between gap-2">
                  <span>
