            <Empty>Nobody is online according to the log tracker.</Empty>
          ) : (
            <ul className="flex flex-wrap gap-2">
              {online.map((p) => (
                <li key={p.id}>
                  <Badge tone="green">{p.playerName}</Badge> <span className="text-[11px] text-slate-500">{timeAgo(p.joinedAt)}</span>
                </li>
              ))}
            </ul>
          )}
          {recent.length > 0 && (
            <details className="mt-3">
              <summary className="cursor-pointer text-xs text-slate-400">Recent sessions</summary>
              <ul className="mt-2 space-y-1 text-xs">
                {recent.map((p) => (
                  <li key={p.id} className="flex justify-between gap-2">
                    <span>{p.playerName}</span>
                    <span className="text-slate-500">
                      {fmtDateTime(p.joinedAt)} → {p.leftAt ? `${fmtDateTime(p.leftAt)}${p.leftAtInferred ? " (inferred)" : ""}` : "now"}
                    </span>
                  </li>
                ))}
              </ul>
            </details>
          )}
        </Card>

        <Card title={`Mods (${mods.length})`}>
          {mods.length === 0 ? (
            <Empty>No mods installed through the panel.</Empty>
          ) : (
            <ul className="space-y-1 text-sm">
              {mods.map((m) => (
                <li key={m.id} className="flex flex-wrap items-center justify-between gap-2">
                  <span>
                    {m.mod.name} {m.version && <span className="text-xs text-slate-500">{m.version}</span>}
                  </span>
                  <StatusDot status={m.status} />
                  {m.error && <span className="w-full text-xs text-red-400">{m.error.slice(0, 200)}</span>}
                </li>
              ))}
            </ul>
          )}
        </Card>
      </div>

      <div className="grid gap-4 xl:grid-cols-2">
        <Card title="Configuration" sub={`${GAME_DISPLAY[family as GameFamily]?.name ?? family}${server.gameVariant ? ` · ${server.gameVariant}` : ""} — secrets hidden.`}>
          {cfgEntries.length === 0 ? (
            <Empty>No saved settings (game defaults).</Empty>
          ) : (
            <Fields cols={2}>
              {cfgEntries.slice(0, 24).map(([k, v]) => (
                <Field key={k} label={k} mono>
                  <span className="text-xs">{typeof v === "object" ? JSON.stringify(v) : String(v)}</span>
                </Field>
              ))}
            </Fields>
          )}
        </Card>
        <Card title={`Schedules (${schedules.length})`}>
          {schedules.length === 0 ? (
            <Empty>No scheduled restarts or commands.</Empty>
          ) : (
            <ul className="space-y-1 text-sm">
              {schedules.map((s) => (
                <li key={s.id}>
                  {s.kind === "command" ? <code className="font-mono text-xs">{s.command}</code> : "restart"}{" "}
                  <span className="text-xs text-slate-500">
                    {s.intervalMinutes ? `every ${s.intervalMinutes} min` : `daily ${String(s.hour).padStart(2, "0")}:${String(s.minute).padStart(2, "0")} UTC`}
                  </span>
                </li>
              ))}
            </ul>
          )}
        </Card>
      </div>
    </div>
  );
}

