export type ListedVm = {
  vmid: number;
  status: string;
  template?: boolean;
  /** Config `memory` (MB). */
  memoryMB: number;
  /** Config `balloon` (MB, current), null when unset. */
  balloonMB: number | null;
};

export type NodeRamSnapshot = {
  /** Physical RAM (MB), from /nodes/<n>/status memory.total. */
  totalMB: number;
  /** Real used (MB), memory.used (MemTotal - MemAvailable; includes ZFS ARC). */
  usedMB: number;
  /** Sum of guaranteed RAM of every RUNNING non-template VM on the node (all VMs, not only Nxeon customers). */
  guaranteedMB: number;
  /** Sum of `memory` of every running VM (the ceiling they may grow to). */
  ceilingMB: number;
  runningVms: number;
};

/** Reduce a node's VM list to the guard's guaranteed/ceiling totals. */
export function summarizeVms(vms: ListedVm[]): { guaranteedMB: number; ceilingMB: number; runningVms: number } {
  let g = 0;
  let c = 0;
  let r = 0;
  for (const v of vms) {
    if (v.template || v.status !== "running") continue;
    g += guaranteedMB(v.memoryMB, v.balloonMB);
    c += v.memoryMB;
    r += 1;
  }
  return { guaranteedMB: g, ceilingMB: c, runningVms: r };
}

export type RamGuardVerdict = {
  ok: boolean;
  reason: string;
  /** Guaranteed RAM after the new VM, as % of (total - reserve). */
  projectedGuaranteedPct: number;
  /** Real used + new VM, as % of total. */
  projectedRealPct: number;
};

/**
 * Can a node take one more VM that pins `newVmMB`? Two independent checks,
 * both must pass:
 *  1. guaranteed + new <= (total - hostReserve) * maxGuaranteedRatio.
 *     Every pinned VM can always claim its full RAM; this keeps the sum of
 *     those claims below what the host can physically hand out after its own
 *     reserve (ZFS ARC cap + host). This is what makes pinning safe.
 *  2. used + new <= total * maxRealRatio. What is really in use right now
 *     (ARC included) must leave room; node-4 at 89% fails this for any VM.
 * The DB-committed check in scheduleNode (sum of plan RAM of every
 * non-deleting server vs Node.capacityRamMB, < CRITICAL) still runs too: it
 * covers STOPPED customer VMs, which this live view cannot see as claims.
 */
export function ramGuardVerdict(snap: NodeRamSnapshot, newVmMB: number, cfg: RamGuardConfig): RamGuardVerdict {
  const budget = Math.max(0, snap.totalMB - cfg.hostReserveMB);
  const projG = snap.guaranteedMB + newVmMB;
  const projR = snap.usedMB + newVmMB;
  const gPct = budget > 0 ? (projG / budget) * 100 : Infinity;
  const rPct = snap.totalMB > 0 ? (projR / snap.totalMB) * 100 : Infinity;
  const gLimit = budget * cfg.maxGuaranteedRatio;
  const rLimit = snap.totalMB * cfg.maxRealRatio;
  const problems: string[] = [];
  if (!(snap.totalMB > 0)) problems.push("node reported no RAM total");
  else {
    if (projG > gLimit) {
      problems.push(
        `guaranteed VM RAM would be ${Math.round(projG)} MB > ${Math.round(gLimit)} MB ` +
          `(${Math.round(cfg.maxGuaranteedRatio * 100)}% of ${snap.totalMB} MB minus ${cfg.hostReserveMB} MB host reserve)`,
      );
    }
    if (projR > rLimit) {
      problems.push(
        `real used would be ${Math.round(projR)} MB > ${Math.round(rLimit)} MB (${Math.round(cfg.maxRealRatio * 100)}% of ${snap.totalMB} MB)`,
      );
    }
  }
  return {
    ok: problems.length === 0,
    reason: problems.length ? problems.join("; ") : "ok",
    projectedGuaranteedPct: gPct,
    projectedRealPct: rPct,
  };
}

/** Headroom (MB) a node has for more pinned RAM under both checks (may be negative). */
export function pinnedHeadroomMB(snap: NodeRamSnapshot, cfg: RamGuardConfig): number {
export const SNAPSHOT_TTL_MS = 60_000;
const READ_TIMEOUT_MS = 8_000;

type NodeLike = { id: string; name: string; apiUrl: string; pveNode: string; tokenId: string; tokenSecret: string };

const cache = new Map<string, { at: number; snap: NodeRamSnapshot | null }>();

function timeout<T>(p: Promise<T>, ms: number, what: string): Promise<T> {
  return Promise.race([
    p,
    new Promise<T>((_, rej) => setTimeout(() => rej(new Error(`${what} timed out after ${ms}ms`)), ms)),
  ]);
}

const MB = 1024 * 1024;

/** Read a node's live RAM snapshot (uncached). Throws on any read failure. */
export async function readNodeRamSnapshot(node: NodeLike): Promise<{ snap: NodeRamSnapshot; vms: (ListedVm & { name?: string })[] }> {
  const conn = pveFor({ apiUrl: node.apiUrl, pveNode: node.pveNode, tokenId: node.tokenId, tokenSecret: node.tokenSecret });
  const [status, list] = await Promise.all([
    timeout(conn.get(`/nodes/${node.pveNode}/status`), READ_TIMEOUT_MS, "node status"),
    timeout(conn.get(`/nodes/${node.pveNode}/qemu`), READ_TIMEOUT_MS, "vm list"),
  ]);
  const rows: any[] = Array.isArray(list) ? list : [];
  const vms = await Promise.all(
    rows.map(async (r) => {
      const vmid = Number(r?.vmid);
      const template = String(r?.template ?? "") === "1";
      const status = String(r?.status ?? "");
      const listedMB = Math.round(Number(r?.maxmem ?? 0) / MB);
      if (template || status !== "running") {
        return { vmid, status, template, memoryMB: listedMB, balloonMB: null, name: r?.name } as ListedVm & { name?: string };
      }
      // current=1: the values the RUNNING VM has, not a pending change.
      const cfg = await timeout(
        conn.get(`/nodes/${node.pveNode}/qemu/${vmid}/config`, { current: 1 }),
        READ_TIMEOUT_MS,
        `config ${vmid}`,
      );
      const memoryMB = Number(cfg?.memory ?? listedMB) || listedMB;
      const b = cfg?.balloon;
      const balloonMB = b === undefined || b === null || b === "" ? null : Number(b);
      return { vmid, status, template, memoryMB, balloonMB, name: r?.name } as ListedVm & { name?: string };
    }),
  );
  const totals = summarizeVms(vms);
  const snap: NodeRamSnapshot = {
    totalMB: Math.round(Number(status?.memory?.total ?? 0) / MB),
    usedMB: Math.round(Number(status?.memory?.used ?? 0) / MB),
    ...totals,
  };
  return { snap, vms };
}

/** Cached snapshot, or null when the node could not be read. */
export async function nodeRamSnapshot(node: NodeLike, now = Date.now()): Promise<NodeRamSnapshot | null> {
  const hit = cache.get(node.id);
  if (hit && now - hit.at < SNAPSHOT_TTL_MS) return hit.snap;
  let snap: NodeRamSnapshot | null = null;
  try {
    snap = (await readNodeRamSnapshot(node)).snap;
  } catch (e) {
    console.error(`[node-ram-guard] could not read RAM snapshot for ${node.name}:`, e instanceof Error ? e.message : e);
  }
  cache.set(node.id, { at: now, snap });
  return snap;
}

export type NodeGuardResult = RamGuardVerdict & { unknown: boolean };

/** Guard verdict for placing a VM of `newVmMB` on `node`. */
export async function nodeRamGuard(node: NodeLike, newVmMB: number): Promise<NodeGuardResult> {
  const snap = await nodeRamSnapshot(node);
  if (!snap) {
    return { ok: false, unknown: true, reason: "live RAM snapshot unavailable", projectedGuaranteedPct: NaN, projectedRealPct: NaN };
  }
  return { ...ramGuardVerdict(snap, newVmMB, ramGuardConfig()), unknown: false };
}

