import { db } from "@/lib/db";
import { Badge } from "@/components/ui/primitives";
import { REGION_LABELS } from "@/lib/node-regions";
import { nodeRamSnapshot } from "@/lib/node-ram-guard";
import { ramGuardVerdict, ramGuardConfig, ramGuardMode } from "@/lib/vm-memory-policy";
import { evaluateMoveTargets, type TargetNodeInput } from "@/lib/admin-server/move-targets";
import { bridgeListVmMoves, vmMoveUiState } from "@/lib/admin-server/vm-move-bridge";
import { withTimeout } from "@/lib/admin-server/live";
import { Card, Field, Fields, Unavailable } from "../ui";
import { MoveConsole, MoveHistory } from "../MoveConsole";
import { type ServerCore, planRamMB, publicEndpoint } from "../core";
import { baseDiskGBFor, effectiveDiskGB } from "@/lib/extra-disk";

export async function MoveTab({ server }: { server: ServerCore }) {
  const nodes = await db.node.findMany({ orderBy: { createdAt: "asc" } });
  const primary = nodes.find((n) => n.isPrimary) ?? null;
  const sourceNode = server.node ?? primary;
  const ram = planRamMB(server);

  // Σ plan RAM per node (non-DELETING) — the "committed" number the engine checks.
  const live = await db.server.findMany({
    where: { status: { not: "DELETING" } },
    select: { nodeId: true, plan: { select: { ramMB: true } }, gamePlan: { select: { ramMB: true } } },
  });
  const committed = new Map<string, number>();
  for (const s of live) {
    const nid = s.nodeId ?? primary?.id;
    if (!nid) continue;
    committed.set(nid, (committed.get(nid) ?? 0) + (s.gamePlan?.ramMB ?? s.plan.ramMB));
  }

  const cfg = ramGuardConfig();
  const inputs: TargetNodeInput[] = await Promise.all(
    nodes.map(async (n) => {
      const snap = n.id === sourceNode?.id ? null : await withTimeout(nodeRamSnapshot(n), 9000).catch(() => null);
      const guard = snap ? ramGuardVerdict(snap, ram, cfg) : null;
      return {
        id: n.id,
        name: n.name,
        region: n.region,
        provider: n.provider,
        enabled: n.enabled,
        status: n.status,
        acceptsProvisions: n.acceptsProvisions,
        capacityRamMB: n.capacityRamMB,
        committedRamMB: committed.get(n.id) ?? 0,
        realTotalRamMB: snap?.totalMB ?? null,
        realUsedRamMB: snap?.usedMB ?? null,
        guard: guard ? { ok: guard.ok, reason: guard.ok ? null : guard.reason, projectedGuaranteedPct: guard.projectedGuaranteedPct, projectedRealPct: guard.projectedRealPct } : null,
      };
    }),
  );
  const evals = evaluateMoveTargets(
    {
      nodeId: sourceNode?.id ?? null,
      region: sourceNode?.region ?? null,
      provider: sourceNode?.provider ?? null,
      planRamMB: ram,
      hasDedicatedIp: !!server.dedicatedIp,
      publicIp: publicEndpoint(server),
    },
    inputs,
    { guardMode: ramGuardMode(), targetPublicIp: (id) => nodes.find((n) => n.id === id)?.publicIp ?? null },
  );
  const state = vmMoveUiState();
  const history = await bridgeListVmMoves(server.id);
  const volumes = server._count.volumes;
  const blockersHere: string[] = [];
  if (!server.vmid) blockersHere.push("The server has no VM yet.");
  if (volumes > 0) blockersHere.push(`${volumes} block-storage volume(s) are assigned — the engine refuses servers with volumes.`);
  if (server.jobs[0]) blockersHere.push("A job is in flight for this server.");
  if (!["RUNNING", "STOPPED"].includes(server.status)) blockersHere.push(`Status is ${server.status.toLowerCase()} — only running or stopped servers move.`);

  return (
    <div className="space-y-4">
      {!state.engine && (
        <Unavailable>
          The VM move engine is not part of this build (it ships on branch feature/vm-node-migration). Target capacity below is real and live; the dry run and the
          run / rollback / cleanup buttons switch on as soon as the engine is merged.
        </Unavailable>
      )}
      {state.engine && !state.canRun && <Unavailable>{state.reason}</Unavailable>}

      <Card title="What moves" sub="The move carries the VM's disk and config to another node; it never destroys anything on the source.">
        <Fields cols={4}>
          <Field label="From">{sourceNode ? `${sourceNode.name} · ${REGION_LABELS[sourceNode.region] ?? sourceNode.region}` : "—"}</Field>
          <Field label="VM">{server.vmid ? `VMID ${server.vmid}` : "—"} · {(ram / 1024).toFixed(1)} GB RAM · {effectiveDiskGB(baseDiskGBFor(server), server.extraDiskGB)} GB disk</Field>
          <Field label="Addressing">{server.dedicatedIp ? `dedicated ${server.dedicatedIp.address} (moves with the VM, same region only)` : `NAT via ${publicEndpoint(server) ?? "—"}`}</Field>
          <Field label="Customer impact">{server.dedicatedIp ? "same IP; short downtime" : "new public IP, same port numbers; short downtime; customer is notified"}</Field>
        </Fields>
        {blockersHere.length > 0 && (
          <ul className="mt-3 space-y-1 text-xs text-amber-300">
            {blockersHere.map((b) => (
              <li key={b}>⚠ {b}</li>
            ))}
          </ul>
        )}
      </Card>

      <Card
        title="Safety guarantees (enforced by the engine)"
        sub="Stated here so nobody has to remember them."
      >
        <ul className="grid gap-2 text-sm sm:grid-cols-2">
          <li>✔ <b>Never destroys the source.</b> After the cut-over the source VM is kept <b>stopped</b> (onboot off) for 7 days; only a separate Cleanup removes it.</li>
          <li>✔ <b>Automatic rollback before commit.</b> Any failure in the downtime window puts the source back (IP, VM, DB status) automatically.</li>
          <li>✔ <b>Disk is copied while the server keeps running</b>; only the final incremental copy happens with it stopped.</li>
          <li>✔ <b>Dedicated IPs move only within the same campus</b> — the upstream move list is checked during the dry run.</li>
          <li>✔ <b>Capacity is checked against real node RAM</b> (4 GB reserve) and committed RAM, plus pool space.</li>
          <li>✔ <b>Snapshots are not carried over</b> — the run asks you to accept that explicitly.</li>
        </ul>
      </Card>

      <Card title="Target nodes" sub={`Live RAM from each node (cached 60 s). RAM guard mode: ${ramGuardMode()}.`}>
        <div className="overflow-x-auto">
          <table className="table-shell">
            <thead>
              <tr>
                <th>Node</th>
                <th>Region</th>
                <th>Committed RAM now → after</th>
                <th>Real RAM after</th>
                <th>Verdict</th>
              </tr>
            </thead>
            <tbody>
              {evals.map((e) => (
                <tr key={e.nodeId}>
                  <td className="font-medium">{e.name}</td>
                  <td className="text-xs">{REGION_LABELS[e.region] ?? e.region}</td>
                  <td className="font-mono text-xs">
                    {e.committedPctNow}% → <span className={e.committedPctAfter >= 100 ? "text-red-400" : e.committedPctAfter >= 90 ? "text-amber-300" : ""}>{e.committedPctAfter}%</span>
                  </td>
                  <td className="font-mono text-xs">
                    {e.realFreeAfterMB == null ? <span className="text-slate-500">unknown</span> : `${e.realPctAfter}% used · ${(Math.max(0, e.realFreeAfterMB) / 1024).toFixed(1)} GB free`}
                  </td>
                  <td className="max-w-md text-xs">
                    {e.eligible ? <Badge tone="green">eligible</Badge> : <Badge tone="red">blocked</Badge>}
                    {[...e.blockers, ...e.warnings].length > 0 && (
                      <ul className="mt-1 space-y-0.5">
                        {e.blockers.map((b) => (
                          <li key={b} className="text-red-300">✖ {b}</li>
                        ))}
                        {e.warnings.map((w) => (
                          <li key={w} className="text-amber-300">⚠ {w}</li>
                        ))}
                      </ul>
                    )}
                    <p className="mt-1 text-slate-500">{e.addressChange}</p>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </Card>

      <MoveConsole
        serverId={server.id}
        hostname={server.hostname}
        targets={evals.map((e) => ({ id: e.nodeId, name: e.name, eligible: e.eligible }))}
        canPreview={state.canPreview && blockersHere.length === 0}
        canRun={state.canRun && blockersHere.length === 0}
        disabledReason={state.reason ?? blockersHere[0] ?? null}
      />

      <MoveHistory serverId={server.id} hostname={server.hostname} moves={history} nodeNames={Object.fromEntries(nodes.map((n) => [n.id, n.name]))} />
    </div>
  );
}

