  hostname: string;
  targets: { id: string; name: string; eligible: boolean }[];
  canPreview: boolean;
  canRun: boolean;
  disabledReason: string | null;
}) {
  const [target, setTarget] = useState(targets.find((t) => t.eligible)?.id ?? "");
  const [dropSnaps, setDropSnaps] = useState(false);
  const [plan, setPlan] = useState<MovePlan | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const selected = targets.find((t) => t.id === target);

  return (
    <section className="card" aria-labelledby="move-run">
      <h2 id="move-run" className="mb-1 font-semibold">Plan & run a move</h2>
      <p className="mb-3 text-xs text-slate-400">1 · pick a target · 2 · dry run (touches nothing, shows the full plan + downtime) · 3 · run with a reason and the hostname typed back.</p>
      <div className="flex flex-wrap items-end gap-3">
        <label>
          <span className="mb-1 block text-xs text-slate-400">Target node</span>
          <select className="input py-1.5 text-sm" value={target} onChange={(e) => { setTarget(e.target.value); setPlan(null); }}>
            <option value="">Choose…</option>
            {targets.map((t) => (
              <option key={t.id} value={t.id}>
                {t.name}{t.eligible ? "" : " (blocked)"}
              </option>
            ))}
          </select>
        </label>
        <label className="flex items-center gap-2 pb-2 text-sm">
          <input type="checkbox" checked={dropSnaps} onChange={(e) => { setDropSnaps(e.target.checked); setPlan(null); }} />
          Accept that snapshots are not carried over
        </label>
        <button
          type="button"
          className="btn-secondary py-1.5 text-sm"
          disabled={!canPreview || !target || pending}
          title={!canPreview ? disabledReason ?? undefined : undefined}
          onClick={() =>
            start(async () => {
              setErr(null);
              setPlan(null);
              const r = await adminPreviewMove(serverId, target, dropSnaps);
              if (r.ok) setPlan(r.plan);
              else setErr(r.error);
            })
          }
        >
          {pending ? "Planning…" : "Dry run"}
        </button>
      </div>
      {!canPreview && disabledReason && <p className="mt-2 text-xs text-slate-500">{disabledReason}</p>}
      {err && <p role="alert" className="mt-3 text-xs text-red-400">{err}</p>}
      {plan && (
        <div className="mt-4 space-y-3">
          <PlanView plan={plan} />
          <ActionPanel
            label={`Run move to ${selected?.name ?? "target"}…`}
            title={`Move ${hostname} to ${selected?.name ?? "target"}`}
            tone="danger"
            confirmText={hostname}
            confirmHint="Type the hostname"
            disabled={!canRun || !plan.ok || !dropSnaps}
            disabledReason={!canRun ? disabledReason ?? "Moves are not enabled" : !plan.ok ? "Blocking preflight checks failed" : "Accept that snapshots are not carried over"}
            description={`Downtime ${fmtDuration(plan.estimatedDowntimeSec)}. The source is kept stopped for 7 days; rollback is automatic until commit.`}
            successText="Move queued — follow it in the history below."
            run={(reason, typed, idem) => adminRunMove(serverId, target, { reason, typedHostname: typed, allowDropSnapshots: dropSnaps, dryRun: false, idem })}
          />
        </div>
      )}
    </section>
  );
}

export function MoveHistory({ serverId, hostname, moves, nodeNames }: { serverId: string; hostname: string; moves: VmMoveView[]; nodeNames: Record<string, string> }) {
  return (
    <section className="card" aria-labelledby="move-history">
      <h2 id="move-history" className="mb-3 font-semibold">Move history</h2>
      {moves.length === 0 ? (
        <p className="text-sm text-slate-500">This server has never been moved.</p>
      ) : (
        <ul className="space-y-3">
          {moves.map((m) => {
            const b = moveButtons(m);
            const idx = MOVE_PHASES.indexOf(m.phase as MovePhase);
            return (
              <li key={m.id} className="rounded-lg border border-white/[0.06] p-3 text-sm">
                <div className="flex flex-wrap items-center justify-between gap-2">
                  <span>
                    {nodeNames[m.sourceNodeId] ?? m.sourceNodeId} → {nodeNames[m.targetNodeId] ?? m.targetNodeId}
                    {m.dryRun && <span className="ml-2 text-xs text-slate-500">(dry run)</span>}
                  </span>
                  <span className="adm-pill" data-tone={m.status === "DONE" || m.status === "CLEANED" ? "green" : m.status === "FAILED" ? "red" : m.status === "RUNNING" ? "blue" : "amber"}>
                    {m.status.toLowerCase()} · {PHASE_LABELS[m.phase as MovePhase] ?? m.phase}
                  </span>
                </div>
                {idx >= 0 && (
                  <div className="mt-2 h-1.5 w-full overflow-hidden rounded-full bg-white/[0.06]" role="progressbar" aria-valuemin={0} aria-valuemax={MOVE_PHASES.length - 1} aria-valuenow={idx}>
                    <div className="h-full rounded-full bg-gradient-to-r from-[#3b6be8] to-[#7b3fef]" style={{ width: `${Math.round((idx / (MOVE_PHASES.length - 1)) * 100)}%` }} />
                  </div>
                )}
                <p className="mt-1 text-xs text-slate-500">
                  {new Date(m.createdAt).toISOString().slice(0, 16).replace("T", " ")} UTC{m.reason ? ` — ${m.reason}` : ""}
                  {m.keepSourceUntil ? ` · source kept until ${m.keepSourceUntil.slice(0, 10)}` : ""}
                  {m.sourceCleanedAt ? ` · source cleaned ${m.sourceCleanedAt.slice(0, 10)}` : ""}
                </p>
                {m.error && <p className="mt-1 text-xs text-red-400">{m.error}</p>}
                {m.log.length > 0 && (
                  <details className="mt-2">
                    <summary className="cursor-pointer text-xs text-slate-400">Log ({m.log.length})</summary>
                    <pre className="mt-1 max-h-60 overflow-auto whitespace-pre-wrap rounded bg-black/30 p-2 font-mono text-[11px] text-slate-400">
                      {m.log.map((l) => `${l.at.slice(11, 19)} [${l.phase}] ${l.msg}`).join("\n")}
                    </pre>
                  </details>
                )}
                <div className="mt-2 flex flex-wrap gap-2">
                  {b.canRollback && (
                    <ActionPanel
                      label="Roll back…"
                      tone="danger"
                      small
                      confirmText={hostname}
                      confirmHint="Type the hostname"
                      description="Only possible before commit: puts the IP, VM and status back on the source."
                      run={(reason, typed) => adminRollbackMove(serverId, m.id, reason, typed)}
                    />
                  )}
                  {b.canCleanup && (
                    <ActionPanel
                      label={b.cleanupNeedsForce ? "Clean up source early…" : "Clean up source…"}
                      tone="danger"
                      small
                      confirmText={hostname}
                      confirmHint="Type the hostname"
                      description={b.cleanupNeedsForce ? "The 7-day keep window has not passed — this destroys the stopped source VM early. The engine re-verifies the target first." : "Destroys the stopped source VM (the engine re-verifies the target is live first)."}
                      run={(reason, typed) => adminCleanupMove(serverId, m.id, reason, typed, b.cleanupNeedsForce)}
                    />
                  )}
                </div>
              </li>
            );
          })}
        </ul>
      )}
    </section>
  );
}

