 * self-serve cancellation refunds the unused term (actions-server-lifecycle.ts).
 */
export async function latestServerTermInvoiceId(server: {
  userId: string;
  hostname: string;
  previousHostnames: string[];
  createdAt: Date;
}): Promise<string | null> {
  const names = [server.hostname, ...(server.previousHostnames ?? [])].filter((h) => !!h);
  if (names.length === 0) return null;
  const inv = await db.invoice.findFirst({
    where: {
      userId: server.userId,
      status: { in: ["PAID", "REFUNDED"] },
      createdAt: { gte: new Date(server.createdAt.getTime() - 60_000) },
      OR: names.map((h) => ({ description: { contains: `(${h})` } })),
    },
    orderBy: { createdAt: "desc" },
    select: { id: true },
  });
  return inv?.id ?? null;
}
