import Link from "next/link";
import { db } from "@/lib/db";
import { Badge, fmtMoney, timeAgo } from "@/components/ui/primitives";
import { monthlyCents } from "@/lib/admin-metrics";
import { extraDiskMonthlyCents, extraDiskPerGbCents } from "@/lib/disk-expand";
import { backupPlusMonthlyCents } from "@/lib/backup-upgrade";
import { dedicatedIpMonthlyCents } from "@/lib/dedicated-ip";
import { taxContextForUser } from "@/lib/tax";
import { renewalQuote } from "@/lib/renewal-quote";
import { walletSplit } from "@/lib/wallet-split";
import { hasChargeableCard, cardDisplayLabel } from "@/lib/stripe-cards";
import { annualDiscountPct } from "@/lib/annual-discount";
import { resolveServerLifetimeSpendCents, latestServerTermInvoiceId } from "@/lib/server-spend";
import { ExtendForm, FreeToggle, GrandfatheredPriceForm, AdminRenewNowButton } from "@/components/SubscriptionControls";
import { ExtendGraceForm, SendReaddEmailButton } from "@/components/admin/CardHealthControls";
import { RefundControls } from "@/components/admin/RefundControls";
import { ServerOpsPanel } from "@/components/admin/ops/ServerOpsPanel";
import { Card, Empty, Field, Fields, fmtDate } from "../ui";
import type { ServerCore } from "../core";

export async function BillingTab({ server }: { server: ServerCore }) {
  const owner = await db.user.findUnique({
    where: { id: server.userId },
    select: {
      id: true, email: true, balanceCents: true, stripeCustomerId: true, stripePaymentMethodId: true,
      cardBrand: true, cardLast4: true, cardExpMonth: true, cardExpYear: true, billingCountry: true, vatId: true,
      paymentCards: { orderBy: { createdAt: "desc" }, select: { id: true, brand: true, last4: true, expMonth: true, expYear: true, isPrimary: true, unusableAt: true, unusableReason: true, createdAt: true } },
    },
  });
  if (!owner) return <Empty>Owner not found.</Empty>;

  const livePlanMonthlyCents = server.gamePlan ? monthlyCents(server.gamePlan.priceCents, server.gamePlan.termMonths) : server.plan.priceCents;
  const effectivePlanMonthlyCents =
    server.grandfatheredRenewalCents != null
      ? server.gamePlan
        ? monthlyCents(server.grandfatheredRenewalCents, server.gamePlan.termMonths)
        : server.grandfatheredRenewalCents
      : livePlanMonthlyCents;

  // Add-ons priced through the same live settings renewalCharge reads.
  const ipBilled = !!server.dedicatedIp && server.wantsDedicatedIp;
  const ipFreePerk = !!server.dedicatedIp && !server.wantsDedicatedIp;
  const [ipPriceCents, backupPlusCents, extraDiskPriceCents] = server.isFree
    ? [0, 0, 0]
    : await Promise.all([
        ipBilled ? dedicatedIpMonthlyCents() : Promise.resolve(0),
        server.backupTier === "PLUS" ? backupPlusMonthlyCents() : Promise.resolve(0),
        server.extraDiskGB > 0 ? extraDiskMonthlyCents(server.extraDiskGB) : Promise.resolve(0),
      ]);
  const addons: { label: string; detail: string; monthlyCents: number }[] = [];
  if (server.dedicatedIp) addons.push({ label: "Dedicated IPv4", detail: ipFreePerk ? `${server.dedicatedIp.address} · free (platform default, not purchased)` : server.dedicatedIp.address, monthlyCents: ipPriceCents });
  if (server.backupTier === "PLUS") addons.push({ label: "Backup Plus", detail: "extended retention", monthlyCents: backupPlusCents });
  if (server.extraDiskGB > 0) addons.push({ label: "Extra disk", detail: `${server.extraDiskGB} GB`, monthlyCents: extraDiskPriceCents });

  // "Renew now" preview — the exact renewalQuote()/walletSplit() the action itself uses.
  let renewPreview: { totalCents: number; walletCents: number; cardCents: number; durationLabel: string; hasCard: boolean; cardLabel: string | null; coversFully: boolean } | null = null;
  if (!server.isFree && server.expiresAt) {
    const taxCtx = await taxContextForUser(owner);
    const quote = renewalQuote(server, {
      ipMonthlyCents: await dedicatedIpMonthlyCents(),
      extraDiskPerGbCents: await extraDiskPerGbCents(),
      backupPlusCents: await backupPlusMonthlyCents(),
      annualDiscountPct: await annualDiscountPct(),
      taxRatePercent: taxCtx.ratePercent,
    });
    const split = walletSplit({ dueCents: quote.totalCents, balanceCents: owner.balanceCents, useWallet: true });
    renewPreview = {
      totalCents: quote.totalCents,
      walletCents: split.walletApplied,
      cardCents: split.cardCents,
      durationLabel: quote.durationLabel,
      hasCard: hasChargeableCard(owner),
      cardLabel: cardDisplayLabel({ brand: owner.cardBrand, last4: owner.cardLast4, expMonth: owner.cardExpMonth, expYear: owner.cardExpYear }),
      coversFully: split.cardCents === 0,
    };
  }

  const [spendMap, termInvoiceId, renewals] = await Promise.all([
    resolveServerLifetimeSpendCents([{ id: server.id, hostname: server.hostname, previousHostnames: server.previousHostnames, userId: server.userId, createdAt: server.createdAt }]),
    latestServerTermInvoiceId(server),
    db.invoice.findMany({
      where: { userId: server.userId, OR: [server.hostname, ...server.previousHostnames].map((h) => ({ description: { contains: `(${h})` } })) },
      orderBy: { createdAt: "desc" },
      take: 10,
      select: { id: true, number: true, description: true, amountCents: true, status: true, refundedCents: true, createdAt: true },
    }),
  ]);
  const lifetime = spendMap.get(server.id) ?? 0;
  const now = Date.now();

  return (
    <div className="space-y-4">
      <div className="grid gap-4 xl:grid-cols-3">
        <Card title="Term" className="xl:col-span-2">
          <Fields cols={3}>
            <Field label="Expires" hint={server.expiresAt && !server.isFree ? `${Math.ceil((server.expiresAt.getTime() - now) / 86_400_000)} days` : undefined}>
              {server.isFree ? "never (free)" : fmtDate(server.expiresAt)}
            </Field>
            <Field label="Term">{server.termMonths} month{server.termMonths === 1 ? "" : "s"}</Field>
            <Field label="Auto-renew">{server.isFree ? "n/a" : server.autoRenew ? "on" : "off"}</Field>
            <Field label="Dunning stage">{server.dunningStage}{server.dunningNextAt ? ` · next ${fmtDate(server.dunningNextAt)}` : ""}</Field>
            <Field label="Billing grace until">{fmtDate(server.billingGraceUntil)}</Field>
            <Field label="Lifetime spend" hint="order + renewals + add-ons, net of refunds">{lifetime > 0 ? fmtMoney(lifetime) : "—"}</Field>
          </Fields>
          <div className="mt-4 flex flex-wrap items-center gap-x-6 gap-y-3 border-t border-white/[0.06] pt-3">
            {!server.isFree && <ExtendForm serverId={server.id} />}
            {renewPreview && <AdminRenewNowButton serverId={server.id} hostname={server.hostname} preview={renewPreview} />}
            <FreeToggle serverId={server.id} isFree={server.isFree} />
          </div>
          <p className="mt-2 text-xs text-slate-500">
            Extend gifts days (a positive extension is treated as free time when the renewal price is prorated); Renew now charges the wallet then the saved card immediately.
          </p>
        </Card>

        <Card title="Renewal price">
          <p className="text-2xl font-semibold">{server.isFree ? "free" : `${fmtMoney(effectivePlanMonthlyCents)}/mo`}</p>
          <p className="mt-1 text-xs text-slate-400">
            {server.isFree
              ? "Free servers never renew."
              : server.grandfatheredRenewalCents != null
                ? `Locked (grandfathered). Live catalog rate is ${fmtMoney(livePlanMonthlyCents)}/mo.`
                : "Live catalog rate — no locked price."}{" "}
            Before add-ons.
          </p>
          {!server.isFree && (
            <div className="mt-3">
              <GrandfatheredPriceForm serverId={server.id} currentCents={server.grandfatheredRenewalCents} />
            </div>
          )}
        </Card>
      </div>

      <div className="grid gap-4 xl:grid-cols-2">
        <Card title="Add-ons">
          {addons.length === 0 ? (
            <Empty>No recurring add-ons on this server.</Empty>
          ) : (
            <ul className="space-y-1.5 text-sm">
              {addons.map((a) => (
                <li key={a.label} className="flex items-center justify-between gap-4">
                  <span>
                    <span className="font-medium">{a.label}</span> <span className="text-xs text-slate-500">{a.detail}</span>
                  </span>
                  <span className={a.monthlyCents === 0 ? "text-xs text-slate-500" : "font-mono text-xs"}>{a.monthlyCents === 0 ? "free" : `+${fmtMoney(a.monthlyCents)}/mo`}</span>
                </li>
              ))}
            </ul>
          )}
        </Card>

        <Card title="Card health" action={<SendReaddEmailButton userId={owner.id} email={owner.email} />}>
          {owner.paymentCards.length === 0 ? (
            <p className="text-sm text-slate-400">
              {hasChargeableCard(owner) ? `Legacy saved card: ${cardDisplayLabel({ brand: owner.cardBrand, last4: owner.cardLast4, expMonth: owner.cardExpMonth, expYear: owner.cardExpYear }) ?? "on file"}` : "No saved card — renewals use the wallet only."}
            </p>
          ) : (
            <ul className="space-y-1.5 text-sm">
              {owner.paymentCards.map((c) => (
                <li key={c.id} className="flex flex-wrap items-center justify-between gap-2">
                  <span>
                    {cardDisplayLabel({ brand: c.brand, last4: c.last4, expMonth: c.expMonth, expYear: c.expYear }) ?? "card"}
                    {c.isPrimary && <span className="ml-2"><Badge tone="brand">primary</Badge></span>}
                  </span>
                  {c.unusableAt ? <Badge tone="red">unusable · {c.unusableReason ?? "declined"}</Badge> : <Badge tone="green">ok</Badge>}
                </li>
              ))}
            </ul>
          )}
          <div className="mt-3 border-t border-white/[0.06] pt-3">
            <p className="mb-1 text-xs text-slate-500">Give the customer more time before dunning acts on this server:</p>
            <ExtendGraceForm serverId={server.id} />
          </div>
        </Card>
      </div>

      <Card title="Invoices for this server" action={<Link href={`/admin/users/${owner.id}?tab=billing`} className="btn-ghost py-1 text-xs">All billing →</Link>}>
        {renewals.length === 0 ? (
          <Empty>No invoices reference this server.</Empty>
        ) : (
          <ul className="space-y-1 text-sm">
            {renewals.map((i) => (
              <li key={i.id} className="flex flex-wrap items-center justify-between gap-2">
                <Link href={`/admin/invoices/${i.id}`} className="font-mono text-xs hover:text-brand-300">#{i.number}</Link>
                <span className="min-w-0 flex-1 truncate text-xs text-slate-400">{i.description}</span>
                <Badge tone={i.status === "PAID" ? "green" : i.status === "OPEN" ? "amber" : i.status === "REFUNDED" ? "brand" : "slate"}>{i.status.toLowerCase()}</Badge>
                <span className="font-mono text-xs">{fmtMoney(i.amountCents)}{i.refundedCents ? ` (−${fmtMoney(i.refundedCents)})` : ""}</span>
                <span className="text-xs text-slate-500">{timeAgo(i.createdAt)}</span>
              </li>
            ))}
          </ul>
        )}
      </Card>

      <div className="grid gap-4 xl:grid-cols-2">
        <Card title="Refund / balance" sub="Refunds bind to the latest term invoice for this server when one is found.">
          <RefundControls userId={owner.id} invoiceId={termInvoiceId ?? undefined} />
        </Card>
        <div>
          <h2 className="mb-2 text-sm font-semibold text-slate-300">Audited customer ops (credit · extend · free · transfer ownership)</h2>
          <ServerOpsPanel serverId={server.id} sections={["customer"]} />
        </div>
      </div>
    </div>
  );
}

