import Link from "next/link";
import { db } from "@/lib/db";
import { StatusDot, timeAgo } from "@/components/ui/primitives";
import { AreaChart } from "@/components/ui/charts";
import { BarChart } from "@/components/ui/bar-chart";
import { actingAdminId, detailWithoutActor } from "@/lib/admin-metrics";
import { Card, Empty, fmtDateTime } from "../ui";
import type { ServerCore } from "../core";

const DAY = 86_400_000;

/** Downsample to at most `n` points by averaging buckets (charts stay cheap). */
function downsample(values: number[], n: number): number[] {
  if (values.length <= n) return values;
  const size = values.length / n;
  const out: number[] = [];
  for (let i = 0; i < n; i++) {
    const slice = values.slice(Math.floor(i * size), Math.floor((i + 1) * size));
    out.push(slice.reduce((a, b) => a + b, 0) / Math.max(1, slice.length));
  }
  return out;
}

export async function ActivityTab({ server }: { server: ServerCore }) {
  const since7 = new Date(Date.now() - 7 * DAY);
  const since30 = new Date(Date.now() - 30 * DAY);
  const [jobs, audits, events, uptime, mem] = await Promise.all([
    db.job.findMany({ where: { serverId: server.id }, orderBy: { createdAt: "desc" }, take: 40 }),
    db.auditLog.findMany({
      where: {
        OR: [
          { target: server.id },
          { detail: { contains: server.id } },
          { detail: { contains: server.hostname } },
        ],
      },
      orderBy: { createdAt: "desc" },
      take: 40,
      select: { id: true, action: true, detail: true, createdAt: true, ip: true, user: { select: { email: true } } },
    }),
    db.telemetryEvent.findMany({ where: { serverId: server.id }, orderBy: { ts: "desc" }, take: 25, select: { id: true, type: true, ts: true, ip: true, user: true, path: true, status: true, label: true } }),
    db.serverUptimeDaily.findMany({ where: { serverId: server.id, date: { gte: since30 } }, orderBy: { date: "asc" } }),
    db.serverMemSample.findMany({ where: { serverId: server.id, ts: { gte: since7 } }, orderBy: { ts: "asc" }, select: { ts: true, usedBytes: true, totalBytes: true } }),
  ]);

  const actorIds = [...new Set(audits.map((a) => actingAdminId(a.detail)).filter(Boolean))] as string[];
  const actors = new Map((actorIds.length ? await db.user.findMany({ where: { id: { in: actorIds } }, select: { id: true, email: true } }) : []).map((u) => [u.id, u.email]));

  const memPct = mem.filter((m) => m.totalBytes > 0n).map((m) => (Number(m.usedBytes) / Number(m.totalBytes)) * 100);
  const memSeries = downsample(memPct, 120);
  const uptimeBars = uptime.map((u) => ({ label: u.date.toISOString().slice(5, 10), value: u.total > 0 ? Math.round((u.up / u.total) * 1000) / 10 : 0, title: `${u.date.toISOString().slice(0, 10)}: ${u.up}/${u.total} checks up` }));
  const upTotal = uptime.reduce((a, u) => a + u.up, 0);
  const allTotal = uptime.reduce((a, u) => a + u.total, 0);

  return (
    <div className="space-y-4">
      <div className="grid gap-4 xl:grid-cols-2">
        <Card title="Uptime (30 days)" sub={allTotal > 0 ? `${((upTotal / allTotal) * 100).toFixed(2)}% of ${allTotal} checks` : "No uptime checks recorded yet."}>
          {uptimeBars.length === 0 ? <Empty>No samples.</Empty> : <BarChart data={uptimeBars} height={160} format={(v) => `${v}%`} ariaLabel="Daily uptime percentage" unit="%" />}
        </Card>
        <Card title="Guest memory used (7 days)" sub={memPct.length ? `${memPct.length} samples · latest ${memPct[memPct.length - 1].toFixed(0)}%` : "No guest-agent samples yet."}>
          {memSeries.length < 2 ? <Empty>Not enough samples.</Empty> : <AreaChart id={`mem-${server.id}`} series={[{ name: "RAM %", data: memSeries, color: "#3b6be8" }]} maxY={100} yLabel={(v) => `${Math.round(v)}%`} height={160} />}
        </Card>
      </div>

      <Card title={`Jobs (${jobs.length})`} sub="Newest first. Payloads and errors expand inline." action={<Link href={`/admin/ops/jobs?server=${server.id}`} className="btn-ghost py-1 text-xs">Queue tools →</Link>}>
        {jobs.length === 0 ? (
          <Empty>No jobs recorded.</Empty>
        ) : (
          <ol className="relative space-y-0 border-l border-white/10 pl-4">
            {jobs.map((j) => {
              const ran = j.startedAt && j.finishedAt ? Math.round((j.finishedAt.getTime() - j.startedAt.getTime()) / 1000) : null;
              return (
                <li key={j.id} className="relative pb-3">
                  <span
                    className={`absolute -left-[21px] top-1.5 h-2.5 w-2.5 rounded-full ${j.status === "FAILED" ? "bg-red-400" : j.status === "DONE" ? "bg-emerald-400" : "bg-sky-400"}`}
                    aria-hidden
                  />
                  <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-sm">
                    <span className="font-medium">{j.type.toLowerCase().replace(/_/g, " ")}</span>
                    <StatusDot status={j.status} />
                    {(j.status === "RUNNING" || j.status === "QUEUED") && j.progress > 0 && <span className="text-xs text-slate-400">{j.progress}%</span>}
                    {j.step && j.status === "RUNNING" && <span className="text-xs text-slate-400">{j.step}</span>}
                    <span className="text-xs text-slate-500" title={j.createdAt.toISOString()}>{timeAgo(j.createdAt)}</span>
                    {j.attempts > 1 && <span className="text-xs text-amber-300">{j.attempts} attempts</span>}
                    {ran != null && <span className="text-xs text-slate-500">ran {ran}s</span>}
                  </div>
                  {j.error && (
                    <details className="mt-1">
                      <summary className="cursor-pointer text-xs text-red-400">error</summary>
                      <pre className="mt-1 whitespace-pre-wrap break-all rounded-lg bg-black/30 p-2 font-mono text-[11px] text-red-300">{j.error}</pre>
                    </details>
                  )}
                  {!j.error && j.payload != null && (
                    <details className="mt-1">
                      <summary className="cursor-pointer text-xs text-slate-500">payload</summary>
                      <pre className="mt-1 whitespace-pre-wrap break-all rounded-lg bg-black/30 p-2 font-mono text-[11px] text-slate-400">{JSON.stringify(j.payload, null, 2)}</pre>
                    </details>
                  )}
                </li>
              );
            })}
          </ol>
        )}
      </Card>

      <div className="grid gap-4 xl:grid-cols-2">
        <Card title="Audit log" sub="Every staff action that names this server.">
          {audits.length === 0 ? (
            <Empty>No audit entries.</Empty>
          ) : (
            <ul className="divide-y divide-white/[0.05] text-sm">
              {audits.map((a) => {
                const as = actingAdminId(a.detail);
                return (
                  <li key={a.id} className="py-2">
                    <div className="flex flex-wrap items-baseline justify-between gap-2">
                      <span className="font-mono text-xs">{a.action}</span>
                      <span className="text-xs text-slate-500">{fmtDateTime(a.createdAt)}</span>
                    </div>
                    <p className="text-xs text-slate-400">
                      {a.user?.email ?? "system"}
                      {as ? ` (as ${actors.get(as) ?? as})` : ""}
                      {a.ip ? ` · ${a.ip}` : ""}
                      {a.detail ? ` — ${as ? detailWithoutActor(a.detail) : a.detail}` : ""}
                    </p>
                  </li>
                );
              })}
            </ul>
          )}
        </Card>
        <Card title="Guest events" sub="SSH logins, visitors, mail auth reported by the telemetry agent.">
          {events.length === 0 ? (
            <Empty>No telemetry for this server.</Empty>
          ) : (
            <ul className="space-y-1 text-xs">
              {events.map((e) => (
                <li key={e.id} className="flex flex-wrap justify-between gap-2">
                  <span>
                    <span className="font-mono">{e.type.toLowerCase()}</span> {e.user ? `· ${e.user}` : ""} {e.path ? `· ${e.path}` : ""} {e.status ? `· ${e.status}` : ""}
                  </span>
                  <span className="font-mono text-slate-500">{e.ip ?? ""} · {fmtDateTime(e.ts)}</span>
                </li>
              ))}
            </ul>
          )}
        </Card>
      </div>
    </div>
  );
}

