                      <summary className="cursor-pointer text-xs text-red-400">error</summary>
                      <pre className="mt-1 whitespace-pre-wrap break-all rounded-lg bg-black/30 p-2 font-mono text-[11px] text-red-300">{j.error}</pre>
                    </details>
                  )}
                  {!j.error && j.payload != null && (
                    <details className="mt-1">
                      <summary className="cursor-pointer text-xs text-slate-500">payload</summary>
                      <pre className="mt-1 whitespace-pre-wrap break-all rounded-lg bg-black/30 p-2 font-mono text-[11px] text-slate-400">{JSON.stringify(j.payload, null, 2)}</pre>
                    </details>
                  )}
                </li>
              );
            })}
          </ol>
        )}
      </Card>

      <div className="grid gap-4 xl:grid-cols-2">
        <Card title="Audit log" sub="Every staff action that names this server.">
          {audits.length === 0 ? (
            <Empty>No audit entries.</Empty>
          ) : (
            <ul className="divide-y divide-white/[0.05] text-sm">
              {audits.map((a) => {
                const as = actingAdminId(a.detail);
                return (
                  <li key={a.id} className="py-2">
                    <div className="flex flex-wrap items-baseline justify-between gap-2">
                      <span className="font-mono text-xs">{a.action}</span>
                      <span className="text-xs text-slate-500">{fmtDateTime(a.createdAt)}</span>
                    </div>
                    <p className="text-xs text-slate-400">
                      {a.user?.email ?? "system"}
                      {as ? ` (as ${actors.get(as) ?? as})` : ""}
                      {a.ip ? ` · ${a.ip}` : ""}
                      {a.detail ? ` — ${as ? detailWithoutActor(a.detail) : a.detail}` : ""}
                    </p>
                  </li>
                );
              })}
            </ul>
          )}
        </Card>
        <Card title="Guest events" sub="SSH logins, visitors, mail auth reported by the telemetry agent.">
          {events.length === 0 ? (
            <Empty>No telemetry for this server.</Empty>
          ) : (
            <ul className="space-y-1 text-xs">
              {events.map((e) => (
                <li key={e.id} className="flex flex-wrap justify-between gap-2">
                  <span>
                    <span className="font-mono">{e.type.toLowerCase()}</span> {e.user ? `· ${e.user}` : ""} {e.path ? `· ${e.path}` : ""} {e.status ? `· ${e.status}` : ""}
                  </span>
                  <span className="font-mono text-slate-500">{e.ip ?? ""} · {fmtDateTime(e.ts)}</span>
                </li>
              ))}
            </ul>
          )}
        </Card>
      </div>
    </div>
  );
}

