import Link from "next/link";
import { db } from "@/lib/db";
import { SuspendServerButton } from "@/components/AdminControls";
import { buildDeleteManifest, deleteWarnings } from "@/lib/admin-server/delete-manifest";
import { liveSnapshots } from "@/lib/admin-server/live";
import { effectiveDiskGB, baseDiskGBFor } from "@/lib/extra-disk";
import { Card } from "../ui";
import { DeleteServerControl } from "../controls";
import type { ServerCore } from "../core";

export async function DangerTab({ server, isGame }: { server: ServerCore; isGame: boolean }) {
  const [volumes, { snaps }] = await Promise.all([
    db.volume.findMany({ where: { serverId: server.id }, select: { name: true, sizeGB: true } }),
    liveSnapshots(server),
  ]);
  const input = {
    hostname: server.hostname,
    vmid: server.vmid,
    nodeName: server.node?.name ?? null,
    diskGB: effectiveDiskGB(baseDiskGBFor(server), server.extraDiskGB),
    dedicatedIp: server.dedicatedIp?.address ?? null,
    portForwards: server._count.portForwards,
    volumes,
    subdomain: server.subdomain,
    isGame,
    snapshots: snaps ? snaps.length : null,
    firewallRules: server._count.firewallRules,
    websites: server._count.websites,
    databases: server._count.vpsDatabases,
    status: server.status,
    isFree: server.isFree,
    expiresAt: server.expiresAt,
  };
  const manifest = buildDeleteManifest(input);
  const warnings = deleteWarnings(input);

  return (
    <div className="space-y-4">
      <Card title="Suspend" sub="Stops the VM and locks the customer's controls. Reversible — unsuspend starts it again.">
        <SuspendServerButton serverId={server.id} suspended={server.status === "SUSPENDED"} />
      </Card>

      <Card title="Transfer ownership" sub="Moves the server to another customer account (typed hostname + reason, audited).">
        <Link href={`/admin/servers/${server.id}?tab=billing`} className="btn-secondary py-1.5 text-sm">
          Open ownership transfer (Billing tab)
        </Link>
      </Card>

      <section className="card border-red-500/25" aria-labelledby="del-h">
        <h2 id="del-h" className="mb-1 font-semibold text-red-400">Delete server</h2>
        <p className="mb-3 text-sm text-slate-400">Read exactly what is destroyed before typing the hostname. There is no undo and no automatic refund.</p>
        {warnings.length > 0 && (
          <ul className="mb-3 space-y-1 rounded-lg border border-amber-500/25 bg-amber-500/[0.06] p-3 text-sm text-amber-300" role="status">
            {warnings.map((w) => (
              <li key={w}>⚠ {w}</li>
            ))}
          </ul>
        )}
        <div className="mb-4 overflow-x-auto">
          <table className="table-shell" aria-label="Delete manifest">
            <thead>
              <tr>
                <th>What</th>
                <th>Effect</th>
                <th>Outcome</th>
              </tr>
            </thead>
            <tbody>
              {manifest.map((m) => (
                <tr key={m.label + m.detail}>
                  <td className="font-medium">{m.label}</td>
                  <td className="text-xs text-slate-300">{m.detail}</td>
                  <td>
                    <span className="adm-pill" data-tone={m.kind === "destroyed" ? "red" : m.kind === "released" ? "amber" : "green"}>{m.kind}</span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        {snaps === null && <p className="mb-3 text-xs text-amber-300">Snapshot count could not be read from the node — any snapshots are destroyed too.</p>}
        <DeleteServerControl serverId={server.id} hostname={server.hostname} />
      </section>
    </div>
  );
}

