  query: string;
  exportHref: string;
  empty: string;
}) {
  const router = useRouter();
  const defaults = useMemo(() => columns.filter((c) => c.defaultHidden).map((c) => c.key), [columns]);
  const [hidden, setHidden] = useState<string[]>(defaults);
  const [views, setViews] = useState<{ name: string; query: string }[]>([]);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null);
  const [pending, start] = useTransition();
  const [chooser, setChooser] = useState(false);

  // Hydration-safe: read storage after mount, never during render.
  useEffect(() => {
    setHidden(readLS<string[]>(COLS_KEY, defaults));
    setViews(readLS<{ name: string; query: string }[]>(VIEWS_KEY, []));
  }, [defaults]);

  const visible = columns.filter((c) => c.always || !hidden.includes(c.key));
  const allSel = rows.length > 0 && rows.every((r) => selected.has(r.id));

  function toggleCol(key: string) {
    const next = hidden.includes(key) ? hidden.filter((k) => k !== key) : [...hidden, key];
    setHidden(next);
    writeLS(COLS_KEY, next);
  }
  function saveView() {
    const name = window.prompt("Name this view (filters + sort are saved):", "");
    if (!name?.trim()) return;
    const next = [...views.filter((v) => v.name !== name.trim()), { name: name.trim().slice(0, 40), query }];
    setViews(next);
    writeLS(VIEWS_KEY, next);
  }
  function deleteView(name: string) {
    const next = views.filter((v) => v.name !== name);
    setViews(next);
    writeLS(VIEWS_KEY, next);
  }
  function bulk(action: "reconcile" | "diagnose") {
    const ids = [...selected];
    setMsg(null);
    start(async () => {
      const r = await adminFleetBulk(action, ids).catch((e) => ({ ok: 0, failed: ids.length, errors: [String(e?.message ?? e)] }));
      setMsg({ ok: r.failed === 0, text: `${action}: ${r.ok} ok${r.failed ? `, ${r.failed} failed — ${r.errors.join("; ")}` : ""}` });
      setSelected(new Set());
      router.refresh();
    });
  }
  function exportSelected() {
    const ids = [...selected];
    window.location.href = `${exportHref}${exportHref.includes("?") ? "&" : "?"}ids=${ids.join(",")}`;
  }

  return (
    <div className="card p-0">
      <div className="flex flex-wrap items-center gap-2 border-b border-white/[0.06] px-4 py-2.5">
        <span className="text-xs text-slate-500">Views:</span>
        {views.length === 0 && <span className="text-xs text-slate-600">none saved</span>}
        {views.map((v) => (
          <span key={v.name} className="inline-flex items-center gap-1 rounded-full border border-white/10 bg-white/[0.04] pl-3 text-xs">
            <a href={`/admin/servers${v.query ? `?${v.query}` : ""}`} className="py-1 text-slate-300 hover:text-white">{v.name}</a>
            <button type="button" className="px-2 py-1 text-slate-500 hover:text-red-300" aria-label={`Delete view ${v.name}`} onClick={() => deleteView(v.name)}>×</button>
          </span>
        ))}
        <button type="button" className="btn-ghost py-1 text-xs" onClick={saveView}>Save current view</button>
        <span className="ml-auto flex flex-wrap items-center gap-2">
          <div className="relative">
            <button type="button" className="btn-ghost py-1 text-xs" aria-expanded={chooser} onClick={() => setChooser(!chooser)}>Columns ▾</button>
            {chooser && (
              <div className="absolute right-0 z-20 mt-1 w-52 rounded-xl border border-white/10 bg-[var(--adm-surface-2,#0f1831)] p-2 shadow-xl" role="menu">
                {columns.filter((c) => !c.always).map((c) => (
                  <label key={c.key} className="flex cursor-pointer items-center gap-2 rounded px-2 py-1 text-xs hover:bg-white/[0.05]">
                    <input type="checkbox" checked={!hidden.includes(c.key)} onChange={() => toggleCol(c.key)} /> {c.label}
                  </label>
                ))}
              </div>
            )}
          </div>
          <a href={exportHref} className="btn-ghost py-1 text-xs">Export CSV (all matches)</a>
        </span>
      </div>

      {selected.size > 0 && (
        <div className="flex flex-wrap items-center gap-2 border-b border-white/[0.06] bg-brand-500/[0.06] px-4 py-2 text-xs" role="region" aria-label="Bulk actions">
          <span className="font-medium">{selected.size} selected</span>
          <button type="button" className="btn-secondary px-2.5 py-1 text-xs" disabled={pending} onClick={() => bulk("reconcile")} title="Read each VM's real state from Proxmox and fix the DB status">Reconcile status</button>
          <button type="button" className="btn-secondary px-2.5 py-1 text-xs" disabled={pending} onClick={() => bulk("diagnose")} title="Queue a read-only diagnosis job for each">Diagnose</button>
          <button type="button" className="btn-ghost px-2.5 py-1 text-xs" onClick={exportSelected}>Export selected</button>
          <a href="/admin/ops/fleet" className="btn-ghost px-2.5 py-1 text-xs" title="Bulk power and delete need a typed confirmation and run with a concurrency cap">Power / delete in bulk →</a>
          <button type="button" className="btn-ghost px-2.5 py-1 text-xs" onClick={() => setSelected(new Set())}>Clear</button>
        </div>
      )}
      {msg && <p role={msg.ok ? "status" : "alert"} className={`px-4 py-2 text-xs ${msg.ok ? "text-emerald-400" : "text-amber-300"}`}>{msg.text}</p>}

      <div className="overflow-x-auto">
        <table className="table-shell" style={{ minWidth: Math.max(720, visible.length * 120) }}>
          <thead>
            <tr>
              <th className="w-8">
                <input type="checkbox" aria-label="Select all on this page" checked={allSel} onChange={() => setSelected(allSel ? new Set() : new Set(rows.map((r) => r.id)))} />
              </th>
              {visible.map((c) => (
                <th key={c.key} className={c.className}>{c.label}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.length === 0 ? (
              <tr>
                <td colSpan={visible.length + 1} className="py-10 text-center text-sm text-slate-500">{empty}</td>
              </tr>
            ) : (
              rows.map((r) => (
                <tr key={r.id} data-selected={selected.has(r.id) || undefined}>
                  <td>
                    <input
                      type="checkbox"
                      aria-label="Select row"
                      checked={selected.has(r.id)}
                      onChange={() =>
                        setSelected((prev) => {
                          const n = new Set(prev);
                          n.has(r.id) ? n.delete(r.id) : n.add(r.id);
                          return n;
                        })
                      }
                    />
                  </td>
                  {visible.map((c) => (
                    <td key={c.key} className={c.className}>{r.cells[c.key] ?? null}</td>
                  ))}
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

