import "server-only";
import { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { latestDriftScan } from "@/lib/admin-ops/actions";

/**
 * Context the fleet filter needs from outside the Server table: servers the
 * last drift scan flagged (mismatch) and servers with an OPEN abuse alert
 * (flagged). Both are small sets.
 */
export async function fleetFilterContext(): Promise<{ driftServerIds: string[]; abuseServerIds: string[] }> {
  const [drift, abuse] = await Promise.all([
    latestDriftScan().catch(() => null),
    db.abuseAlert.findMany({ where: { status: "OPEN" }, select: { serverId: true }, distinct: ["serverId"] }),
  ]);
  const findings = ((drift?.result as { findings?: { serverId?: string | null }[] } | null)?.findings ?? []) as { serverId?: string | null }[];
  return {
    driftServerIds: [...new Set(findings.map((f) => f.serverId).filter((x): x is string => !!x))],
    abuseServerIds: abuse.map((a) => a.serverId),
  };
}

/** Latest guest sample per server (mem or disk) for just the given ids — one DISTINCT ON query. */
export async function latestSamples(table: "ServerMemSample" | "ServerDiskSample", serverIds: string[]) {
  if (serverIds.length === 0) return new Map<string, { usedBytes: bigint; totalBytes: bigint; ts: Date }>();
  const rows = await db.$queryRaw<{ serverId: string; usedBytes: bigint; totalBytes: bigint; ts: Date }[]>(
    Prisma.sql`SELECT DISTINCT ON ("serverId") "serverId", "usedBytes", "totalBytes", "ts"
               FROM ${Prisma.raw(`"${table}"`)}
               WHERE "serverId" IN (${Prisma.join(serverIds)})
               ORDER BY "serverId", "ts" DESC`,
  );
  return new Map(rows.map((r) => [r.serverId, r]));
}

