import Link from "next/link";
import { requireArea } from "@/lib/rbac";
import { db } from "@/lib/db";
import { PageHeader, StatusDot, Badge, fmtMoney, fmtBytes } from "@/components/ui/primitives";
import { MeterBar } from "@/components/ui/charts";
import { currentRenewalPrices } from "@/lib/admin-metrics";
import { serverFleetPriceCents, serverFleetTags, type FleetTag } from "@/lib/admin-fleet";
import { dunningConfig } from "@/lib/dunning-config";
import { SuspendServerButton, ReconcileServerButton } from "@/components/AdminControls";
import { RebootServerButton } from "@/components/admin/ServerAdminActions";
import { ServerFleetTable, type FleetColumn, type FleetRow } from "@/components/admin/ServerFleetTable";
import { AutoRefresh } from "@/components/AutoRefresh";
import { pveForNode, listVms } from "@/lib/proxmox";
import { REGION_LABELS, REGION_COUNTRY } from "@/lib/node-regions";
import { CountryFlag } from "@/components/ui/CountryFlag";
import { resolveServerLifetimeSpendCents } from "@/lib/server-spend";
import { GAME_DISPLAY, GAME_ART_SLUG, type GameFamily } from "@/lib/games";
import { parseFleetFilters, fleetWhere, fleetOrderBy, fleetHref, fleetFiltersToParams, FLEET_COLUMNS, SERVER_STATUSES, PER_PAGE_OPTIONS, type FleetFilters } from "@/lib/admin-server/fleet-query";
import { dbOnlyHealth, evaluateStateTruth } from "@/lib/admin-server/state-truth";
import { fleetFilterContext, latestSamples } from "@/lib/admin-server/fleet-load";
import { withTimeout } from "@/lib/admin-server/live";
import { FleetTable, type FleetRowView } from "@/components/admin/server360/FleetTable";

export const dynamic = "force-dynamic";

const TRANSITIONAL = ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"];
const EXPIRING_SOON_DAYS = 5;

/** Archive-backed views (ServerArchive.reason) — kept exactly as before the redesign. */
const ARCHIVE_FILTERS: Record<string, { label: string; reasons: string[] }> = {
  CANCELLED: { label: "cancelled", reasons: ["CANCELLED"] },
  EXPIRED: { label: "expired", reasons: ["EXPIRED"] },
  DELETED: { label: "deleted", reasons: ["REMOVED", "DELETED"] },
};

function GameCover({ family }: { family: string }) {
  const art = GAME_ART_SLUG[family as GameFamily];
  const display = GAME_DISPLAY[family as GameFamily];
  if (art?.poster) return <img src={`/games/art/${art.poster}_poster.jpg`} alt="" width={28} height={28} className="h-7 w-7 shrink-0 rounded-md object-cover" />;
  return <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md bg-white/[0.06] text-sm">{display?.glyph ?? "🎮"}</span>;
}

function VpsIcon() {
  return (
    <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md bg-white/[0.06] text-slate-300">
      <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
        <rect x="3" y="4" width="18" height="7" rx="2" />
        <rect x="3" y="13" width="18" height="7" rx="2" />
        <circle cx="7.5" cy="7.5" r="0.8" fill="currentColor" />
        <circle cx="7.5" cy="16.5" r="0.8" fill="currentColor" />
      </svg>
    </span>
  );
}

function ServiceType({ gameFamily }: { gameFamily: string | null }) {
  return (
    <div className="flex items-center gap-2">
      {gameFamily ? <GameCover family={gameFamily} /> : <VpsIcon />}
      <Badge tone={gameFamily ? "brand" : "slate"}>{gameFamily ? GAME_DISPLAY[gameFamily as GameFamily]?.name ?? "Game" : "VPS"}</Badge>
    </div>
  );
}

function RegionCell({ region }: { region: string | null }) {
  if (!region) return <span className="text-xs text-slate-500">—</span>;
  const code = REGION_COUNTRY[region];
  return (
    <span className="flex items-center gap-1.5 text-xs text-slate-400">
      {code && <CountryFlag code={code} size={14} />}
      {REGION_LABELS[region] ?? region}
    </span>
  );
}

function HealthDot({ health, title }: { health: "ok" | "warn" | "bad" | "unknown"; title: string }) {
  const color = health === "ok" ? "bg-emerald-400" : health === "warn" ? "bg-amber-400" : health === "bad" ? "bg-red-500" : "bg-slate-500";
  return (
    <span className="inline-flex items-center" title={title}>
      <span className={`h-2.5 w-2.5 rounded-full ${color}`} aria-hidden />
      <span className="sr-only">{health}: {title}</span>
    </span>
  );
}

function Meter({ pct, label }: { pct: number | null; label: string }) {
  if (pct == null) return <span className="text-xs text-slate-600">{label}</span>;
  return (
    <div className="min-w-24 space-y-1">
      <div className="flex justify-between text-[11px] text-slate-500">
        <span className="font-mono">{label}</span>
      </div>
      <MeterBar value={pct} max={100} color={pct > 90 ? "#ef4444" : pct > 75 ? "#f59e0b" : "#34d399"} />
    </div>
  );
}

export default async function AdminServers({ searchParams }: { searchParams: Promise<Record<string, string | string[] | undefined>> }) {
  await requireArea("fleet");
  const sp = await searchParams;
  const rawStatus = (Array.isArray(sp.status) ? sp.status[0] : sp.status) ?? "";

  // ── Archive views ─────────────────────────────────────────────────────────
  if (ARCHIVE_FILTERS[rawStatus]) {
    const filter = ARCHIVE_FILTERS[rawStatus];
    const [archived, liveCounts, archiveCounts] = await Promise.all([
      db.serverArchive.findMany({ where: { reason: { in: filter.reasons } }, orderBy: { deletedAt: "desc" }, take: 1000 }),
      db.server.count(),
      db.serverArchive.groupBy({ by: ["reason"], _count: true }),
    ]);
    const archiveCountFor = (reasons: string[]) => archiveCounts.filter((c) => reasons.includes(c.reason)).reduce((n, c) => n + c._count, 0);
    const columns: FleetColumn[] = [
      { header: "Hostname" }, { header: "Owner" }, { header: "Type" }, { header: "Service" }, { header: "Node" },
      { header: "Region" }, { header: "Total spent" }, { header: "Provisioned" }, { header: "Reason" }, { header: "Removed" },
    ];
    const rows: FleetRow[] = archived.map((a) => ({
      id: a.id,
      search: [a.hostname, a.userEmail, a.serviceName, a.nodeName].filter(Boolean).join(" ").toLowerCase(),
      cells: [
        <span key="h" className="font-medium text-slate-300">{a.hostname}</span>,
        a.userId ? <Link key="o" href={`/admin/users/${a.userId}`} className="text-slate-300 hover:text-brand-300">{a.userEmail}</Link> : <span key="o" className="text-slate-500">{a.userEmail || "—"}</span>,
        <ServiceType key="t" gameFamily={a.gameFamily} />,
        <span key="p" className="text-xs">{a.serviceName}</span>,
        <span key="n" className="text-xs text-slate-400">{a.nodeName ?? "—"}</span>,
        <RegionCell key="r" region={a.region} />,
        <span key="sp" className="text-xs">{a.totalSpentCents > 0 ? fmtMoney(a.totalSpentCents) : <span className="text-slate-600">—</span>}</span>,
        <span key="prov" className="text-xs text-slate-400">{a.provisionedAt.toISOString().slice(0, 10)}</span>,
        <Badge key="reason" tone={a.reason === "CANCELLED" ? "slate" : a.reason === "EXPIRED" ? "amber" : "red"}>{a.reason.toLowerCase()}</Badge>,
        <span key="del" className="text-xs text-slate-400" title={a.deletedAt.toISOString()}>{a.deletedAt.toISOString().slice(0, 10)}</span>,
      ],
    }));
    return (
      <div className="space-y-6">
        <PageHeader title="Server fleet" sub={`${archived.length} ${filter.label} server${archived.length === 1 ? "" : "s"}.`} />
        <StatusChips liveTotal={liveCounts} archiveCountFor={archiveCountFor} active={rawStatus} />
        <ServerFleetTable columns={columns} rows={rows} minWidth={1400} empty={`No ${filter.label} servers.`} />
      </div>
    );
  }

  // ── Live fleet: server-side filtered + paginated ──────────────────────────
  const f = parseFleetFilters(sp);
  const now = new Date();
  const ctx = f.mismatch || f.flagged ? await fleetFilterContext() : { driftServerIds: [], abuseServerIds: [] };
  const where = fleetWhere(f, { now, ...ctx });

  const [total, counts, archiveCounts, nodes, plans, gamePlans, families] = await Promise.all([
    db.server.count({ where }),
    db.server.groupBy({ by: ["status"], _count: true }),
    db.serverArchive.groupBy({ by: ["reason"], _count: true }),
    db.node.findMany({ select: { id: true, name: true, region: true }, orderBy: { createdAt: "asc" } }),
    db.plan.findMany({ select: { id: true, name: true }, orderBy: { priceCents: "asc" } }),
    db.gamePlan.findMany({ select: { id: true, name: true, gameFamily: true }, orderBy: [{ gameFamily: "asc" }, { priceCents: "asc" }] }),
    db.gamePlan.findMany({ select: { gameFamily: true }, distinct: ["gameFamily"] }),
  ]);
  const pages = Math.max(1, Math.ceil(total / f.per));
  const page = Math.min(f.page, pages);
  const servers = await db.server.findMany({
    where,
    orderBy: fleetOrderBy(f),
    skip: (page - 1) * f.per,
    take: f.per,
    include: {
      user: { select: { id: true, email: true, name: true } },
      plan: { select: { name: true, priceCents: true } },
      gamePlan: { select: { name: true, priceCents: true, termMonths: true, gameFamily: true } },
      node: { select: { id: true, name: true, region: true, publicIp: true, apiUrl: true, pveNode: true, tokenId: true, tokenSecret: true } },
      dedicatedIp: { select: { id: true, address: true } },
      gameRuntime: { select: { state: true, probedAt: true, intent: true, probeError: true } },
      jobs: { where: { status: { in: ["QUEUED", "RUNNING"] } }, take: 1, select: { type: true, status: true, updatedAt: true } },
    },
  });

  const countByStatus = new Map(counts.map((c) => [c.status as string, c._count]));
  const liveTotal = counts.reduce((n, c) => n + c._count, 0);
  const archiveCountFor = (reasons: string[]) => archiveCounts.filter((c) => reasons.includes(c.reason)).reduce((n, c) => n + c._count, 0);
  const ids = servers.map((s) => s.id);

  // Live CPU: one Proxmox /qemu call per node present on THIS page (capped), never per server.
  const pageNodes = new Map(servers.map((s) => s.node).filter((n): n is NonNullable<typeof n> => !!n).map((n) => [n.id, n]));
  const liveByNode = new Map(
    await Promise.all(
      [...pageNodes.values()].map(async (n) => {
        try {
          const vms = await withTimeout(listVms(pveForNode(n)), 6000);
          return [n.id, new Map(vms.map((v: any) => [v.vmid, v]))] as const;
        } catch {
          return [n.id, null] as const;
        }
      }),
    ),
  );
  const [memById, diskById, spendById, renewalPrices] = await Promise.all([
    latestSamples("ServerMemSample", ids),
    latestSamples("ServerDiskSample", ids).catch(() => new Map()),
    resolveServerLifetimeSpendCents(servers.map((s) => ({ id: s.id, hostname: s.hostname, previousHostnames: s.previousHostnames, userId: s.userId, createdAt: s.createdAt }))),
    currentRenewalPrices(),
  ]);
  const dunningCfg = servers.some((s) => s.status === "SUSPENDED" && s.suspendReason === "UNPAID") ? await dunningConfig() : null;

  const expiringSoon = await db.server.findMany({
    where: { isFree: false, status: { notIn: ["SUSPENDED", "DELETING"] }, expiresAt: { gte: now, lte: new Date(now.getTime() + EXPIRING_SOON_DAYS * 86_400_000) } },
    orderBy: { expiresAt: "asc" },
    take: 9,
    select: { id: true, hostname: true, expiresAt: true },
  });
  const expiringCount = await db.server.count({ where: { isFree: false, status: { notIn: ["SUSPENDED", "DELETING"] }, expiresAt: { gte: now, lte: new Date(now.getTime() + EXPIRING_SOON_DAYS * 86_400_000) } } });

  const rows: FleetRowView[] = servers.map((s) => {
    const gameFamily = s.gamePlan?.gameFamily ?? null;
    const nodeLive = s.node ? liveByNode.get(s.node.id) : undefined;
    const live = s.vmid && nodeLive ? nodeLive.get(s.vmid) : null;
    const job = s.jobs[0] ?? null;
    const truthInput = {
      dbStatus: s.status,
      provisionError: s.provisionError,
      suspendReason: s.suspendReason,
      isGame: !!gameFamily,
      runtime: s.gameRuntime ? { state: s.gameRuntime.state, probedAt: s.gameRuntime.probedAt, intent: s.gameRuntime.intent, probeError: s.gameRuntime.probeError } : null,
      activeJob: job,
      updatedAt: s.updatedAt,
      now,
    };
    const truth = !s.vmid
      ? dbOnlyHealth(truthInput)
      : nodeLive === null || nodeLive === undefined
        ? evaluateStateTruth({ ...truthInput, proxmox: { kind: "unreachable" } })
        : evaluateStateTruth({ ...truthInput, proxmox: live ? { kind: "vm", status: String(live.status) } : { kind: "missing" } });
    const healthTitle = truth.mismatches.filter((m) => m.severity !== "info").map((m) => m.message).join(" · ") || (truth.health === "unknown" ? "Node unreachable" : "All sources agree");
    const mem = memById.get(s.id);
    const disk = diskById.get(s.id) as { usedBytes: bigint; totalBytes: bigint } | undefined;
    const memPct = mem && mem.totalBytes > 0n ? (Number(mem.usedBytes) / Number(mem.totalBytes)) * 100 : null;
    const diskPct = disk && disk.totalBytes > 0n ? (Number(disk.usedBytes) / Number(disk.totalBytes)) * 100 : null;
    const cpuPct = live ? Math.round((live.cpu ?? 0) * 100) : null;
    const tags: FleetTag[] = serverFleetTags(s, { now, renewingSoonWindowMs: EXPIRING_SOON_DAYS * 86_400_000, dunning: dunningCfg });
    const priceMonthly = serverFleetPriceCents(s, renewalPrices);
    const spent = spendById.get(s.id) ?? 0;
    const endpoint = s.dedicatedIp ? s.dedicatedIp.address : s.sshPort ? `${s.node?.publicIp ?? process.env.PUBLIC_IP ?? "—"}:${s.sshPort}` : s.ipAddress ?? "—";
    return {
      id: s.id,
      cells: {
        health: <HealthDot health={truth.health} title={healthTitle} />,
        hostname: (
          <span>
            <Link href={`/admin/servers/${s.id}`} className="font-medium hover:text-brand-300">{s.label || s.hostname}</Link>
            {s.label && <div className="font-mono text-[11px] text-slate-500">{s.hostname}</div>}
            {(s.isFree || tags.length > 0) && (
              <div className="mt-1 flex flex-wrap gap-1">
                {s.isFree && <Badge tone="green">free</Badge>}
                {tags.map((t) => (
                  <span key={t.key} title={t.title}><Badge tone={t.tone}>{t.label}</Badge></span>
                ))}
              </div>
            )}
          </span>
        ),
        owner: (
          <span>
            <Link href={`/admin/users/${s.user.id}`} className="text-slate-300 hover:text-brand-300">{s.user.email}</Link>
            <Link href={fleetHref("/admin/servers", { owner: s.user.id })} className="ml-1 text-[11px] text-slate-500 hover:text-brand-300" title="Only this owner's servers">⌕</Link>
          </span>
        ),
        type: <ServiceType gameFamily={gameFamily} />,
        plan: (
          <span>
            {s.gamePlan ? s.gamePlan.name : s.plan.name}
            {!s.isFree && <span className="text-xs text-slate-500"> · {fmtMoney(priceMonthly)}/mo</span>}
          </span>
        ),
        vmid: <span className="font-mono text-xs">{s.vmid ?? "—"}</span>,
        endpoint: (
          <span className="font-mono text-xs">
            {endpoint}
            {s.ipAddress && !s.dedicatedIp && <div className="text-slate-600">int {s.ipAddress}</div>}
          </span>
        ),
        node: (
          <span className="text-xs">
            {s.node ? <Link href={`/admin/nodes/${s.node.id}`} className="hover:text-brand-300">{s.node.name}</Link> : "—"}
            <RegionCell region={s.node?.region ?? null} />
          </span>
        ),
        cpu: <Meter pct={cpuPct} label={cpuPct == null ? (s.vmid ? "unavailable" : "—") : `${cpuPct}%`} />,
        ram: <Meter pct={memPct} label={mem && mem.totalBytes > 0n ? `${fmtBytes(Number(mem.usedBytes))} / ${fmtBytes(Number(mem.totalBytes))}` : "not measured"} />,
        disk: <Meter pct={diskPct} label={disk && disk.totalBytes > 0n ? `${fmtBytes(Number(disk.usedBytes))} / ${fmtBytes(Number(disk.totalBytes))}` : "not measured"} />,
        status: (
          <span>
            <StatusDot status={s.status} />
            {job && <div className="text-[11px] text-sky-300">{job.type.toLowerCase().replace(/_/g, " ")} · {job.status.toLowerCase()}</div>}
          </span>
        ),
        expires: <span className="text-xs">{s.isFree ? "never" : s.expiresAt ? s.expiresAt.toISOString().slice(0, 10) : "—"}</span>,
        spend: <span className="text-xs" title="Real lifetime total: order + renewals + add-ons, net of refunds">{spent > 0 ? fmtMoney(spent) : <span className="text-slate-600">—</span>}</span>,
        created: <span className="text-xs text-slate-400">{s.createdAt.toISOString().slice(0, 10)}</span>,
        actions: (
          <div className="flex flex-wrap items-center justify-end gap-2">
            {["ERROR", "PENDING", "PROVISIONING"].includes(s.status) && <ReconcileServerButton serverId={s.id} />}
            {s.status !== "DELETING" && <RebootServerButton serverId={s.id} status={s.status} />}
            {s.status !== "DELETING" && <SuspendServerButton serverId={s.id} suspended={s.status === "SUSPENDED"} />}
          </div>
        ),
      },
    };
  });

  const qs = new URLSearchParams(fleetFiltersToParams({ ...f, page: 1 })).toString();
  const exportHref = `/api/admin/servers/export${qs ? `?${qs}` : ""}`;
  const anyTransitional = servers.some((s) => TRANSITIONAL.includes(s.status));
  const activeFilters = Object.keys(fleetFiltersToParams({ ...f, page: 1, sort: "created", dir: "desc", per: 25 })).length;

  return (
    <div className="space-y-5">
      {anyTransitional && <AutoRefresh />}
      <PageHeader title="Server fleet" sub={`${total} of ${liveTotal} server${liveTotal === 1 ? "" : "s"}${activeFilters ? " match the filters" : " across all clients"}.`} />

      {expiringCount > 0 && (
        <div className="rounded-xl border border-amber-500/30 bg-amber-500/[0.07] px-4 py-3">
          <div className="flex flex-wrap items-center gap-3 text-sm text-amber-300">
            <span className="font-medium">{expiringCount} server{expiringCount === 1 ? "" : "s"} renewing within {EXPIRING_SOON_DAYS} days</span>
            <Link href={fleetHref("/admin/servers", { expiring: EXPIRING_SOON_DAYS, sort: "expires", dir: "asc" })} className="text-xs underline">show them</Link>
          </div>
          <div className="mt-2 flex flex-wrap gap-x-4 gap-y-1 text-xs text-amber-300/80">
            {expiringSoon.slice(0, 8).map((s) => (
              <Link key={s.id} href={`/admin/servers/${s.id}`} className="hover:text-amber-200 hover:underline">{s.hostname} · {s.expiresAt!.toISOString().slice(0, 10)}</Link>
            ))}
          </div>
        </div>
      )}

      <StatusChips liveTotal={liveTotal} countByStatus={countByStatus} archiveCountFor={archiveCountFor} liveActive={f.status ?? undefined} active={undefined} base={f} />

      <FilterBar f={f} nodes={nodes} regions={[...new Set(nodes.map((n) => n.region))]} plans={plans} gamePlans={gamePlans} families={families.map((x) => x.gameFamily)} />

      <FleetTable
        columns={FLEET_COLUMNS.map((c) => ({ key: c.key, label: c.label, always: "always" in c ? c.always : false, defaultHidden: "defaultHidden" in c ? c.defaultHidden : false, className: c.key === "actions" ? "text-right" : undefined }))}
        rows={rows}
        query={qs}
        exportHref={exportHref}
        empty={activeFilters ? "No servers match these filters." : "No servers yet."}
      />

      <Pager f={f} page={page} pages={pages} total={total} />

      <p className="text-xs text-slate-500">
        Health compares the database status with the VM&apos;s real Proxmox state (and the game runtime for game servers) — hover a dot for the reason; open
        the server for fixes. CPU is live from the node; RAM and disk are the latest guest-agent samples. Price is what the server will actually be charged at
        its next renewal (add-ons and any locked rate included). Total spent is a real historical sum, net of refunds. Bulk actions here are non-destructive;
        bulk power/delete live on Ops → Fleet.
      </p>
    </div>
  );
}

function FilterBar({ f, nodes, regions, plans, gamePlans, families }: {
  f: FleetFilters;
  nodes: { id: string; name: string }[];
  regions: string[];
  plans: { id: string; name: string }[];
  gamePlans: { id: string; name: string; gameFamily: string }[];
  families: string[];
}) {
  const sel = "input py-1.5 text-xs";
  return (
    <form method="GET" action="/admin/servers" className="card flex flex-wrap items-end gap-2 p-3" role="search" aria-label="Filter servers">
      <label className="min-w-56 flex-1">
        <span className="mb-1 block text-[11px] text-slate-500">Search</span>
        <input className="input w-full py-1.5 text-sm" type="search" name="q" defaultValue={f.q} placeholder="hostname, IP, VMID, SSH port, owner email…" />
      </label>
      <label>
        <span className="mb-1 block text-[11px] text-slate-500">Status</span>
        <select name="status" defaultValue={f.status ?? ""} className={sel}>
          <option value="">Any</option>
          {SERVER_STATUSES.map((s) => <option key={s} value={s}>{s.toLowerCase()}</option>)}
        </select>
      </label>
      <label>
        <span className="mb-1 block text-[11px] text-slate-500">Node</span>
        <select name="node" defaultValue={f.node ?? ""} className={sel}>
          <option value="">Any</option>
          {nodes.map((n) => <option key={n.id} value={n.id}>{n.name}</option>)}
        </select>
      </label>
      <label>
        <span className="mb-1 block text-[11px] text-slate-500">Region</span>
        <select name="region" defaultValue={f.region ?? ""} className={sel}>
          <option value="">Any</option>
          {regions.map((r) => <option key={r} value={r}>{REGION_LABELS[r] ?? r}</option>)}
        </select>
      </label>
      <label>
        <span className="mb-1 block text-[11px] text-slate-500">Type / game</span>
        <select name="kind" defaultValue={f.kind ?? ""} className={sel}>
          <option value="">Any</option>
          <option value="vps">VPS</option>
          <option value="game">Any game</option>
          {families.map((g) => <option key={g} value={g}>{GAME_DISPLAY[g as GameFamily]?.name ?? g}</option>)}
        </select>
      </label>
      <label>
        <span className="mb-1 block text-[11px] text-slate-500">Plan</span>
        <select name="plan" defaultValue={f.plan ?? ""} className={`${sel} max-w-44`}>
          <option value="">Any</option>
          <optgroup label="VPS plans">{plans.map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}</optgroup>
          <optgroup label="Game plans">{gamePlans.map((p) => <option key={p.id} value={p.id}>{GAME_DISPLAY[p.gameFamily as GameFamily]?.name ?? p.gameFamily} · {p.name}</option>)}</optgroup>
        </select>
      </label>
      <label>
        <span className="mb-1 block text-[11px] text-slate-500">Expiring</span>
        <select name="expiring" defaultValue={f.expiring ? String(f.expiring) : ""} className={sel}>
          <option value="">Any</option>
          <option value="3">≤ 3 days</option>
          <option value="7">≤ 7 days</option>
          <option value="14">≤ 14 days</option>
          <option value="30">≤ 30 days</option>
        </select>
      </label>
      <label className="flex items-center gap-1.5 pb-2 text-xs"><input type="checkbox" name="flagged" value="1" defaultChecked={f.flagged} /> Flagged</label>
      <label className="flex items-center gap-1.5 pb-2 text-xs" title="DB status disagrees with reality: ERROR, stuck transitions, game down while VM up, or flagged by the last drift scan"><input type="checkbox" name="mismatch" value="1" defaultChecked={f.mismatch} /> Mismatch</label>
      <label>
        <span className="mb-1 block text-[11px] text-slate-500">Sort</span>
        <select name="sort" defaultValue={f.sort} className={sel}>
          <option value="created">Created</option>
          <option value="expires">Expires</option>
          <option value="hostname">Hostname</option>
          <option value="status">Status</option>
          <option value="vmid">VMID</option>
        </select>
      </label>
      <label>
        <span className="mb-1 block text-[11px] text-slate-500">Order</span>
        <select name="dir" defaultValue={f.dir} className={sel}>
          <option value="desc">desc</option>
          <option value="asc">asc</option>
        </select>
      </label>
      <label>
        <span className="mb-1 block text-[11px] text-slate-500">Per page</span>
        <select name="per" defaultValue={String(f.per)} className={sel}>
          {PER_PAGE_OPTIONS.map((n) => <option key={n} value={n}>{n}</option>)}
        </select>
      </label>
      {f.owner && <input type="hidden" name="owner" value={f.owner} />}
      <button className="btn-primary py-1.5 text-xs">Apply</button>
      <Link href="/admin/servers" className="btn-ghost py-1.5 text-xs">Reset</Link>
      {f.owner && <span className="w-full text-xs text-slate-400">Filtered to one owner · <Link href={fleetHref("/admin/servers", { ...f, owner: null, page: 1 })} className="underline">remove</Link></span>}
    </form>
  );
}

function Pager({ f, page, pages, total }: { f: FleetFilters; page: number; pages: number; total: number }) {
  return (
    <nav className="flex flex-wrap items-center justify-between gap-3 text-xs text-slate-500" aria-label="Pagination">
      <span>Page {page} of {pages} · {total} server{total === 1 ? "" : "s"}</span>
      <div className="flex items-center gap-2">
        {page > 1 && <Link href={fleetHref("/admin/servers", { ...f, page: 1 })} className="btn-ghost py-1 text-xs">« First</Link>}
        {page > 1 && <Link href={fleetHref("/admin/servers", { ...f, page: page - 1 })} className="btn-ghost py-1 text-xs" rel="prev">← Prev</Link>}
        {page < pages && <Link href={fleetHref("/admin/servers", { ...f, page: page + 1 })} className="btn-ghost py-1 text-xs" rel="next">Next →</Link>}
        {page < pages && <Link href={fleetHref("/admin/servers", { ...f, page: pages })} className="btn-ghost py-1 text-xs">Last »</Link>}
      </div>
    </nav>
  );
}

/** Status chips: every live status + the archive views, preserving other filters on the live ones. */
function StatusChips({ liveTotal, countByStatus, archiveCountFor, liveActive, active, base }: {
  liveTotal: number;
  countByStatus?: Map<string, number>;
  archiveCountFor: (reasons: string[]) => number;
  liveActive?: string;
  active: string | undefined;
  base?: FleetFilters;
}) {
  const chip = (href: string, label: string, count: number, isActive: boolean) => (
    <Link
      key={href + label}
      href={href}
      aria-current={isActive ? "page" : undefined}
      className={`rounded-full border px-3 py-1 text-xs font-medium transition-colors ${isActive ? "border-brand-500/40 bg-brand-500/10 text-brand-300" : "border-white/10 bg-white/[0.04] text-slate-400 hover:text-slate-200"}`}
    >
      {label} · {count}
    </Link>
  );
  const keep = base ? { ...base, page: 1 } : {};
  return (
    <div className="flex flex-wrap items-center gap-2">
      {chip(fleetHref("/admin/servers", { ...keep, status: null }), "All", liveTotal, !liveActive && !active)}
      {countByStatus && SERVER_STATUSES.filter((s) => countByStatus.has(s)).map((s) => chip(fleetHref("/admin/servers", { ...keep, status: s }), s.toLowerCase(), countByStatus.get(s)!, liveActive === s))}
      <span className="mx-1 h-4 w-px bg-white/10" />
      {Object.entries(ARCHIVE_FILTERS).map(([key, fl]) => chip(`/admin/servers?status=${key}`, fl.label, archiveCountFor(fl.reasons), active === key))}
    </div>
  );
}

