import { NextRequest, NextResponse } from "next/server";
import { realUser } from "@/lib/auth";
import { canAccess } from "@/lib/rbac";
import { db } from "@/lib/db";
import { recordAudit } from "@/lib/audit";
import { currentRenewalPrices } from "@/lib/admin-metrics";
import { serverFleetPriceCents } from "@/lib/admin-fleet";
import { parseFleetFilters, fleetWhere, fleetOrderBy, csvCell } from "@/lib/admin-server/fleet-query";
import { fleetFilterContext } from "@/lib/admin-server/fleet-load";

/**
 * CSV export of /admin/servers — the SAME filter parser + Prisma where as the
 * page (lib/admin-server/fleet-query.ts), so the file always matches the
 * screen. `ids=a,b,c` exports just the selected rows. Fleet area only (ADMIN),
 * refused while impersonating, capped at 5000 rows, audited, never cached.
 * Contains no secrets (no passwords, no keys).
 */
export const dynamic = "force-dynamic";

const MAX_ROWS = 5000;

export async function GET(req: NextRequest) {
  const user = await realUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  if (!canAccess(user.role, "fleet")) return NextResponse.json({ error: "forbidden" }, { status: 403 });

  const sp = Object.fromEntries(req.nextUrl.searchParams.entries());
  const f = parseFleetFilters(sp);
  const ids = (sp.ids ?? "")
    .split(",")
    .map((s) => s.trim())
    .filter((s) => /^[a-z0-9]{8,40}$/i.test(s))
    .slice(0, 500);
  const ctx = f.mismatch || f.flagged ? await fleetFilterContext() : { driftServerIds: [], abuseServerIds: [] };
