  const lines = [headers.map(csvCell).join(",")];
  for (const s of servers) {
    lines.push(
      [
        s.id, s.hostname, s.label ?? "", s.user.email, s.gamePlan ? "game" : "vps", s.gamePlan?.gameFamily ?? "",
        s.gamePlan?.name ?? s.plan.name, s.status, s.vmid ?? "", s.node?.name ?? "", s.node?.region ?? "",
        s.dedicatedIp?.address ?? s.node?.publicIp ?? "", s.sshPort ?? "", s.ipAddress ?? "", s.dedicatedIp?.address ?? "",
