import "server-only";
import { cache } from "react";
import { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { geoLocateIp } from "@/lib/geo-ip";
import { evaluateRisk, emailFamilyKey, parseFlagNote, type RiskFacts, type RiskReport } from "@/lib/admin-client/risk";

/** The customer row every tab of /admin/users/[id] starts from (deduped by React cache). */
export const loadClientCore = cache(async (id: string) => {
  return db.user.findUnique({
    where: { id },
    include: {
      customerNotes: { include: { author: { select: { name: true, email: true } } }, orderBy: { createdAt: "desc" } },
      _count: {
        select: { servers: true, sshKeys: true, notifications: true, hostingAccounts: true, emailSubscriptions: true, domains: true, invoices: true, apiTokens: true, tickets: true, paymentCards: true },
      },
    },
  });
});
export type ClientCore = NonNullable<Awaited<ReturnType<typeof loadClientCore>>>;

export function clientFlags(c: ClientCore) {
  return c.customerNotes
    .map((n) => ({ note: n, flag: parseFlagNote(n.body) }))
    .filter((x): x is { note: (typeof c.customerNotes)[number]; flag: NonNullable<ReturnType<typeof parseFlagNote>> } => !!x.flag);
}

const DAY = 86_400_000;

/**
 * Gather the facts lib/admin-client/risk.ts scores. Everything is a bounded
 * read (indexed columns, LIMITs), so the profile tab stays fast on old
 * accounts with thousands of visits.
 */
export const loadRisk = cache(async (c: ClientCore): Promise<{ report: RiskReport; facts: RiskFacts }> => {
  const [visits, sessions, cards, invoices, abuse, archives, fraudAudits] = await Promise.all([
    db.visit.findMany({ where: { userId: c.id }, orderBy: { createdAt: "desc" }, take: 500, select: { ip: true, country: true, visitorId: true } }),
    db.userSession.findMany({ where: { userId: c.id }, orderBy: { createdAt: "desc" }, take: 100, select: { ip: true } }),
    db.paymentCard.findMany({ where: { userId: c.id }, select: { createdAt: true, unusableAt: true } }),
    db.invoice.findMany({ where: { userId: c.id }, select: { number: true, status: true, amountCents: true, refundedCents: true, createdAt: true, paidAt: true } }),
    db.abuseAlert.count({ where: { userId: c.id, status: "OPEN" } }),
    db.serverArchive.findMany({ where: { userId: c.id }, select: { provisionedAt: true, deletedAt: true } }),
    db.auditLog.count({
      where: {
        action: { contains: "fraud" },
        OR: [{ detail: { contains: c.email } }, { detail: { contains: c.id } }, { target: c.id }],
      },
    }),
  ]);

  const ips = [...new Set([...visits.map((v) => v.ip), ...sessions.map((s) => s.ip)].filter((x): x is string => !!x))].slice(0, 60);
  const visitorIds = [...new Set(visits.map((v) => v.visitorId).filter((x): x is string => !!x))].slice(0, 30);
  const countries = new Set<string>();
  for (const v of visits) {
    const cc = v.country ?? geoLocateIp(v.ip)?.country ?? null;
    if (cc && cc.length === 2) countries.add(cc.toUpperCase());
  }

  const [ipRows, browserRows, aliasRows] = await Promise.all([
    ips.length
      ? db.visit.groupBy({ by: ["userId", "ip"], where: { ip: { in: ips }, userId: { not: null, notIn: [c.id] }, isBot: false } })
      : Promise.resolve([] as { userId: string | null; ip: string }[]),
    visitorIds.length
      ? db.visit.findMany({ where: { visitorId: { in: visitorIds }, userId: { not: null, notIn: [c.id] } }, select: { userId: true }, distinct: ["userId"], take: 20 })
      : Promise.resolve([] as { userId: string | null }[]),
    db.$queryRaw<{ id: string; email: string }[]>(Prisma.sql`
      SELECT id, email FROM "User"
      WHERE id <> ${c.id}
        AND split_part(lower(email), '@', 2) = ${c.email.toLowerCase().split("@")[1] ?? ""}
        AND (CASE WHEN split_part(lower(email), '@', 2) IN ('gmail.com', 'googlemail.com')
                  THEN replace(split_part(split_part(lower(email), '@', 1), '+', 1), '.', '')
                  ELSE split_part(split_part(lower(email), '@', 1), '+', 1) END)
            = ${emailFamilyKey(c.email).split("@")[0]}
      LIMIT 20`),
  ]);

  const otherIds = [...new Set([...ipRows.map((r) => r.userId), ...browserRows.map((r) => r.userId)].filter((x): x is string => !!x))];
  const others = otherIds.length ? await db.user.findMany({ where: { id: { in: otherIds } }, select: { id: true, email: true } }) : [];
  const emailOf = new Map(others.map((o) => [o.id, o.email]));
  const ipCount = new Map<string, number>();
  for (const r of ipRows) if (r.userId) ipCount.set(r.userId, (ipCount.get(r.userId) ?? 0) + 1);

  const numbers = invoices.map((i) => i.number);
  const chargebacks = numbers.length
    ? await db.auditLog.count({ where: { action: "partner.chargeback", OR: numbers.slice(0, 200).map((n) => ({ detail: { startsWith: `invoice #${n}:` } })) } })
    : 0;
  const paid = invoices.filter((i) => i.status === "PAID" || i.status === "REFUNDED");
  const firstPaid = paid.map((i) => i.paidAt ?? i.createdAt).sort((a, b) => a.getTime() - b.getTime())[0] ?? null;

  const facts: RiskFacts = {
    accountAgeDays: Math.floor((Date.now() - c.createdAt.getTime()) / DAY),
    emailVerified: !!c.emailVerifiedAt,
    totpEnabled: c.totpEnabled,
    suspended: c.suspended,
    billingCountry: c.billingCountry,
    seenCountries: [...countries],
    sharedIpAccounts: [...ipCount.entries()].map(([id, n]) => ({ id, email: emailOf.get(id) ?? id, sharedIps: n })),
    sharedBrowserAccounts: browserRows.filter((r) => r.userId).map((r) => ({ id: r.userId!, email: emailOf.get(r.userId!) ?? r.userId! })),
    aliasAccounts: aliasRows,
    cards: cards.map((k) => ({ createdAt: k.createdAt, unusable: !!k.unusableAt })),
    paidInvoiceCents: paid.reduce((n, i) => n + i.amountCents, 0),
    refundedInvoices: invoices.filter((i) => i.refundedCents > 0).length,
    refundedCents: invoices.reduce((n, i) => n + i.refundedCents, 0),
    chargebacks,
    openAbuseAlerts: abuse,
    priorFraudActions: fraudAudits,
    shortLivedServers: archives.filter((a) => a.deletedAt.getTime() - a.provisionedAt.getTime() < 2 * DAY).length,
    minutesToFirstPurchase: firstPaid ? (firstPaid.getTime() - c.createdAt.getTime()) / 60_000 : null,
  };
  return { report: evaluateRisk(facts), facts };
});

