"use client";

import { useState } from "react";
import { ActionPanel } from "@/components/admin/server360/ActionPanel";
import {
  adminResetTwoFactor,
  adminResendVerification,
  adminPasswordResetLink,
  adminRevokeSessions,
  adminAddCustomerFlag,
  adminClearCustomerFlag,
  adminPreviewMerge,
  adminDeleteAccount,
  type MergePreview,
} from "@/lib/actions-admin-client";
import { FLAG_KINDS, FLAG_LABELS, type FlagKind } from "@/lib/admin-client/risk";

export function AddFlagControl({ userId, existing }: { userId: string; existing: string[] }) {
  const options = FLAG_KINDS.filter((k) => !existing.includes(k));
  const [kind, setKind] = useState<FlagKind>(options[0] ?? "manual_review");
  const [note, setNote] = useState("");
  if (options.length === 0) return null;
  return (
    <ActionPanel
      label="Add flag…"
      title="Flag this customer"
      small
      needsReason={false}
      description="Flags show on the customer's header and in the fleet list owner column for every admin."
      run={() => adminAddCustomerFlag(userId, kind, note)}
    >
      <div className="flex flex-wrap gap-2">
        <select className="input py-1.5 text-sm" value={kind} onChange={(e) => setKind(e.target.value as FlagKind)} aria-label="Flag">
          {options.map((k) => (
            <option key={k} value={k}>
              {FLAG_LABELS[k]}
            </option>
          ))}
        </select>
