      run={(reason) => adminPasswordResetLink(userId, reason)}
      successText="Reset link sent."
    />
  );
}

export function RevokeSessionsControl({ userId }: { userId: string }) {
  return (
    <ActionPanel
      label="Sign out everywhere…"
      tone="danger"
      description="Ends every session on every device (suspected account takeover)."
      run={async (reason) => {
        const r = await adminRevokeSessions(userId, reason);
        return r.ok ? { ok: true, message: `${r.revoked} session(s) ended.` } : r;
      }}
    />
  );
}

export function MergePreviewControl({ userId }: { userId: string }) {
  const [email, setEmail] = useState("");
  const [preview, setPreview] = useState<MergePreview | null>(null);
  return (
    <div className="space-y-2">
      <ActionPanel
        label="Preview merge…"
        title="Merge into another account (preview)"
        needsReason={false}
        description="Shows everything that would have to move. Automatic merge is not built — nothing is changed."
        canSubmit={/@/.test(email)}
        run={async () => {
          const r = await adminPreviewMerge(userId, email);
          if (r.ok) setPreview(r.preview);
          return r.ok ? { ok: true, message: "Preview below." } : r;
        }}
      >
        <input className="input w-full py-1.5 text-sm" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="target account email" type="email" />
