export function DeleteAccountControl({ userId, email }: { userId: string; email: string }) {
  const [word, setWord] = useState("");
  return (
    <ActionPanel
      label="Delete account…"
      title={`Permanently delete ${email}`}
      tone="danger"
      confirmText={email}
      confirmHint="Type the email"
      canSubmit={word.trim() === "DELETE"}
      description="Refused while the account owns anything (servers, hosting, email, domains, open invoices, non-zero wallet). Invoices, notes and tickets are deleted with the account; the audit trail is kept but detached. There is no undo."
      run={(reason, typed, idem) => adminDeleteAccount(userId, typed, word, reason, idem)}
    >
      <label className="block">
        <span className="mb-1 block text-xs text-slate-400">
          Type <code className="font-mono">DELETE</code>
        </span>
        <input className="input w-full py-1.5 font-mono text-xs" value={word} onChange={(e) => setWord(e.target.value)} autoComplete="off" />
      </label>
    </ActionPanel>
  );
}

