import Link from "next/link";
import { db } from "@/lib/db";
import { Badge, timeAgo } from "@/components/ui/primitives";
import { CustomerNotes } from "@/components/admin/CustomerNotes";
import { geoLocateIp } from "@/lib/geo-ip";
import { heardLabel } from "@/lib/heard-about";
import { FLAG_LABELS } from "@/lib/admin-client/risk";
import { Card, Empty, Field, Fields } from "@/components/admin/server360/ui";
import { AddFlagControl, ClearFlagControl } from "../controls";
import { type ClientCore, clientFlags, loadRisk } from "../core";

export async function ProfileTab({ user, canAct }: { user: ClientCore; canAct: boolean }) {
  const [{ report, facts }, visits, lastLogin, orgs] = await Promise.all([
    loadRisk(user),
    db.visit.findMany({ where: { userId: user.id }, orderBy: { createdAt: "desc" }, take: 60, select: { ip: true, country: true, city: true, createdAt: true } }),
    db.auditLog.findFirst({ where: { userId: user.id, action: "user.login" }, orderBy: { createdAt: "desc" }, select: { createdAt: true } }),
    Promise.all([
      db.org.findMany({ where: { ownerId: user.id }, include: { _count: { select: { members: true } } } }).catch(() => []),
      db.orgMember.findMany({ where: { userId: user.id }, include: { org: { select: { id: true, name: true } } } }).catch(() => []),
    ]),
  ]);
  const geocoded = visits.find((v) => v.city || v.country);
  let location: string | null = geocoded ? [geocoded.city, geocoded.country].filter(Boolean).join(", ") : null;
  if (!location) {
    const g = geoLocateIp(visits[0]?.ip);
    if (g) location = [g.city, g.country].filter(Boolean).join(", ") || null;
  }
  const flags = clientFlags(user);
  const plainNotes = user.customerNotes.filter((n) => !flags.some((f) => f.note.id === n.id));
  const [owned, member] = orgs;

  return (
    <div className="space-y-4">
      <div className="grid gap-4 xl:grid-cols-3">
        <Card title="Client info" className="xl:col-span-2">
          <Fields cols={3}>
            <Field label="Joined">{user.createdAt.toISOString().slice(0, 10)} <span className="text-xs text-slate-500">({facts.accountAgeDays} d)</span></Field>
            <Field label="Last login">{lastLogin ? timeAgo(lastLogin.createdAt) : "—"}</Field>
            <Field label="Location">{location ?? "unknown"}</Field>
            <Field label="Billing country">{user.billingCountry ?? "—"}{user.vatId ? ` · VAT ${user.vatId}` : ""}</Field>
            <Field label="Heard about us">{heardLabel(user.heardAboutUs, { withOtherText: true })}</Field>
            <Field label="Email verified">{user.emailVerifiedAt ? <Badge tone="green">yes</Badge> : <Badge tone="amber">no</Badge>}</Field>
            <Field label="2FA">{user.totpEnabled ? <Badge tone="green">on</Badge> : <Badge tone="slate">off</Badge>}</Field>
            <Field label="SSH keys / API tokens">{user._count.sshKeys} / {user._count.apiTokens}</Field>
            <Field label="Notifications sent">{user._count.notifications}</Field>
            <Field label="Revenue reporting">{user.excludeFromRevenue ? "excluded" : "included"}</Field>
            <Field label="Google / Discord">{user.googleId ? "Google linked" : "—"}{(user as { discordUserId?: string | null }).discordUserId ? " · Discord linked" : ""}</Field>
            <Field label="Stripe customer" mono>{user.stripeCustomerId ?? "—"}</Field>
          </Fields>
          {(owned.length > 0 || member.length > 0) && (
            <div className="mt-4 border-t border-white/[0.06] pt-3 text-sm">
              <p className="mb-1 text-xs text-slate-500">Teams</p>
              {owned.map((o) => (
                <p key={o.id} className="text-xs">{o.name} <span className="text-slate-500">· owner · {o._count.members} member{o._count.members === 1 ? "" : "s"}</span></p>
              ))}
              {member.map((m) => (
                <p key={m.id} className="text-xs">{m.org.name} <span className="text-slate-500">· {m.role.toLowerCase()}</span></p>
              ))}
            </div>
          )}
        </Card>

        <Card
          title="Flags"
          sub="Structured flags (stored as tagged notes). Visible to every admin."
          action={canAct ? <AddFlagControl userId={user.id} existing={flags.map((f) => f.flag.kind)} /> : undefined}
        >
          {flags.length === 0 ? (
            <Empty>No flags.</Empty>
          ) : (
            <ul className="space-y-2 text-sm">
              {flags.map(({ flag, note }) => (
                <li key={note.id} className="flex flex-wrap items-start justify-between gap-2">
                  <span>
                    <Badge tone={flag.kind === "vip" ? "green" : "amber"}>{FLAG_LABELS[flag.kind]}</Badge>
                    {flag.note && <span className="ml-2 text-xs text-slate-400">{flag.note}</span>}
                    <span className="block text-[11px] text-slate-500">{note.author?.email ?? "?"} · {timeAgo(note.createdAt)}</span>
                  </span>
                  {canAct && <ClearFlagControl userId={user.id} noteId={note.id} label={FLAG_LABELS[flag.kind]} />}
                </li>
              ))}
            </ul>
          )}
        </Card>
      </div>

      <Card
        title={`Risk signals — ${report.level}`}
        sub="Built only from data on this account (cards, invoices, sign-ins, sessions, linked accounts, audit log). The level is the combined weight of the signals, not a fraud probability."
      >
        {report.signals.length === 0 ? (
          <Empty>No signals.</Empty>
        ) : (
          <ul className="space-y-2">
            {report.signals.map((s) => (
              <li key={s.key} className="flex flex-wrap items-start gap-3 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2 text-sm">
                <span className="adm-pill" data-tone={s.severity === "high" ? "red" : s.severity === "medium" ? "amber" : s.severity === "low" ? "blue" : undefined}>{s.severity}</span>
                <span className="min-w-0 flex-1">
                  <span className="font-medium">{s.title}</span>
                  <span className="block text-xs text-slate-400">{s.detail}</span>
                </span>
              </li>
            ))}
          </ul>
        )}
        {(facts.sharedIpAccounts.length > 0 || facts.sharedBrowserAccounts.length > 0 || facts.aliasAccounts.length > 0) && (
          <div className="mt-4 grid gap-3 border-t border-white/[0.06] pt-3 text-xs sm:grid-cols-3">
            {[
              ["Alias accounts", facts.aliasAccounts.map((a) => ({ id: a.id, email: a.email, extra: "" }))],
              ["Same browser", facts.sharedBrowserAccounts.map((a) => ({ id: a.id, email: a.email, extra: "" }))],
              ["Shared IPs", facts.sharedIpAccounts.map((a) => ({ id: a.id, email: a.email, extra: `${a.sharedIps} IP${a.sharedIps === 1 ? "" : "s"}` }))],
            ].map(([label, list]) => (
              <div key={label as string}>
                <p className="mb-1 text-slate-500">{label as string}</p>
                {(list as { id: string; email: string; extra: string }[]).length === 0 ? (
                  <p className="text-slate-600">none</p>
                ) : (
                  <ul className="space-y-0.5">
                    {(list as { id: string; email: string; extra: string }[]).slice(0, 8).map((a) => (
                      <li key={a.id}>
                        <Link href={`/admin/users/${a.id}`} className="hover:text-brand-300">{a.email}</Link> <span className="text-slate-500">{a.extra}</span>
                      </li>
                    ))}
                  </ul>
                )}
              </div>
            ))}
          </div>
        )}
      </Card>

      <CustomerNotes userId={user.id} notes={plainNotes} canEdit={canAct} />
    </div>
  );
}

