import Link from "next/link";
import { db } from "@/lib/db";
import { Badge, StatusDot, fmtMoney } from "@/components/ui/primitives";
import { SuspendServerButton } from "@/components/AdminControls";
import { RebootServerButton } from "@/components/admin/ServerAdminActions";
import { currentRenewalPrices } from "@/lib/admin-metrics";
import { serverFleetPriceCents } from "@/lib/admin-fleet";
import { dbOnlyHealth } from "@/lib/admin-server/state-truth";
import { REGION_LABELS } from "@/lib/node-regions";
import { Card, Empty } from "@/components/admin/server360/ui";
import type { ClientCore } from "../core";

export async function ServersTab({ user, canAct }: { user: ClientCore; canAct: boolean }) {
  const [servers, hosting, email, domains, prices, archived] = await Promise.all([
    db.server.findMany({
      where: { userId: user.id },
      orderBy: { createdAt: "desc" },
      include: {
        plan: true,
        gamePlan: { select: { name: true, priceCents: true, termMonths: true, gameFamily: true } },
        dedicatedIp: { select: { id: true, address: true } },
        node: { select: { name: true, region: true, publicIp: true } },
        gameRuntime: { select: { state: true, probedAt: true, intent: true, probeError: true } },
        jobs: { where: { status: { in: ["QUEUED", "RUNNING"] } }, take: 1, select: { type: true, status: true, updatedAt: true } },
      },
    }),
    db.hostingAccount.findMany({ where: { userId: user.id }, include: { plan: { select: { name: true, priceCents: true } }, node: { select: { name: true } } }, orderBy: { createdAt: "desc" } }),
    db.emailSubscription.findMany({ where: { userId: user.id }, include: { emailPlan: { select: { name: true, priceCents: true, termMonths: true } }, _count: { select: { mailboxes: true } } }, orderBy: { createdAt: "desc" } }),
    db.domain.findMany({ where: { userId: user.id }, orderBy: { createdAt: "desc" } }),
    currentRenewalPrices(),
    db.serverArchive.findMany({ where: { userId: user.id }, orderBy: { deletedAt: "desc" }, take: 20 }),
  ]);
  const now = new Date();

  return (
    <div className="space-y-4">
      <Card title={`Servers (${servers.length})`} action={<Link href={`/admin/servers?owner=${user.id}`} className="btn-ghost py-1 text-xs">Fleet list →</Link>}>
        {servers.length === 0 ? (
          <Empty>No servers.</Empty>
        ) : (
          <ul className="grid gap-3 md:grid-cols-2 2xl:grid-cols-3">
            {servers.map((s) => {
              const h = dbOnlyHealth({
                dbStatus: s.status,
                provisionError: s.provisionError,
                suspendReason: s.suspendReason,
                isGame: !!s.gamePlan,
                runtime: s.gameRuntime ? { state: s.gameRuntime.state, probedAt: s.gameRuntime.probedAt, intent: s.gameRuntime.intent, probeError: s.gameRuntime.probeError } : null,
                activeJob: s.jobs[0] ?? null,
                updatedAt: s.updatedAt,
                now,
              });
              const issue = h.mismatches.find((m) => m.severity !== "info");
              return (
                <li key={s.id} className="rounded-xl border border-white/[0.07] bg-white/[0.02] p-3">
                  <div className="flex items-start justify-between gap-2">
                    <div className="min-w-0">
                      <Link href={`/admin/servers/${s.id}`} className="block truncate font-medium hover:text-brand-300">{s.label || s.hostname}</Link>
                      <p className="truncate text-xs text-slate-500">
                        {s.gamePlan ? s.gamePlan.name : s.plan.name} · {s.node ? `${s.node.name} (${REGION_LABELS[s.node.region] ?? s.node.region})` : "no node"}
                      </p>
                    </div>
                    <StatusDot status={s.status} />
                  </div>
                  <div className="mt-2 flex flex-wrap gap-1">
                    {s.isFree && <Badge tone="green">free</Badge>}
                    {s.dedicatedIp && <Badge tone={s.wantsDedicatedIp ? "brand" : "amber"}>{s.wantsDedicatedIp ? "IPv4" : "IPv4 (free perk)"}</Badge>}
                    {s.backupTier === "PLUS" && <Badge tone="brand">Backup Plus</Badge>}
                    {s.extraDiskGB > 0 && <Badge tone="brand">+{s.extraDiskGB} GB</Badge>}
                    {s.grandfatheredRenewalCents != null && <Badge tone="slate">locked price</Badge>}
                  </div>
                  <dl className="mt-2 grid grid-cols-2 gap-1 text-xs">
                    <dt className="text-slate-500">Renews</dt>
                    <dd>{s.isFree ? "never" : s.expiresAt ? s.expiresAt.toISOString().slice(0, 10) : "—"}</dd>
                    <dt className="text-slate-500">Price</dt>
                    <dd>{s.isFree ? "free" : `${fmtMoney(serverFleetPriceCents(s, prices))}/mo`}</dd>
                    <dt className="text-slate-500">Endpoint</dt>
                    <dd className="truncate font-mono">{s.dedicatedIp?.address ?? (s.sshPort ? `${s.node?.publicIp ?? "—"}:${s.sshPort}` : "—")}</dd>
                  </dl>
                  {issue && <p className={`mt-2 text-xs ${issue.severity === "critical" ? "text-red-300" : "text-amber-300"}`}>⚠ {issue.message}</p>}
                  {s.jobs[0] && <p className="mt-1 text-xs text-sky-300">{s.jobs[0].type.toLowerCase().replace(/_/g, " ")} · {s.jobs[0].status.toLowerCase()}</p>}
                  {canAct && s.status !== "DELETING" && (
                    <div className="mt-3 flex flex-wrap items-center gap-2 border-t border-white/[0.05] pt-2">
                      <RebootServerButton serverId={s.id} status={s.status} />
                      <SuspendServerButton serverId={s.id} suspended={s.status === "SUSPENDED"} />
                      <Link href={`/admin/servers/${s.id}?tab=billing`} className="btn-ghost py-1 text-xs">Billing</Link>
                    </div>
                  )}
                </li>
              );
            })}
          </ul>
        )}
      </Card>

      <div className="grid gap-4 xl:grid-cols-2">
        <Card title={`Web hosting (${hosting.length})`} action={<Link href="/admin/hosting" className="btn-ghost py-1 text-xs">Manage →</Link>}>
          {hosting.length === 0 ? (
            <Empty>No hosting accounts.</Empty>
          ) : (
            <ul className="space-y-1.5 text-sm">
              {hosting.map((h) => (
                <li key={h.id} className="flex flex-wrap items-center justify-between gap-2">
                  <span>{h.primaryDomain} <span className="font-mono text-xs text-slate-500">{h.username}</span></span>
                  <span className="text-xs text-slate-400">{h.plan.name} · {fmtMoney(h.plan.priceCents)}/mo · {h.node.name}</span>
                  {h.sslActive ? <Badge tone="green">ssl</Badge> : <Badge tone="slate">no ssl</Badge>}
                  <StatusDot status={h.status} />
                  <span className="text-xs text-slate-500">{h.expiresAt ? h.expiresAt.toISOString().slice(0, 10) : "—"}</span>
                </li>
              ))}
            </ul>
          )}
        </Card>
        <Card title={`Business email (${email.length})`} action={<Link href="/admin/mailboxes" className="btn-ghost py-1 text-xs">Manage →</Link>}>
          {email.length === 0 ? (
            <Empty>No email subscriptions.</Empty>
          ) : (
            <ul className="space-y-1.5 text-sm">
              {email.map((e) => (
                <li key={e.id} className="flex flex-wrap items-center justify-between gap-2">
                  <span>{e.domainName}</span>
                  <span className="text-xs text-slate-400">{e.emailPlan.name} · {fmtMoney(e.emailPlan.priceCents)}/{e.emailPlan.termMonths === 1 ? "mo" : `${e.emailPlan.termMonths}mo`} · {e._count.mailboxes} mailbox{e._count.mailboxes === 1 ? "" : "es"}</span>
                  {e.verified ? <Badge tone="green">verified</Badge> : <Badge tone="amber">unverified</Badge>}
                  <StatusDot status={e.status} />
                  <span className="text-xs text-slate-500">{e.expiresAt ? e.expiresAt.toISOString().slice(0, 10) : "—"}</span>
                </li>
              ))}
            </ul>
          )}
        </Card>
        <Card title={`Domains (${domains.length})`}>
          {domains.length === 0 ? (
            <Empty>No domains.</Empty>
          ) : (
            <ul className="space-y-1.5 text-sm">
              {domains.map((d) => (
                <li key={d.id} className="flex flex-wrap items-center justify-between gap-2">
                  <span className="font-medium">{d.name}</span>
                  <Badge tone={d.status === "ACTIVE" ? "green" : d.status === "FAILED" ? "red" : "amber"}>{d.status.toLowerCase()}</Badge>
                  <span className="text-xs text-slate-500">{d.expiresAt ? d.expiresAt.toISOString().slice(0, 10) : "—"}</span>
                </li>
              ))}
            </ul>
          )}
        </Card>
        <Card title={`Past servers (${archived.length})`} sub="Deleted, expired or cancelled — from the server archive.">
          {archived.length === 0 ? (
            <Empty>None.</Empty>
          ) : (
            <ul className="space-y-1 text-xs">
              {archived.map((a) => (
                <li key={a.id} className="flex flex-wrap justify-between gap-2">
                  <span className="font-mono">{a.hostname}</span>
                  <span className="text-slate-400">{a.serviceName} · {a.reason.toLowerCase()} {a.deletedAt.toISOString().slice(0, 10)}{a.totalSpentCents ? ` · ${fmtMoney(a.totalSpentCents)}` : ""}</span>
                </li>
