        <Card title="Wallet">
          <p className="text-2xl font-semibold">{fmtMoney(user.balanceCents)}</p>
          <p className="mt-1 text-xs text-slate-400">
            Last {ledger.length} entries: +{fmtMoney(credits)} / −{fmtMoney(debits)}. {openInv.length ? `${openInv.length} open invoice(s), ${fmtMoney(openInv.reduce((n, i) => n + i.amountCents, 0))}.` : "No open invoices."}
          </p>
          <Fields cols={2}>
            <Field label="Auto-recharge">{user.autoRechargeEnabled ? `on · ${fmtMoney(user.autoRechargeAmountCents ?? 0)} below ${fmtMoney(user.autoRechargeThresholdCents ?? 0)}` : "off"}</Field>
            <Field label="Spend cap">{user.spendCapEnabled ? fmtMoney(user.hardCapCents ?? 0) : "off"}</Field>
          </Fields>
          {canAct && <div className="mt-3"><CreditForm userId={user.id} /></div>}
        </Card>

        <Card title="Cards & payment methods" className="xl:col-span-2" action={canBill ? <SendReaddEmailButton userId={user.id} email={user.email} /> : undefined}>
          {cards.length === 0 ? (
            <p className="text-sm text-slate-400">
              {hasChargeableCard(user)
                ? `Legacy saved card only: ${cardDisplayLabel({ brand: user.cardBrand, last4: user.cardLast4, expMonth: user.cardExpMonth, expYear: user.cardExpYear }) ?? "on file"}`
                : "No saved card."}
            </p>
          ) : (
            <ul className="space-y-1.5 text-sm">
              {cards.map((c) => (
                <li key={c.id} className="flex flex-wrap items-center justify-between gap-2">
                  <span>
                    {cardDisplayLabel({ brand: c.brand, last4: c.last4, expMonth: c.expMonth, expYear: c.expYear }) ?? "card"}
                    {c.isPrimary && <span className="ml-2"><Badge tone="brand">primary</Badge></span>}
                  </span>
                  <span className="text-xs text-slate-500">added {timeAgo(c.createdAt)}</span>
                  {c.unusableAt ? <Badge tone="red">unusable · {c.unusableReason ?? "declined"}</Badge> : <Badge tone="green">ok</Badge>}
                </li>
              ))}
            </ul>
          )}
          <p className="mt-2 text-xs text-slate-500">
            PayPal: {user.paypalPayerEmail ?? "—"} · Stripe customer: <span className="font-mono">{user.stripeCustomerId ?? "—"}</span>
          </p>
        </Card>
      </div>

      <Card title={`Subscriptions (${servers.length} servers)`} sub="Each server renews on its own date; locked = grandfathered renewal price." action={<Link href="/admin/billing/card-health" className="btn-ghost py-1 text-xs">Card health →</Link>}>
        {servers.length === 0 ? (
          <Empty>No active servers.</Empty>
        ) : (
          <div className="overflow-x-auto">
            <table className="table-shell">
              <thead>
                <tr><th>Server</th><th>Renews</th><th>Auto-renew</th><th>Price basis</th><th>Dunning</th><th>Grace until</th></tr>
              </thead>
              <tbody>
                {servers.map((s) => {
                  const live = s.gamePlan ? monthlyCents(s.gamePlan.priceCents, s.gamePlan.termMonths) : s.plan.priceCents;
                  const locked = s.grandfatheredRenewalCents != null ? (s.gamePlan ? monthlyCents(s.grandfatheredRenewalCents, s.gamePlan.termMonths) : s.grandfatheredRenewalCents) : null;
                  return (
                    <tr key={s.id}>
                      <td><Link href={`/admin/servers/${s.id}?tab=billing`} className="hover:text-brand-300">{s.hostname}</Link></td>
                      <td className="text-xs">{s.isFree ? "free" : fmtDate(s.expiresAt)}</td>
                      <td className="text-xs">{s.isFree ? "—" : s.autoRenew ? "on" : "off"}</td>
                      <td className="text-xs">{s.isFree ? "—" : locked != null ? <>{fmtMoney(locked)}/mo <Badge tone="slate">locked</Badge> <span className="text-slate-500">(live {fmtMoney(live)})</span></> : `${fmtMoney(live)}/mo live`}</td>
                      <td className="text-xs">{s.dunningStage || "—"}</td>
                      <td className="text-xs">{fmtDate(s.billingGraceUntil)}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </Card>

      <div className="grid gap-4 xl:grid-cols-2">
        <Card title={`Wallet ledger (latest ${ledger.length})`}>
          {ledger.length === 0 ? (
            <Empty>No transactions.</Empty>
          ) : (
            <ul className="max-h-[28rem] space-y-1 overflow-y-auto pr-1 text-sm">
              {ledger.map((t) => (
                <li key={t.id} className="flex items-baseline justify-between gap-3">
                  <span className="min-w-0 truncate">{t.description}</span>
                  <span className="shrink-0 text-xs text-slate-500">{timeAgo(t.createdAt)}</span>
                  <span className={`shrink-0 font-mono text-xs ${t.amountCents < 0 ? "text-red-400" : "text-emerald-400"}`}>{t.amountCents < 0 ? "−" : "+"}{fmtMoney(Math.abs(t.amountCents))}</span>
                </li>
              ))}
            </ul>
          )}
        </Card>
        <Card title={`Invoices (${user._count.invoices})`} action={<Link href="/admin/invoices" className="btn-ghost py-1 text-xs">All →</Link>}>
          {invoices.length === 0 ? (
            <Empty>No invoices.</Empty>
          ) : (
            <ul className="max-h-[28rem] space-y-1 overflow-y-auto pr-1 text-sm">
              {invoices.map((i) => (
                <li key={i.id} className="flex flex-wrap items-center justify-between gap-2">
                  <Link href={`/admin/invoices/${i.id}`} className="font-mono text-xs hover:text-brand-300">#{i.number}</Link>
                  <span className="min-w-0 flex-1 truncate text-xs text-slate-400">{i.description}</span>
                  <Badge tone={i.status === "PAID" ? "green" : i.status === "OPEN" ? "amber" : i.status === "REFUNDED" ? "brand" : "slate"}>{i.status.toLowerCase()}</Badge>
                  <span className="font-mono text-xs">{fmtMoney(i.amountCents)}{i.refundedCents ? ` (−${fmtMoney(i.refundedCents)})` : ""}</span>
                </li>
              ))}
            </ul>
          )}
        </Card>
      </div>

      <div className="grid gap-4 xl:grid-cols-2">
        {canBill ? (
          <Card title="Refunds & credits" sub="Refund a real payment (with reason, audited) or adjust the wallet.">
            <RefundControls userId={user.id} />
          </Card>
        ) : (
          <Card title="Refunds & credits"><Empty>Requires the billing area.</Empty></Card>
        )}
        <Card title="Money actions on this account" sub="Credits, refunds and balance changes recorded in the audit log.">
          {refundAudits.length === 0 ? (
            <Empty>None recorded.</Empty>
          ) : (
            <ul className="space-y-1 text-xs">
              {refundAudits.map((a) => (
                <li key={a.id}>
                  <span className="font-mono">{a.action}</span> <span className="text-slate-500">· {a.user?.email ?? "system"} · {timeAgo(a.createdAt)}</span>
                  {a.detail && <span className="block text-slate-400">{a.detail}</span>}
                </li>
              ))}
            </ul>
          )}
        </Card>
      </div>
    </div>
  );
}

