import Link from "next/link";
import { db } from "@/lib/db";
import { Badge, StatusDot, timeAgo } from "@/components/ui/primitives";
import { EmailLogViewer, type EmailLogRow } from "@/components/admin/EmailLogViewer";
import { Card, Empty } from "@/components/admin/server360/ui";
import type { ClientCore } from "../core";

export async function SupportTab({ user }: { user: ClientCore }) {
  const [tickets, dms, chats, emails] = await Promise.all([
    db.ticket.findMany({ where: { userId: user.id }, orderBy: { updatedAt: "desc" }, take: 50, include: { _count: { select: { messages: true } } } }),
    db.staffDm.findMany({ where: { userId: user.id }, orderBy: { updatedAt: "desc" }, select: { id: true, subject: true, status: true, unreadForStaff: true, updatedAt: true } }),
    db.chatConversation.findMany({ where: { userId: user.id }, orderBy: { lastMessageAt: "desc" }, take: 20, select: { id: true, status: true, lastMessageAt: true, unreadForAgent: true, botEscalatedAt: true, _count: { select: { messages: true } } } }),
    db.emailLog.findMany({ where: { OR: [{ userId: user.id }, { toEmail: { equals: user.email, mode: "insensitive" } }] }, orderBy: { createdAt: "desc" }, take: 50 }),
  ]);
  const emailRows: EmailLogRow[] = emails.map((e) => ({
    id: e.id,
    toEmail: e.toEmail,
    subject: e.subject,
    template: e.template,
    status: e.status,
    error: e.error,
    html: e.html,
    createdAt: e.createdAt.toISOString(),
    openedAt: e.openedAt?.toISOString() ?? null,
    openCount: e.openCount,
    clickedAt: e.clickedAt?.toISOString() ?? null,
    clickCount: e.clickCount,
  }));
  const opened = emails.filter((e) => e.openedAt).length;

  return (
    <div className="space-y-4">
      <div className="grid gap-4 xl:grid-cols-2">
        <Card title={`Tickets (${tickets.length})`} action={<Link href="/admin/support" className="btn-ghost py-1 text-xs">Desk →</Link>}>
          {tickets.length === 0 ? (
            <Empty>No tickets.</Empty>
          ) : (
            <ul className="space-y-1.5 text-sm">
              {tickets.map((t) => (
                <li key={t.id} className="flex flex-wrap items-center justify-between gap-2">
                  <Link href={`/admin/support/${t.id}`} className="min-w-0 flex-1 truncate font-medium hover:text-brand-300">{t.subject}</Link>
                  <Badge tone={t.priority === "URGENT" ? "red" : t.priority === "HIGH" ? "amber" : t.priority === "NORMAL" ? "brand" : "slate"}>{t.priority.toLowerCase()}</Badge>
                  <StatusDot status={t.status} />
                  <span className="text-xs text-slate-500">{t._count.messages} msg · {timeAgo(t.updatedAt)}</span>
                </li>
              ))}
            </ul>
          )}
        </Card>

        <Card title={`Direct messages (${dms.length})`} sub="Staff-initiated threads (separate from tickets).">
          {dms.length === 0 ? (
            <Empty>No direct messages yet.</Empty>
          ) : (
            <ul className="space-y-1.5 text-sm">
              {dms.map((d) => (
                <li key={d.id} className="flex flex-wrap items-center justify-between gap-2">
                  <Link href={`/admin/dms/${d.id}`} className="min-w-0 flex-1 truncate font-medium hover:text-brand-300">{d.subject}</Link>
                  {d.unreadForStaff && <Badge tone="amber">reply waiting</Badge>}
                  <StatusDot status={d.status} />
                  <span className="text-xs text-slate-500">{timeAgo(d.updatedAt)}</span>
                </li>
              ))}
            </ul>
          )}
        </Card>

        <Card title={`Live chats (${chats.length})`} action={<Link href="/admin/chat" className="btn-ghost py-1 text-xs">Chat desk →</Link>}>
          {chats.length === 0 ? (
            <Empty>No chats while signed in.</Empty>
          ) : (
            <ul className="space-y-1.5 text-sm">
              {chats.map((c) => (
                <li key={c.id} className="flex flex-wrap items-center justify-between gap-2">
                  <Link href={`/admin/chat?c=${c.id}`} className="font-mono text-xs hover:text-brand-300">{c.id.slice(-8)}</Link>
                  <span className="text-xs text-slate-400">{c._count.messages} messages{c.botEscalatedAt ? " · escalated" : ""}</span>
                  {c.unreadForAgent && <Badge tone="amber">unread</Badge>}
                  <StatusDot status={c.status} />
                  <span className="text-xs text-slate-500">{timeAgo(c.lastMessageAt)}</span>
                </li>
              ))}
            </ul>
          )}
        </Card>

        <Card title="Email engagement" sub="From the email log (opens are pixel-based and undercount).">
          <p className="text-sm">
            {emails.length} email{emails.length === 1 ? "" : "s"} logged · {opened} opened · {emails.filter((e) => e.clickedAt).length} clicked · {emails.filter((e) => e.status === "FAILED").length} failed
          </p>
        </Card>
      </div>

      <Card title={`Emails sent (${emails.length})`}>
        {emailRows.length === 0 ? <Empty>No emails logged to this customer.</Empty> : <EmailLogViewer logs={emailRows} />}
      </Card>
    </div>
  );
}

