import { db } from "@/lib/db";
import { Badge, timeAgo } from "@/components/ui/primitives";
import { actingAdminId, detailWithoutActor } from "@/lib/admin-metrics";
import { geoLocateIp } from "@/lib/geo-ip";
import { Card, Empty, Field, Fields, fmtDateTime } from "@/components/admin/server360/ui";
import type { ClientCore } from "../core";

export async function SecurityTab({ user }: { user: ClientCore }) {
  const [logins, sessions, visits, ownAudit, staffAudit, tokens, keys] = await Promise.all([
    db.auditLog.findMany({ where: { userId: user.id, action: { in: ["user.login", "user.login_failed", "user.password_reset_complete", "user.2fa_enabled", "user.2fa_disabled", "user.2fa_backup_code_used"] } }, orderBy: { createdAt: "desc" }, take: 30, select: { id: true, action: true, ip: true, detail: true, createdAt: true } }),
    db.userSession.findMany({ where: { userId: user.id }, orderBy: { lastSeenAt: "desc" }, take: 30 }),
    db.visit.findMany({ where: { userId: user.id }, orderBy: { createdAt: "desc" }, take: 120, select: { ip: true, country: true, city: true, path: true, kind: true, createdAt: true, browser: true, os: true } }),
    db.auditLog.findMany({ where: { userId: user.id }, orderBy: { createdAt: "desc" }, take: 40, select: { id: true, action: true, detail: true, ip: true, createdAt: true } }),
    db.auditLog.findMany({ where: { target: user.id, NOT: { userId: user.id } }, orderBy: { createdAt: "desc" }, take: 30, select: { id: true, action: true, detail: true, ip: true, createdAt: true, user: { select: { email: true } } } }),
    db.apiToken.findMany({ where: { userId: user.id }, orderBy: { createdAt: "desc" }, select: { id: true, name: true, prefix: true, scopes: true, lastUsedAt: true, expiresAt: true, revoked: true, createdAt: true } }),
    db.apiKey.findMany({ where: { userId: user.id }, orderBy: { createdAt: "desc" }, select: { id: true, name: true, prefix: true, scope: true, lastUsedAt: true, revokedAt: true, createdAt: true } }).catch(() => []),
  ]);
  const actorIds = [...new Set(ownAudit.map((a) => actingAdminId(a.detail)).filter(Boolean))] as string[];
  const actors = new Map((actorIds.length ? await db.user.findMany({ where: { id: { in: actorIds } }, select: { id: true, email: true } }) : []).map((u) => [u.id, u.email]));

  const ipMap = new Map<string, { country: string | null; city: string | null; lastSeen: Date; hits: number }>();
  for (const v of visits) {
    const cur = ipMap.get(v.ip);
    if (cur) cur.hits++;
    else {
      const geo = v.country || v.city ? { country: v.country, city: v.city } : geoLocateIp(v.ip);
      ipMap.set(v.ip, { country: geo?.country ?? null, city: geo?.city ?? null, lastSeen: v.createdAt, hits: 1 });
    }
  }
  const pages = visits.filter((v) => v.kind === "portal").slice(0, 20);
  const live = sessions.filter((s) => !s.revokedAt);

  return (
    <div className="space-y-4">
      <div className="grid gap-4 xl:grid-cols-3">
        <Card title="Security posture">
          <Fields cols={2}>
            <Field label="2FA">{user.totpEnabled ? <Badge tone="green">on</Badge> : <Badge tone="slate">off</Badge>}</Field>
            <Field label="Backup codes left">{user.totpEnabled ? user.backupCodes.length : "—"}</Field>
            <Field label="Email verified">{user.emailVerifiedAt ? fmtDateTime(user.emailVerifiedAt) : <Badge tone="amber">no</Badge>}</Field>
            <Field label="Session version" hint="bumps sign out every older session">{user.sessionVersion}</Field>
            <Field label="Live sessions">{live.length}</Field>
            <Field label="Account">{user.suspended ? <Badge tone="red">suspended</Badge> : "active"}</Field>
          </Fields>
          <p className="mt-3 text-xs text-slate-500">Reset 2FA, sign out everywhere and password reset are on the Actions tab.</p>
        </Card>

        <Card title={`Sessions (${sessions.length})`} className="xl:col-span-2">
          {sessions.length === 0 ? (
            <Empty>No sessions recorded.</Empty>
          ) : (
            <ul className="space-y-1 text-xs">
              {sessions.map((s) => (
                <li key={s.id} className={`flex flex-wrap justify-between gap-2 ${s.revokedAt ? "opacity-50" : ""}`}>
                  <span className="min-w-0 truncate">{s.userAgent ?? "unknown device"}</span>
                  <span className="font-mono text-slate-400">{s.ip ?? "—"}{s.location ? ` · ${s.location}` : ""}</span>
                  <span className="text-slate-500">seen {timeAgo(s.lastSeenAt)}{s.revokedAt ? ` · ended ${timeAgo(s.revokedAt)}` : ""}</span>
                </li>
              ))}
            </ul>
          )}
        </Card>
      </div>

      <div className="grid gap-4 xl:grid-cols-2">
        <Card title="Sign-in & security events">
          {logins.length === 0 ? (
            <Empty>No sign-in events recorded.</Empty>
          ) : (
            <ul className="space-y-1 text-xs">
              {logins.map((l) => (
                <li key={l.id} className="flex flex-wrap justify-between gap-2">
                  <span className="font-mono">{l.action}{l.detail ? ` (${l.detail})` : ""}</span>
                  <span className="text-slate-500">{l.ip ?? "—"} · {fmtDateTime(l.createdAt)}</span>
                </li>
              ))}
            </ul>
          )}
        </Card>
        <Card title={`IP addresses (${ipMap.size})`} sub="From portal + marketing visits while signed in.">
          {ipMap.size === 0 ? (
            <Empty>No recorded visits.</Empty>
          ) : (
            <ul className="space-y-1 text-xs">
              {[...ipMap.entries()].slice(0, 15).map(([ip, m]) => (
                <li key={ip} className="flex flex-wrap justify-between gap-2">
                  <span className="font-mono">{ip}</span>
                  <span className="text-slate-500">{[m.city, m.country].filter(Boolean).join(", ") || "—"} · {m.hits} hit{m.hits === 1 ? "" : "s"} · {timeAgo(m.lastSeen)}</span>
                </li>
              ))}
            </ul>
          )}
        </Card>
      </div>

      <div className="grid gap-4 xl:grid-cols-2">
        <Card title={`API tokens (${tokens.length + keys.length})`}>
          {tokens.length + keys.length === 0 ? (
            <Empty>No API tokens.</Empty>
          ) : (
            <ul className="space-y-1.5 text-sm">
              {tokens.map((t) => (
                <li key={t.id} className={`flex flex-wrap items-center justify-between gap-2 ${t.revoked ? "opacity-50" : ""}`}>
                  <span>{t.name} <span className="font-mono text-xs text-slate-500">{t.prefix}…</span></span>
                  <span className="text-xs text-slate-400">{t.scopes.join(", ") || "all"}</span>
                  <span className="text-xs text-slate-500">{t.revoked ? "revoked" : t.lastUsedAt ? `used ${timeAgo(t.lastUsedAt)}` : "never used"}{t.expiresAt ? ` · expires ${t.expiresAt.toISOString().slice(0, 10)}` : ""}</span>
                </li>
              ))}
              {keys.map((k) => (
                <li key={k.id} className={`flex flex-wrap items-center justify-between gap-2 ${k.revokedAt ? "opacity-50" : ""}`}>
                  <span>{k.name} <span className="font-mono text-xs text-slate-500">{k.prefix}…</span> <Badge tone="slate">key</Badge></span>
                  <span className="text-xs text-slate-400">{k.scope}</span>
                  <span className="text-xs text-slate-500">{k.revokedAt ? "revoked" : k.lastUsedAt ? `used ${timeAgo(k.lastUsedAt)}` : "never used"}</span>
                </li>
              ))}
            </ul>
          )}
        </Card>
        <Card title="Recent portal pages">
          {pages.length === 0 ? (
            <Empty>No portal page views recorded.</Empty>
          ) : (
            <ul className="max-h-64 space-y-1 overflow-y-auto pr-1 text-xs">
              {pages.map((v, i) => (
                <li key={i} className="truncate">{v.path} <span className="text-slate-500">· {[v.browser, v.os].filter(Boolean).join(" / ")} · {timeAgo(v.createdAt)}</span></li>
              ))}
            </ul>
          )}
        </Card>
      </div>

      <div className="grid gap-4 xl:grid-cols-2">
        <Card title="Account activity" sub="Rows recorded against this account (admin actions taken while impersonating are named).">
          {ownAudit.length === 0 ? (
            <Empty>No recorded activity.</Empty>
          ) : (
            <ul className="divide-y divide-white/[0.05] text-sm">
              {ownAudit.map((a) => {
                const as = actingAdminId(a.detail);
                return (
                  <li key={a.id} className="flex flex-wrap items-baseline justify-between gap-2 py-2">
                    <span className="min-w-0">
                      <span className="font-mono text-xs">{a.action}</span>
                      {a.detail && <span className="ml-2 text-xs text-slate-500">{as ? detailWithoutActor(a.detail) : a.detail}</span>}
                      {as && <span className="ml-2"><Badge tone="amber">by {actors.get(as) ?? as}</Badge></span>}
                    </span>
                    <span className="text-xs text-slate-500">{timeAgo(a.createdAt)}</span>
                  </li>
                );
              })}
            </ul>
          )}
        </Card>
        <Card title="Staff actions on this account" sub="Audited admin actions that target this customer.">
          {staffAudit.length === 0 ? (
            <Empty>None recorded.</Empty>
          ) : (
            <ul className="divide-y divide-white/[0.05] text-sm">
              {staffAudit.map((a) => (
                <li key={a.id} className="py-2">
                  <div className="flex flex-wrap justify-between gap-2">
                    <span className="font-mono text-xs">{a.action}</span>
                    <span className="text-xs text-slate-500">{fmtDateTime(a.createdAt)}</span>
                  </div>
                  <p className="text-xs text-slate-400">{a.user?.email ?? "system"}{a.ip ? ` · ${a.ip}` : ""}{a.detail ? ` — ${a.detail}` : ""}</p>
                </li>
              ))}
            </ul>
          )}
        </Card>
      </div>
    </div>
  );
}

