import Link from "next/link";
import { db } from "@/lib/db";
import { Badge, fmtMoney, timeAgo } from "@/components/ui/primitives";
import { computeAffiliateEarnings } from "@/lib/affiliate";
import { Card, Empty, Field, Fields } from "@/components/admin/server360/ui";
import type { ClientCore } from "../core";

export async function PartnerTab({ user }: { user: ClientCore }) {
  const [rel, earnings, commissionSums, payouts] = await Promise.all([
    db.user.findUnique({
      where: { id: user.id },
      select: {
        referredBy: { select: { id: true, email: true } },
        referrals: { select: { id: true, email: true, createdAt: true }, orderBy: { createdAt: "desc" }, take: 50 },
        referralPartner: { select: { id: true, name: true, code: true, status: true, commissionRatePct: true, type: true } },
        partnerAttachment: { select: { attachedAt: true, firstPurchaseDiscountUsedAt: true, partner: { select: { id: true, name: true, code: true } } } },
      },
    }),
    computeAffiliateEarnings(user.id).catch(() => null),
    db.partnerCommission.groupBy({ by: ["status"], where: { customerId: user.id }, _sum: { amountCents: true }, _count: true }).catch(() => []),
    db.affiliatePayout.findMany({ where: { userId: user.id }, orderBy: { createdAt: "desc" }, take: 20 }),
  ]);

  return (
    <div className="space-y-4">
      <div className="grid gap-4 xl:grid-cols-2">
        <Card title="Referral program (customer referrals)">
          <Fields cols={2}>
            <Field label="Referral code" mono>{user.referralCode ?? "—"}</Field>
            <Field label="Referred by">{rel?.referredBy ? <Link href={`/admin/users/${rel.referredBy.id}`} className="hover:text-brand-300">{rel.referredBy.email}</Link> : "—"}</Field>
            <Field label="Signup credit">{user.signupCreditCents ? fmtMoney(user.signupCreditCents) : "—"}</Field>
            <Field label="Referrer rewarded">{user.referralRewardedAt ? timeAgo(user.referralRewardedAt) : "—"}</Field>
            {earnings && (
              <>
                <Field label="Referred / paying">{earnings.referredCount} / {earnings.payingCount}</Field>
                <Field label="Earned (total)">{fmtMoney(earnings.totalEarnedCents)}</Field>
                <Field label="Paid out / pending">{fmtMoney(earnings.paidPayoutCents)} / {fmtMoney(earnings.pendingPayoutCents)}</Field>
                <Field label="Available">{fmtMoney(earnings.availableCents)}</Field>
              </>
            )}
          </Fields>
        </Card>

        <Card title="Creator / partner program" action={<Link href="/admin/partners" className="btn-ghost py-1 text-xs">Partners →</Link>}>
          <Fields cols={2}>
            <Field label="Is a partner">
              {rel?.referralPartner ? (
                <Link href={`/admin/partners/${rel.referralPartner.id}`} className="hover:text-brand-300">
                  {rel.referralPartner.name} · {rel.referralPartner.code} <Badge tone={rel.referralPartner.status === "ACTIVE" ? "green" : "slate"}>{rel.referralPartner.status.toLowerCase()}</Badge>
                </Link>
              ) : (
                "no"
              )}
            </Field>
            <Field label="Attached to partner">
              {rel?.partnerAttachment ? (
                <Link href={`/admin/partners/${rel.partnerAttachment.partner.id}`} className="hover:text-brand-300">
                  {rel.partnerAttachment.partner.name} ({rel.partnerAttachment.partner.code})
                </Link>
              ) : (
                "no"
              )}
            </Field>
            {rel?.partnerAttachment && <Field label="Attached">{timeAgo(rel.partnerAttachment.attachedAt)}{rel.partnerAttachment.firstPurchaseDiscountUsedAt ? " · first-purchase discount used" : ""}</Field>}
            <Field label="Commissions this customer generated">
              {commissionSums.length === 0 ? "—" : commissionSums.map((c) => `${c.status.toLowerCase()} ${fmtMoney(c._sum.amountCents ?? 0)} (${c._count})`).join(" · ")}
            </Field>
          </Fields>
        </Card>
      </div>

      <div className="grid gap-4 xl:grid-cols-2">
        <Card title={`Accounts they referred (${rel?.referrals.length ?? 0})`}>
          {!rel || rel.referrals.length === 0 ? (
            <Empty>None.</Empty>
          ) : (
            <ul className="space-y-1 text-sm">
              {rel.referrals.map((r) => (
                <li key={r.id} className="flex justify-between gap-2">
                  <Link href={`/admin/users/${r.id}`} className="hover:text-brand-300">{r.email}</Link>
                  <span className="text-xs text-slate-500">{timeAgo(r.createdAt)}</span>
                </li>
              ))}
            </ul>
          )}
        </Card>
        <Card title={`Affiliate payouts (${payouts.length})`}>
          {payouts.length === 0 ? (
            <Empty>No payout requests.</Empty>
          ) : (
            <ul className="space-y-1 text-sm">
              {payouts.map((p) => (
                <li key={p.id} className="flex flex-wrap justify-between gap-2">
                  <span className="font-mono text-xs">{fmtMoney(p.amountCents)}</span>
                  <Badge tone={p.status === "PAID" ? "green" : p.status === "DECLINED" ? "red" : "amber"}>{p.status.toLowerCase()}</Badge>
                  <span className="text-xs text-slate-500">{timeAgo(p.createdAt)}{p.note ? ` · ${p.note}` : ""}</span>
                </li>
              ))}
            </ul>
          )}
        </Card>
      </div>
    </div>
  );
}

