import { SuspendUserButton, CreditForm, RevenueExcludeToggle } from "@/components/AdminControls";
import { ImpersonateButton } from "@/components/admin/ImpersonateButton";
import { Card, Empty } from "@/components/admin/server360/ui";
import {
  ResetTwoFactorControl,
  ResendVerificationControl,
  PasswordResetControl,
  RevokeSessionsControl,
  MergePreviewControl,
  DeleteAccountControl,
} from "../controls";
import type { ClientCore } from "../core";

export async function ActionsTab({ user, canAct }: { user: ClientCore; canAct: boolean }) {
  if (!canAct) {
    return (
      <Card title="Actions">
        <Empty>Account actions require an admin account. You can still read every other tab.</Empty>
      </Card>
    );
  }
  const isCustomer = user.role === "CUSTOMER";
  return (
    <div className="space-y-4">
      <div className="grid gap-4 xl:grid-cols-2">
        <Card title="Money" sub="Credits are audited (admin.credit_user). Refunds of real payments are on the Billing tab.">
          <div className="space-y-3">
            <CreditForm userId={user.id} />
            <RevenueExcludeToggle userId={user.id} excluded={user.excludeFromRevenue} />
          </div>
        </Card>
        <Card title="Access" sub="Impersonation is audited and refused for admin accounts; spend actions are blocked while impersonating.">
          <div className="flex flex-wrap items-center gap-3">
            {user.role !== "ADMIN" && <ImpersonateButton userId={user.id} email={user.email} />}
            {user.role !== "ADMIN" && <SuspendUserButton userId={user.id} suspended={user.suspended} />}
          </div>
          <p className="mt-2 text-xs text-slate-500">Suspending signs the customer out and blocks sign-in. Their servers keep running (suspend those individually).</p>
        </Card>
      </div>

      <Card title="Sign-in & security" sub="Each needs a reason; all are audited against this customer.">
        <div className="flex flex-wrap items-start gap-3">
          <PasswordResetControl userId={user.id} />
          <ResendVerificationControl userId={user.id} verified={!!user.emailVerifiedAt} />
          {isCustomer && <RevokeSessionsControl userId={user.id} />}
          {isCustomer && <ResetTwoFactorControl userId={user.id} email={user.email} enabled={user.totpEnabled} />}
        </div>
      </Card>

      {isCustomer && (
        <div className="grid gap-4 xl:grid-cols-2">
          <Card title="Merge accounts" sub="Preview what a merge would move. Executing a merge is not built yet.">
            <MergePreviewControl userId={user.id} />
          </Card>
          <section className="card border-red-500/25" aria-labelledby="delacct">
            <h2 id="delacct" className="mb-1 font-semibold text-red-400">Delete account</h2>
            <p className="mb-3 text-xs text-slate-400">
              Same deletion the customer&apos;s own GDPR request runs, with stricter checks: nothing may still be owned and the wallet must be zero. Typed email + DELETE + reason.
            </p>
            <DeleteAccountControl userId={user.id} email={user.email} />
          </section>
        </div>
      )}
    </div>
  );
}

