import { test } from "node:test";
import assert from "node:assert/strict";
import { serverFleetPriceCents, serverFleetTags, type FleetTagServer } from "../lib/admin-fleet.ts";
import type { PricedServer, RenewalPrices } from "../lib/renewal-charge.ts";
import type { DunningConfig } from "../lib/dunning-config.ts";

/**
 * Guards for the /admin/servers fleet list's Price column and lifecycle tags
 * (lib/admin-fleet.ts). This is the surface built to fix the real live bug the
 * owner found on darkeden-guard-sg: the list showed the bare plan price, with
 * no awareness of add-ons or a per-server grandfathered rate.
 *
 * `serverFleetPriceCents` is a thin wrapper over `renewalCharge` — the same
 * pricing formula worker/billing.ts, the saved-card path and "Renew now" all
 * charge through — so the grandfather-survives-a-price-rise and
 * unaffected-when-unset guarantees are already proven at the `renewalCharge`
 * level in test/money-core-guards.test.ts. What's specific to THIS file is:
 * the fleet list actually calls through to that guarantee, includes add-ons,
 * and (deliberately, unlike MRR's serverMonthlyCents) does not zero out for a
 * suspended row — plus the tag logic, which is new.
  for (const [name, re] of Object.entries(must)) {
    const at = SRC.indexOf(`export async function ${name}(`);
    const next = SRC.indexOf("export async function", at + 10);
    assert.match(SRC.slice(at, next < 0 ? undefined : next), re, `${name} confirmation`);
  }
});

