import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { stripComments } from "./_source-tools.ts";
import { evaluateStateTruth, dbOnlyHealth, type StateTruthInput } from "../lib/admin-server/state-truth.ts";
import { evaluateMoveTargets, fmtDuration, TARGET_RESERVE_MB, type TargetNodeInput } from "../lib/admin-server/move-targets.ts";
import { buildDeleteManifest, deleteWarnings, deleteConfirmMatches, type DeleteManifestInput } from "../lib/admin-server/delete-manifest.ts";
import { parseFleetFilters, fleetFiltersToParams, fleetWhere, fleetHref, csvCell, FLEET_COLUMNS } from "../lib/admin-server/fleet-query.ts";
import { forwardIssues } from "../lib/admin-server/network.ts";
import { resolveServerTab, resolveClientTab, serverTabsFor } from "../lib/admin-server/tabs.ts";
import { moveButtons, vmMoveUiState, ENGINE_PRESENT } from "../lib/admin-server/vm-move-bridge.ts";
import { evaluateRisk, emailFamilyKey, parseFlagNote, flagNoteBody, type RiskFacts } from "../lib/admin-client/risk.ts";

/**
 * The admin server / client 360 redesign (2026-10-01): the pure logic behind
 * the tabs, plus structural tripwires over the two new "use server" modules —
 * every export is a public endpoint, so every one must open with gate()
 * (requireArea + assertNotImpersonating), destructive ones must check a typed
 * confirmation server-side, and every mutation must write an audit row.
 */

const NOW = new Date("2026-10-01T12:00:00Z");
const base: StateTruthInput = {
  dbStatus: "RUNNING",
  isGame: false,
  proxmox: { kind: "vm", status: "running" },
  runtime: null,
  activeJob: null,
  updatedAt: new Date(NOW.getTime() - 3600_000),
  now: NOW,
};

test("state truth: agreement is healthy", () => {
  const t = evaluateStateTruth(base);
  assert.equal(t.health, "ok");
  assert.equal(t.mismatches.length, 0);
  assert.deepEqual(t.sources.map((s) => s.key), ["db", "proxmox"]);
});

test("state truth: DB RUNNING but VM stopped is critical with a reconcile fix", () => {
  const t = evaluateStateTruth({ ...base, proxmox: { kind: "vm", status: "stopped" } });
  assert.equal(t.health, "bad");
  assert.equal(t.mismatches[0].code, "db_running_vm_stopped");
  assert.equal(t.mismatches[0].fix, "reconcile");
});

test("state truth: suspended server whose VM runs is critical (suspension not enforced)", () => {
  const t = evaluateStateTruth({ ...base, dbStatus: "SUSPENDED" });
  assert.ok(t.mismatches.some((m) => m.code === "suspended_vm_running" && m.severity === "critical"));
});

test("state truth: missing VM and unreachable node are distinguished; unreachable is never a mismatch", () => {
  assert.ok(evaluateStateTruth({ ...base, proxmox: { kind: "missing" } }).mismatches.some((m) => m.code === "vm_missing"));
  const u = evaluateStateTruth({ ...base, proxmox: { kind: "unreachable", error: "timeout" } });
  assert.ok(u.mismatches.every((m) => m.severity === "info"));
  assert.equal(u.health, "unknown");
});

test("state truth: game down inside a running VM warns unless the owner asked for stop", () => {
  const probedAt = new Date(NOW.getTime() - 60_000);
  const down = evaluateStateTruth({ ...base, isGame: true, runtime: { state: "crashed", probedAt, intent: "running" } });
  assert.ok(down.mismatches.some((m) => m.code === "game_down" && m.fix === "restart_game"));
