for (const file of ["actions-admin-server.ts", "actions-admin-client.ts"]) {
  const SRC = stripComments(readFileSync(join(import.meta.dirname, "..", "lib", file), "utf8"));
  const exported = [...SRC.matchAll(/export\s+async\s+function\s+([A-Za-z0-9_]+)\s*\(/g)].map((m) => ({ name: m[1], index: m.index! }));
  const body = (name: string) => {
    const at = SRC.indexOf(`export async function ${name}(`);
    const next = SRC.indexOf("export async function", at + 10);
    return SRC.slice(at, next < 0 ? undefined : next);
  };

  test(`${file}: "use server" and gate() = requireArea + assertNotImpersonating`, () => {
    assert.ok(SRC.trimStart().startsWith('"use server"'));
    const m = /async function gate\([^)]*\)\s*\{([\s\S]*?)\n\}/.exec(SRC);
    assert.ok(m, "gate() exists");
    assert.match(m![1], /requireArea\(/);
    assert.match(m![1], /assertNotImpersonating\(/);
  });

  test(`${file}: every export opens with gate()`, () => {
    assert.ok(exported.length >= 6, `found ${exported.length}`);
    const offenders = exported.filter(({ name }) => !/\)\s*(:\s*Promise<[\s\S]*?>)?\s*\{\s*\n\s*const admin = await gate\(/.test(body(name).slice(0, 600))).map((e) => e.name);
    assert.deepEqual(offenders, []);
  });

  test(`${file}: every mutating export writes an audit row`, () => {
    const readOnly = new Set(["adminPreviewMove", "adminPreviewMerge"]);
    const offenders = exported.filter(({ name }) => !readOnly.has(name) && !/await audit\(|admin\.client\.account_deleted/.test(body(name))).map((e) => e.name);
    assert.deepEqual(offenders, []);
  });

  test(`${file}: every export rate-limits`, () => {
    const exempt = new Set(["adminClearCustomerFlag"]);
    const offenders = exported.filter(({ name }) => !exempt.has(name) && !/limited\(/.test(body(name))).map((e) => e.name);
    assert.deepEqual(offenders, []);
  });
}

test("destructive server actions check the typed hostname server-side", () => {
  const SRC = stripComments(readFileSync(join(import.meta.dirname, "..", "lib", "actions-admin-server.ts"), "utf8"));
  for (const name of ["adminDeleteServer", "adminReinstallServer", "adminRestoreBackup", "adminRollbackMove", "adminCleanupMove"]) {
    const at = SRC.indexOf(`export async function ${name}(`);
    const next = SRC.indexOf("export async function", at + 10);
    assert.match(SRC.slice(at, next), /deleteConfirmMatches\(/, name);
  }
  const run = SRC.slice(SRC.indexOf("export async function adminRunMove("));
  assert.match(run.slice(0, 2000), /!opts\.dryRun && !deleteConfirmMatches/);
  assert.match(SRC, /adminSnapshotAction[\s\S]*?op !== "create" && typedConfirm\.trim\(\) !== name/);
});

test("credential reveal never puts the secret in the audit detail", () => {
  const SRC = stripComments(readFileSync(join(import.meta.dirname, "..", "lib", "actions-admin-server.ts"), "utf8"));
  const at = SRC.indexOf("export async function adminRevealRootPassword(");
  const fn = SRC.slice(at, SRC.indexOf("export async function", at + 10));
  const auditCall = /await audit\(([\s\S]*?)\);/.exec(fn)![1];
  assert.doesNotMatch(auditCall, /\bpw\b|password\s*\}/);
});

test("account delete demands email + DELETE + no owned products", () => {
  const SRC = stripComments(readFileSync(join(import.meta.dirname, "..", "lib", "actions-admin-client.ts"), "utf8"));
  const at = SRC.indexOf("export async function adminDeleteAccount(");
  const fn = SRC.slice(at, SRC.indexOf("export async function", at + 10) < 0 ? undefined : SRC.indexOf("export async function", at + 10));
