// Admin pages smoke + screenshots against the agent dev server (throwaway DB).
// usage: node smoke.mjs <base> <outdir> <route,...> [modes=desktop-dark,mobile-dark]
import { chromium } from "/opt/nxeon/node_modules/playwright/index.mjs";
import { SignJWT } from "/opt/nxeon/node_modules/jose/dist/webapi/index.js";
import fs from "node:fs";
import path from "node:path";

const [base, outdir, routesArg, modesArg = "desktop-dark,mobile-dark"] = process.argv.slice(2);
const env = Object.fromEntries(
  fs.readFileSync("/opt/nxeon-wt-adminpages/.env", "utf8").split("\n").filter((l) => /^[A-Z_]+=/.test(l))
    .map((l) => { const i = l.indexOf("="); return [l.slice(0, i), l.slice(i + 1).replace(/^"|"$/g, "")]; }),
);
const routes = routesArg.split(",");
const modes = modesArg.split(",");
fs.mkdirSync(outdir, { recursive: true });
const token = await new SignJWT({ sub: process.env.USER_ID, sv: 0, typ: "session" }).setProtectedHeader({ alg: "HS256" }).setIssuedAt().setExpirationTime("1d").sign(new TextEncoder().encode(env.AUTH_SECRET));
const cookieName = env.NXEON_COOKIE_NAME ?? "nxeon_session";

const browser = await chromium.launch();
const results = [];
for (const mode of modes) {
  const [dev, theme] = mode.split("-");
  const ctx = await browser.newContext({ viewport: dev === "mobile" ? { width: 390, height: 844 } : { width: 1440, height: 900 }, deviceScaleFactor: 1 });
  const u = new URL(base);
  await ctx.addCookies([{ name: cookieName, value: token, domain: u.hostname, path: "/" }]);
  await ctx.addInitScript((t) => { try { localStorage.setItem("nxeon.admin.theme", t); } catch {} }, theme);
  for (const r of routes) {
    const page = await ctx.newPage();
    const errors = [];
    page.on("console", (m) => { if (m.type() === "error") errors.push(m.text().slice(0, 300)); });
    page.on("pageerror", (e) => errors.push("PAGEERROR " + String(e).slice(0, 300)));
    let status = 0;
    try {
      const resp = await page.goto(base + r, { waitUntil: "domcontentloaded", timeout: 240000 });
      status = resp?.status() ?? 0;
      await page.waitForLoadState("networkidle", { timeout: 30000 }).catch(() => {});
      await page.waitForTimeout(800);
    } catch (e) { errors.push("NAV " + String(e).slice(0, 200)); }
    const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth).catch(() => -1);
    const bodyText = await page.evaluate(() => document.body.innerText.slice(0, 20000)).catch(() => "");
    const errorBoundary = /Application error|Unhandled Runtime Error|Something went wrong/i.test(bodyText);
    const name = (r.replace(/[^a-z0-9]+/gi, "_").replace(/^_|_$/g, "") || "home") + `.${mode}.png`;
    await page.screenshot({ path: path.join(outdir, name), fullPage: true }).catch(() => {});
    results.push({ mode, route: r, status, errors: [...new Set(errors)], overflow, errorBoundary });
    console.log(`${status} ${mode} ${r} errs=${errors.length} overflowX=${overflow} boundary=${errorBoundary}`);
    for (const e of [...new Set(errors)].slice(0, 3)) console.log("   ", e);
    await page.close();
  }
  await ctx.close();
}
await browser.close();
fs.writeFileSync(path.join(outdir, "results.json"), JSON.stringify(results, null, 2));

