// Functional clicks against the agent dev server (throwaway DB only).
import { chromium } from "/opt/nxeon/node_modules/playwright/index.mjs";
import { SignJWT } from "/opt/nxeon/node_modules/jose/dist/webapi/index.js";
import fs from "node:fs";

const [base, outdir] = process.argv.slice(2);
const env = Object.fromEntries(fs.readFileSync("/opt/nxeon-wt-adminpages/.env", "utf8").split("\n").filter((l) => /^[A-Z_]+=/.test(l)).map((l) => { const i = l.indexOf("="); return [l.slice(0, i), l.slice(i + 1)]; }));
const token = await new SignJWT({ sub: process.env.USER_ID, sv: 0, typ: "session" }).setProtectedHeader({ alg: "HS256" }).setIssuedAt().setExpirationTime("1d").sign(new TextEncoder().encode(env.AUTH_SECRET));
const S1 = process.env.S1, FR = process.env.FR, DEL = process.env.DEL;
const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
await ctx.addCookies([{ name: "nxeon_session", value: token, domain: "localhost", path: "/" }, { name: "nxeon_cookie_consent", value: "essential", domain: "localhost", path: "/" }]);
const page = await ctx.newPage();
const log = (...a) => console.log("RESULT", ...a);
const errs = [];
page.on("pageerror", (e) => errs.push(String(e).slice(0, 200)));

async function go(p) { await page.goto(base + p, { waitUntil: "domcontentloaded", timeout: 240000 }); await page.waitForLoadState("networkidle", { timeout: 30000 }).catch(() => {}); }

try {
  // 1. Reveal root password with reason
  await go(`/admin/servers/${S1}?tab=access`);
  await page.getByRole("button", { name: "Reveal root password…" }).click();
  await page.getByPlaceholder("e.g. ticket #1234 — customer asked").fill("ticket #42 verify");
  await page.getByRole("button", { name: "Reveal root password…" }).last().click();
  await page.waitForTimeout(2500);
  log("reveal shows password:", (await page.locator("code", { hasText: "fixture-root-pw" }).count()) > 0);
  await page.screenshot({ path: `${outdir}/interact_reveal.png`, fullPage: false });

  // 2. Delete confirmation: wrong hostname keeps button disabled
  await go(`/admin/servers/${DEL}?tab=danger`);
  await page.getByRole("button", { name: "Delete server…" }).click();
  await page.getByPlaceholder("e.g. ticket #1234 — customer asked").fill("test teardown");
  const inputs = page.locator('input[autocomplete="off"]');
  await inputs.last().fill("wrong-name");
  const confirm = page.getByRole("button", { name: "Delete server…" }).last();
  log("delete disabled with wrong hostname:", await confirm.isDisabled());
  await inputs.last().fill("fleet-24");
  log("delete enabled with right hostname:", !(await confirm.isDisabled()));
  await page.screenshot({ path: `${outdir}/interact_delete_confirm.png`, fullPage: true });
  await confirm.click();
  await page.waitForURL(/\/admin\/servers(\?|$)/, { timeout: 60000 }).catch(() => {});
  log("after delete url:", page.url().replace(base, ""));

  // 3. Add a flag on the fraud account
  await go(`/admin/users/${FR}?tab=profile`);
  await page.getByRole("button", { name: "Add flag…" }).click();
  await page.locator("select[aria-label=Flag]").selectOption("do_not_refund");
  await page.getByPlaceholder("Why (shown with the flag)").fill("refund abuse");
  await page.getByRole("button", { name: "Add flag…" }).last().click();
  await page.waitForTimeout(2500);
  log("flag visible:", (await page.getByText("Do not refund").count()) > 0);

  // 4. Fleet bulk reconcile on 2 rows + CSV export
  await go(`/admin/servers?q=fleet-0`);
  const boxes = page.getByRole("checkbox", { name: "Select row" });
  await boxes.nth(0).check(); await boxes.nth(1).check();
  await page.getByRole("button", { name: "Reconcile status" }).click();
  await page.waitForTimeout(6000);
  log("bulk msg:", (await page.locator('[role=status],[role=alert]').allInnerTexts()).join(" | ").slice(0, 200));
  const csv = await page.request.get(base + "/api/admin/servers/export?q=fleet-0");
  const body = await csv.text();
  log("csv status", csv.status(), "lines", body.split("\r\n").length, "header", body.split("\r\n")[0].slice(0, 80));

  // 5. Keyboard: arrow through the tab bar
  await go(`/admin/servers/${S1}`);
  await page.locator('[data-testid=tabbar] a').first().focus();
  await page.keyboard.press("ArrowRight"); await page.keyboard.press("ArrowRight");
  log("focused tab after 2x ArrowRight:", await page.evaluate(() => document.activeElement?.textContent));
} catch (e) {
  log("FAILED", String(e).slice(0, 400));
  await page.screenshot({ path: `${outdir}/interact_fail.png`, fullPage: true }).catch(() => {});
}
log("pageerrors", JSON.stringify(errs));
await browser.close();

